class RecordedProviderRouteInsertionService:
    """Deterministic test double for the write-before-route-matrix gate."""

    def __init__(self, *, passed: bool = True, failure_reason: Optional[str] = None):
        self.passed = passed
        self.failure_reason = failure_reason
        self.calls: list[dict[str, Any]] = []
        self._service = ProviderRouteInsertionService()

    def evaluate(self, **kwargs):
        self.calls.append(kwargs)
        if self.passed:
            return self._service.evaluate(**kwargs)
        return SimpleNamespace(
            passed=False,
            failure_reason=self.failure_reason,
            to_dict=lambda: {
                "status": "failed",
                "failureReason": self.failure_reason,
                "networkVerified": False,
                "detourLevel": "unacceptable",
                "generalizedCostDelta": None,
                "detourRatio": None,
                "timeWindowFeasible": False,
                "routeDecisionContract": copy.deepcopy(kwargs.get("route_decision_contract")),
                "legs": {},
            },
        )


def canonical_server_route_decision_contract() -> dict:
    """Server-owned route policy used only by successful Agent fixtures."""

    contract = AgentService._compile_route_decision_contract(
        request_text="公交地铁优先，绕路最多20分钟，绕路比例最多20%",
        experience_specs=[],
    )
    assert contract["status"] == "ready"
    return contract


def test_qualitative_locality_compiles_frozen_5km_45min_adjacent_contract() -> None:
    contract = AgentService._compile_route_decision_contract(
        request_text=("公交地铁优先，尽量少绕路，但景点间的距离不要间隔太远了；绕路最多10分钟，绕路比例最多20%"),
        experience_specs=[],
    )

    assert contract["status"] == "ready"
    assert contract["adjacentLegConstraint"] == {
        "candidateSearchRadiusMeters": 5000.0,
        "maxProviderTravelMinutes": 45.0,
    }
    assert contract["adjacentLegConstraintSource"] == "versioned_product_policy_for_qualitative_user_constraint"
    assert contract["detourTolerance"] == {
        "maxGeneralizedCostDelta": 10.0,
        "maxDetourRatio": 0.2,
    }
    assert RouteInsertionScorer.normalized_route_decision_contract(contract) is not None


def test_strict_structured_detour_choice_compiles_frozen_compact_route_policy() -> None:
    """A persisted strict choice must not fall back to citywide POI ordering.

    The Controller owns the relative tolerance numbers, while the server-owned
    product policy supplies the bounded adjacent search and Provider-leg cap.
    This is the trace-shaped path where the user selected the structured
    ``尽量少绕路`` option instead of entering equivalent free text.
    """

    contract = AgentService._compile_route_decision_contract(
        request_text="公交地铁优先",
        experience_specs=[],
        existing_contract={
            "detourTolerance": {
                "maxGeneralizedCostDelta": 15,
                "maxDetourRatio": 0.15,
            },
            "detourToleranceSource": "controller_semantic_choice",
        },
    )

    assert contract["status"] == "ready"
    assert contract["schemaVersion"] == "route-decision-contract-v2"
    assert contract["adjacentLegConstraint"] == {
        "candidateSearchRadiusMeters": 5000.0,
        "maxProviderTravelMinutes": 45.0,
    }
    assert contract["adjacentLegConstraintSource"] == "versioned_product_policy_for_strict_detour_tolerance"
    assert contract["topologyConstraint"] == {"maxBacktrackRatio": 0.15}
    assert contract["detourTolerance"] == {
        "maxGeneralizedCostDelta": 15.0,
        "maxDetourRatio": 0.15,
    }


