@pytest.fixture(autouse=True)
def deterministic_provider_route_matrix(monkeypatch):
    """Make route proofs use fresh, canonical Provider legs in this unit file."""

    calls: list[dict[str, Any]] = []

    def build_routes(
        _self,
        plan_id,
        pois,
        transport_mode="transit",
        segments=None,
        route_pairs=None,
        **_kwargs,
    ):
        segments = list(segments or [])
        segment_by_id = {segment.id: segment for segment in segments}
        pairs = list(route_pairs or [])
        if not pairs:
            pairs = [
                (left.id, right.id)
                for left, right, _left_poi, _right_poi in _self._route_groups(list(pois or []), segments)
                if left is not None and right is not None
            ]
        poi_by_id = {poi.id: poi for poi in pois or []}
        calls.append({"planId": str(plan_id), "pairs": list(pairs), "mode": transport_mode})
        routes = []
        for index, (left_id, right_id) in enumerate(pairs):
            left = segment_by_id[left_id]
            right = segment_by_id[right_id]
            left_poi = poi_by_id[left.poi_id]
            right_poi = poi_by_id[right.poi_id]
            if None in {
                left_poi.longitude,
                left_poi.latitude,
                right_poi.longitude,
                right_poi.latitude,
            }:
                continue
            routes.append(
                RouteOption(
                    id=f"route_agent_service_fixture_{index}_{left_id}_{right_id}",
                    plan_id=plan_id,
                    from_segment_id=left_id,
                    to_segment_id=right_id,
                    from_poi_id=left.poi_id,
                    to_poi_id=right.poi_id,
                    distance_meters=(480 if str(plan_id).endswith("_baseline") else 240),
                    duration_seconds=(240 if str(plan_id).endswith("_baseline") else 120),
                    mode=transport_mode,
                    provider="amap-webservice",
                    is_selected=True,
                    polyline=[
                        [left_poi.longitude, left_poi.latitude],
                        [right_poi.longitude, right_poi.latitude],
                    ],
                    steps=[],
                    provider_payload={
                        "walkingDistanceMeters": 0,
                        "transferCount": 0,
                        "waitSeconds": 0,
                        "riskPenaltyMinutes": 0,
                    },
                    queried_at=datetime.now(timezone.utc),
                )
            )
        return routes

    monkeypatch.setattr(RouteService, "build_routes", build_routes)
    return calls


def apply_recorded_agent_patch(
    connection: sqlite3.Connection,
    plan_id: str,
    operations: list[ItineraryPatchOperation],
    **kwargs,
):
    """Apply one successful Agent seed with explicit server route authority."""

    kwargs.setdefault("source_type", "agent")
    kwargs.setdefault("server_route_decision_contract", canonical_server_route_decision_contract())
    return ItineraryPatchService(connection).apply_patch(plan_id, operations, **kwargs)


def record_completed_night_experience_context(
    connection: sqlite3.Connection,
    session_id: str,
    *,
    allowed_day_numbers: list[int],
    frequency: str = "one_selected_day",
    trip_day_count: Optional[int] = None,
    source_request_override: Optional[str] = None,
) -> dict:
    """Persist a deterministic controller-owned night ExperienceSpec.

    Local timeline-command tests start after the user already completed the
    dynamic clarification flow.  Record that server envelope explicitly so
    candidate discovery and route decisions never depend on a hidden default
    family or on presentation text.
    """

    service = AgentService(connection)
    day_count = max(int(trip_day_count or 0), max(allowed_day_numbers))
    resolved_dates = {
        "status": "resolved",
        "dayCount": day_count,
        "dates": [f"2026-10-{day_number:02d}" for day_number in range(1, day_count + 1)],
        "startDate": "2026-10-01",
        "endDate": f"2026-10-{day_count:02d}",
    }
    source_request = source_request_override or route_ready_request(f"北京{day_count}日游，晚上看城市夜景")
    base_contract = service._request_intent_contract(
        source_request,
        resolved_dates,
        SimpleNamespace(meal_slots=[]),
    )
    experience_spec = {
        "intentType": "night_view",
        "frequency": frequency,
        "allowedDayNumbers": list(allowed_day_numbers),
        "experienceFamilies": [
            "public_city_view",
            "waterfront_evening",
            "historic_lit_street",
        ],
        "accessPolicy": "public_outdoor_or_verified_controlled_access",
        "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
        "timeWindow": {"start": "18:30", "end": "22:00"},
        "detourTolerance": {
            "maxGeneralizedCostDelta": 35,
            "maxDetourRatio": 0.35,
        },
        "evidenceFreshness": {
            "maxAgeHours": 24,
            "requiredForControlledAccess": True,
        },
        "confidence": 0.95,
        "unresolvedDimensions": [],
    }
    source_turn_id = f"turn_recorded_experience_{session_id}"
    checkpoint = {
        "schemaVersion": ClarificationCheckpointService.SCHEMA_VERSION,
        "checkpointId": f"clarify_recorded_{session_id}",
        "planningRootId": f"planning_root_recorded_{session_id}",
        "requestFingerprint": ClarificationCheckpointService._fingerprint(base_contract),
        "contractVersion": 3,
        "ambiguities": [
            {
                "dimensionId": "night_view.cardinality",
                "resolved": True,
                "answerSource": "recorded_controller_fixture",
            },
            {
                "dimensionId": "night_view.experience_mode",
                "resolved": True,
                "answerSource": "recorded_controller_fixture",
            },
        ],
        "resolvedAnswers": [
            {
                "dimensionId": "night_view.cardinality",
                "semanticValue": {
                    "frequency": frequency,
                    "allowedDayNumbers": list(allowed_day_numbers),
                },
                "source": "recorded_controller_fixture",
                "sourceUserTurnId": f"user_recorded_{session_id}",
            },
            {
                "dimensionId": "night_view.experience_mode",
                "semanticValue": {
                    key: copy.deepcopy(value)
                    for key, value in experience_spec.items()
                    if key
                    in {
                        "experienceFamilies",
                        "accessPolicy",
                        "distinctnessPolicy",
                        "timeWindow",
                        "detourTolerance",
                        "evidenceFreshness",
                        "confidence",
                    }
                },
                "source": "recorded_controller_fixture",
                "sourceUserTurnId": f"user_recorded_{session_id}",
            },
        ],
        "experienceSpecs": [copy.deepcopy(experience_spec)],
        "candidateGapSummary": {},
        "nextQuestionDimensionId": None,
        "completionCriteria": copy.deepcopy(base_contract.get("completionCriteria") or []),
        "status": "answered",
        "sourceUserTurnId": f"user_recorded_{session_id}",
        "sourceAssistantTurnId": source_turn_id,
    }
    checkpoint["fingerprint"] = ClarificationCheckpointService._fingerprint(checkpoint)
    final_contract = service._request_contract_after_clarification(
        base_contract,
        checkpoint,
        {
            "effectiveUserMessage": source_request,
            "resolvedTripDates": resolved_dates,
        },
    )
    assert final_contract["clarificationRequired"] is False
    assert final_contract["experienceSpecs"][0]["unresolvedDimensions"] == []
    assert final_contract["routeDecisionContract"]["status"] == "ready"

    session = connection.execute(
        "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
        (session_id,),
    ).fetchone()
    assert session is not None
    request_envelope = {
        "sourceUserRequest": source_request,
        "effectiveUserMessage": source_request,
        "resolvedTripDates": resolved_dates,
        "requestIntentContract": final_contract,
        "clarificationCheckpoint": checkpoint,
        "experienceSpecs": [experience_spec],
        "activeVersionId": session["active_version_id"],
        "currentUserTurnId": f"user_recorded_{session_id}",
    }
    now = datetime.now(timezone.utc).isoformat()
    connection.execute(
        """
        INSERT INTO conversation_turns (
            id, session_id, role, content, turn_index, status,
            itinerary_version_id, agent_request_json, agent_response_json,
            created_at, updated_at
        ) VALUES (?, ?, 'assistant', ?, 1, 'active', ?, ?, ?, ?, ?)
        """,
        (
            source_turn_id,
            session_id,
            "已按 Agent 语义选择记录完整夜景体验合同。",
            session["active_version_id"],
            json.dumps(request_envelope, ensure_ascii=False),
            json.dumps(
                {
                    "clarificationCheckpoint": checkpoint,
                    "experienceSpecs": [experience_spec],
                },
                ensure_ascii=False,
            ),
            now,
            now,
        ),
    )
    connection.commit()
    return request_envelope


