def _intent_contract_for_test_context(context: dict) -> dict:
    message = str(context.get("message") or "")
    state = context.get("state") if isinstance(context.get("state"), dict) else {}
    if state.get("hasUnansweredClarification"):
        intent = "clarification_answer"
        requested_scope = "clarification"
    elif any(marker in message for marker in ("重试", "再试", "重新来")):
        intent = "retry_current_stage"
        requested_scope = "current_stage"
    elif state.get("hasActiveVersion"):
        intent = "modify_itinerary"
        requested_scope = "active_itinerary"
    else:
        intent = "create_itinerary"
        requested_scope = "new_itinerary"
    return {
        "intent": intent,
        "confidence": 0.99,
        "requestedScope": requested_scope,
        "isQuestion": False,
        "isNegated": "不要" in message or "别" in message,
    }


def _install_intent_contract(provider):
    inherited = provider.decide_autonomy_lite

    def decide_autonomy_lite(context, *, timeout_seconds):
        if context.get("schemaVersion") == "conversation-intent-context-v1":
            return _intent_contract_for_test_context(context)
        return inherited(context, timeout_seconds=timeout_seconds)

    provider.decide_autonomy_lite = decide_autonomy_lite
    return provider


class IntentContractProviderMixin:
    """Keep legacy business-controller doubles honest at the new intent seam."""

    def decide_autonomy_lite(self, context, *, timeout_seconds):
        if context.get("schemaVersion") != "conversation-intent-context-v1":
            inherited = getattr(super(), "decide_autonomy_lite", None)
            if callable(inherited):
                return inherited(context, timeout_seconds=timeout_seconds)
            raise RuntimeError("controller_provider_unavailable")
        assert timeout_seconds > 0
        return json.dumps(
            _intent_contract_for_test_context(context),
            ensure_ascii=False,
        )


class ControllerTimelineCommandProvider(IntentContractProviderMixin):
    """V3 model fixture selecting the executor-local timeline compiler."""

    def __init__(self):
        self.decision_calls = 0

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        self.decision_calls = int(getattr(self, "decision_calls", 0)) + 1
        observation = context.get("observation") if isinstance(context.get("observation"), dict) else {}
        if int(observation.get("cycleIndex") or 0) > 0:
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "finish",
                "confidence": 0.99,
                "decisionSummary": "已重新观察 timeline command 的持久化结果",
                "requiredTools": [],
                "actionDirective": {"type": "finish", "assistantReply": "已根据验证结果完成。"},
                "stopCondition": {"type": "finished"},
            }
        lineage = observation.get("versionLineage") or {}
        base_version_id = str(lineage.get("currentVersionId") or "")
        segment_ids = [
            str(item.get("segmentId"))
            for item in observation.get("segmentRefs") or []
            if isinstance(item, dict) and item.get("segmentId")
        ]
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "patch_itinerary",
            "confidence": 0.97,
            "decisionSummary": "选择受约束的 timeline command executor",
            "requiredTools": ["patch_itinerary", "resolve_poi"],
            "actionDirective": {
                "type": "patch_itinerary",
                "operationIntent": "timeline_command",
                "baseVersionId": base_version_id,
                "targetSegmentIds": segment_ids,
                "requestedOutcome": "执行用户明确的局部时间轴命令",
                "preserve": ["other_days", "other_segments"],
                "maxChangedSegmentCount": 3,
            },
            "stopCondition": {"type": "verified_patch_or_truthful_no_change"},
        }


