def clear_database() -> None:
    initialize_database()
    db_path = sqlite_path_from_url(get_settings().database_url)
    with sqlite3.connect(db_path) as connection:
        connection.executescript(
            """
            DELETE FROM agent_choice_executions;
            DELETE FROM amap_poi_candidates;
            DELETE FROM planning_runs;
            DELETE FROM travel_preference_memories;
            DELETE FROM session_preference_memories;
            DELETE FROM itinerary_patches;
            DELETE FROM itinerary_versions;
            DELETE FROM conversation_turns;
            DELETE FROM conversation_sessions;
            DELETE FROM traffic_crowding_signals;
            DELETE FROM route_options;
            DELETE FROM ticket_lookup_results;
            DELETE FROM poi_risk_alerts;
            DELETE FROM weather_signals;
            DELETE FROM itinerary_segments;
            DELETE FROM itinerary_days;
            DELETE FROM itinerary_plans;
            DELETE FROM pois;
            """
        )


def open_db() -> sqlite3.Connection:
    db_path = sqlite_path_from_url(get_settings().database_url)
    connection = sqlite3.connect(db_path, check_same_thread=False)
    connection.row_factory = sqlite3.Row
    return connection


def payload_tool_names(payload: dict) -> list[str]:
    return [tool["function"]["name"] for tool in payload.get("tools") or []]


def test_route_aware_meal_selection_uses_geometry_only_for_ranking_not_rejection():
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        itinerary_service = ItineraryService(connection)
        intent = PoiIntent(
            raw_need="午餐体验当地美食",
            city="示例市",
            day_number=1,
            time_window="12:00-13:00",
            intent_type="meal",
            specificity="functional",
            search_queries=["当地美食"],
            preferred_types=["餐饮"],
            rejected_types=["酒店"],
            candidate_hints=["特色餐厅"],
            hint_policy="llm_common_knowledge_hint",
            target_count=1,
        )
        slot = DaySlot(
            slot_id="day1_lunch",
            day_number=1,
            date=None,
            time_window="12:00-13:00",
            start_time="12:00",
            duration_minutes=60,
            kind="meal",
            raw_need="午餐体验当地美食",
            route_anchor=True,
        )
        context = FunctionalSlotContext(
            slot_id=slot.slot_id,
            day_number=1,
            intent_type="meal",
            raw_need=slot.raw_need,
            previous_anchor=POI(
                id="prev", name="上午地点", city="示例市", category="scenic", latitude=30.0, longitude=120.0
            ),
            next_anchor=POI(
                id="next", name="下午地点", city="示例市", category="scenic", latitude=30.0, longitude=120.1
            ),
            same_day_anchors=[],
            transport_mode="transit",
        )
        far = CandidateScore(synthetic_map_poi("far_meal", "远处特色餐厅", 120.45, 30.45), 0.94, {"hintMatch": 0.18})
        high = CandidateScore(synthetic_map_poi("high_meal", "略绕路特色餐厅", 120.05, 30.05), 1.0, {"hintMatch": 0.18})
        near = CandidateScore(
            synthetic_map_poi("near_meal", "路线附近传统小吃餐厅", 120.05, 30.0), 0.76, {"typeMatch": 0.22}
        )

        available = [far, high, near]
        selected = service._pop_next_pool_candidate_score(
            available,
            itinerary_service,
            intent,
            slot,
            set(),
            set(),
            [],
            "transit",
            threshold=0.72,
            slot_context=context,
            day_meal_brands=set(),
            trip_meal_brands=set(),
        )

    assert selected is high
    # Geometry may rank a bounded candidate batch but cannot declare a real
    # transit detour unacceptable before the provider route matrix is checked.
    assert "meal_detour_unacceptable" not in far.rejected_reasons
    assert far in available
    assert far.route_aware["routeInsertion"]["reason"].startswith("geometry_precheck:")
    assert getattr(high, "route_aware")["rejectedReasons"] == []
    assert getattr(high, "route_aware")["decisionRole"] == ("geometry_coarse_ordering_only")
    assert high.score == 1.0
    assert far.score == 0.94
    assert getattr(far, "route_aware")["routeInsertion"]["detourLevel"] == "high"
    assert getattr(high, "route_aware")["routeInsertion"]["detourLevel"] == "high"
    assert getattr(near, "route_aware")["routeInsertion"]["detourLevel"] == "low"


