def test_timeline_route_preflight_missing_contract_is_recoverable_zero_write():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "路线合同缺失")
        before_versions = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        before_patches = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]

        passed, proofs, failure_reason = AgentService(connection)._preflight_timeline_patch_route_matrix(
            session={
                "active_plan_id": session.active_plan_id,
                "active_version_id": session.active_version_id,
            },
            operations=[
                ItineraryPatchOperation(
                    op="replace_segment_poi",
                    segmentId="seg_missing_contract",
                    amapPoi=night_view_map_poi(
                        "B0MISSINGCONTRACT",
                        "合同待恢复观景台",
                        116.397,
                        39.923,
                    ),
                )
            ],
            request_context={},
            command=SimpleNamespace(scope="night_view"),
        )
        after_versions = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        after_patches = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]

    assert passed is False
    assert proofs == []
    assert failure_reason == "route_decision_contract_missing_or_invalid"
    assert after_versions == before_versions
    assert after_patches == before_patches


def test_timeline_route_contract_is_normalized_and_propagated_to_writer_context():
    contract = RouteInsertionScorer.build_route_decision_contract(
        source="request_intent_contract",
        provenance={"requestFingerprint": "timeline-route-contract-test"},
        detour_tolerance={
            "maxGeneralizedCostDelta": 28.0,
            "maxDetourRatio": 0.22,
        },
        mobility_profile={
            "source": "explicit_request_mobility_semantics",
            "walkingPenaltyMinutesPerKm": 1.5,
            "transferPenaltyMinutes": 4.0,
            "waitTimeMultiplier": 1.0,
            "riskPenaltyMultiplier": 1.0,
        },
    )
    assert contract is not None
    request_context = {
        "requestIntentContract": {"routeDecisionContract": contract},
        "routeInsertionProofs": [{"segmentId": "seg_target"}],
    }

    tolerance, mobility, normalized, source = AgentService._route_detour_tolerance(
        request_context,
        command=SimpleNamespace(scope="night_view"),
    )
    writer_context = object.__new__(AgentService)._timeline_command_planning_context(
        SimpleNamespace(as_dict=lambda: {"scope": "night_view"}),
        request_context=request_context,
    )

    assert tolerance == contract["detourTolerance"]
    assert mobility == contract["mobilityProfile"]
    assert normalized == contract
    assert source == "requestIntentContract.routeDecisionContract:night_view"
    assert writer_context["routeDecisionContract"] == contract
    assert writer_context["routeInsertionProofs"] == [{"segmentId": "seg_target"}]


