def test_night_view_hint_supplement_adds_city_family_diversity():
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        pool = IntentPool(
            pool_id="night_view_pool",
            raw_need="夜景观景点",
            city="北京",
            intent_type="night_view",
            target_count=1,
            preferred_types=[],
            rejected_types=[],
            route_preference={},
            assign_to_slots=["day1_night", "day2_night"],
            candidate_hints=["鸟巢", "水立方"],
            hint_policy="llm_common_knowledge_hint",
        )

        hints = service._server_candidate_hints_for_pool(pool, {"selectedCity": "北京"})

    assert service._pool_needs_server_hint_supplement(pool, pool.candidate_hints)
    # Generic creative seeds may remain, but without a controller-owned
    # ExperienceSpec the semantic family strategy itself must fail closed.
    assert hints
    assert service._night_view_semantic_search_strategies("北京", {"selectedCity": "北京"}) == []
    assert not any("公共城市夜景空间" in hint or "滨水夜间公共空间" in hint for hint in hints)
    assert not any("什刹海" in hint or "景山" in hint or "国贸" in hint for hint in hints)


