def test_agent_message_events_include_run_timing_and_persist_final_duration():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=one_day_timeline_command_snapshot())],
            source_type="agent",
        )
        streamed_events = []
        response = AgentService(connection, provider=ControllerTimelineCommandProvider()).send_message(
            session.session_id,
            AgentMessageRequest(content=route_ready_request("预算按人均显示，不要重排时间轴")),
            event_sink=streamed_events.append,
        )
        stored = connection.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()

    assert streamed_events[0].type == "agent_run"
    assert streamed_events[0].metadata["runStartedAt"]
    assert isinstance(streamed_events[0].metadata["runElapsedMs"], int)
    assert streamed_events[-1].type == "agent_run"
    assert streamed_events[-1].duration_ms >= 0
    assert streamed_events[-1].metadata["runDurationMs"] >= 0
    assert response.planning_steps[-1].type == "agent_run"
    stored_payload = json.loads(stored["agent_response_json"])
    assert stored_payload["planningSteps"][-1]["type"] == "agent_run"
    assert stored_payload["planningSteps"][-1]["durationMs"] >= 0


