def test_timeline_transport_preference_command_updates_segments_without_collecting_candidates():
    clear_database()
    request_content = route_ready_request("不要骑行，只要公交地铁，别重排景点")
    route_contract = AgentService._compile_route_decision_contract(
        request_text=request_content,
        experience_specs=[],
    )
    assert route_contract["status"] == "ready"
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=one_day_timeline_command_snapshot())],
            source_type="agent",
            server_route_decision_contract=route_contract,
        )
        response = AgentService(connection, provider=ControllerTimelineCommandProvider()).send_message(
            session.session_id,
            AgentMessageRequest(content=request_content),
        )
        transport_modes = [
            row[0]
            for row in connection.execute(
                "SELECT transport_mode FROM itinerary_segments WHERE id IN ('seg_command_1', 'seg_command_2') ORDER BY id"
            ).fetchall()
        ]
        operations = json.loads(
            connection.execute(
                "SELECT operations_json FROM itinerary_patches WHERE result_version_id = ?",
                (response.version.id,),
            ).fetchone()[0]
        )

    assert response.version is not None, response.model_dump(mode="json")
    assert transport_modes == ["public_transit", "public_transit"]
    assert "未重排景点" in response.assistant_turn.content
    assert [operation["op"] for operation in operations] == ["replace_transport_mode", "replace_transport_mode"]
    assert all(operation["value"] == "public_transit" for operation in operations)
    event_types = [event.type for event in response.planning_steps]
    assert "timeline_edit" in event_types
    assert "patch_itinerary" in event_types
    assert "collect_candidates" not in event_types
    timeline_event = next(event for event in response.planning_steps if event.type == "timeline_edit")
    preview = timeline_event.metadata["resultPreview"]
    assert preview["timelineCommand"]["scope"] == "route"
    assert preview["transportMode"] == "public_transit"
    assert preview["globalReorder"] is False
    assert preview["externalRouteRefresh"] is False


def test_timeline_meal_edit_replaces_dinner_without_tool_loop_or_search(monkeypatch):
    clear_database()
    nearby_calls: list[str] = []
    snapshot = one_day_timeline_command_snapshot()
    snapshot["days"][0]["segments"].insert(
        1,
        {
            "id": "seg_command_meal",
            "startTime": "18:00",
            "endTime": "19:00",
            "kind": "meal",
            "poi": {
                "id": "meal_placeholder",
                "name": "晚餐 当地特色美食",
                "city": "北京",
                "category": "food",
                "latitude": None,
                "longitude": None,
                "source": "agent-text-timeline",
                "confidence": 0.4,
                "photos": [],
            },
            "transportMode": "public_transit",
            "estimatedCost": 120,
            "notes": "groundingStatus：waiting_for_poi_grounding",
        },
    )

    def fake_nearby(_self, city, longitude, latitude, keyword, category="all", radius=1500, limit=8):
        nearby_calls.append(str(keyword))
        budget = current_amap_call_budget()
        if budget is not None:
            budget.try_acquire(
                endpoint="place/around", keyword=str(keyword), category=str(category), source="test_fake_nearby"
            )
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword,
            category=category,
            providerName=AMAP_PLACE_SOURCE,
            queriedAt=datetime.now(timezone.utc),
            pois=[
                MapPoiResponse(
                    id="amap_duck_1",
                    name="北京烤鸭示例店",
                    type="餐饮服务;中餐厅;烤鸭",
                    city=city,
                    district="测试区",
                    address="测试路 1 号",
                    longitude=float(longitude) + 0.001,
                    latitude=float(latitude) + 0.001,
                    category="food",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.94,
                    photos=[],
                )
            ],
        )

    def fail_search(*_args, **_kwargs):
        raise AssertionError("meal edit should not fallback to citywide search when nearby succeeds")

    monkeypatch.setattr(MapPoiService, "search_nearby", fake_nearby)
    monkeypatch.setattr(MapPoiService, "search", fail_search)
    refreshed_route_pairs: list[set[tuple[str, str]] | None] = []

    def fake_refresh_routes(self, plan_id, preferred_mode=None, route_pairs=None):
        refreshed_route_pairs.append(route_pairs)
        return ["相邻路线已刷新。"]

    def fail_optional_refresh(*_args, **_kwargs):
        raise AssertionError("deterministic timeline command should not refresh weather/ticket/risk tools")

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=snapshot)],
            source_type="agent",
        )
        monkeypatch.setattr(ItineraryService, "refresh_routes", fake_refresh_routes)
        monkeypatch.setattr(ItineraryService, "refresh_planning_tools", fail_optional_refresh)
        response = AgentService(connection, provider=ControllerTimelineCommandProvider()).send_message(
            session.session_id,
            AgentMessageRequest(content=route_ready_request("第一天我想吃北京烤鸭，只改餐饮不要重排景点")),
        )

    assert response.version is not None, response.model_dump(mode="json")
    assert nearby_calls == ["北京烤鸭"]
    day = response.itinerary.days[0]
    assert [segment.id for segment in day.segments] == ["seg_command_1", "seg_command_meal", "seg_command_2"]
    meal = next(segment for segment in day.segments if segment.id == "seg_command_meal")
    assert meal.poi.name == "北京烤鸭示例店"
    assert meal.poi.source == AMAP_PLACE_SOURCE
    assert refreshed_route_pairs == []
    event_types = [event.type for event in response.planning_steps]
    assert "timeline_edit" in event_types
    assert "collect_candidates" not in event_types
    preview = next(event for event in response.planning_steps if event.type == "timeline_edit").metadata[
        "resultPreview"
    ]
    assert preview["timelineCommand"]["scope"] == "meal"
    assert preview["changedScope"] == "day_meal_only"
    assert preview["toolLoopEntered"] is False
    assert preview["webSearchCalls"] == 0
    assert preview["ticketLookupCalls"] == 0
    assert preview["amapCallBudget"]["usedPlaceAround"] == 1


def test_timeline_remove_lunch_uses_single_remove_patch_without_provider_call():
    clear_database()
    snapshot = one_day_timeline_command_snapshot()
    snapshot["days"][0]["segments"].insert(
        1,
        {
            "id": "seg_command_lunch",
            "startTime": "12:00",
            "endTime": "13:00",
            "kind": "meal",
            "poi": amap_poi_snapshot("poi_command_lunch", "午餐京味小吃", "B000LUNCH", 116.33, 39.98),
            "transportMode": "public_transit",
            "estimatedCost": 50,
            "notes": "午餐",
        },
    )

    class FailIfCalledProvider(ControllerTimelineCommandProvider):
        def generate(self, *_args, **_kwargs):
            raise AssertionError("explicit meal deletion must not call the model")

        def run_tool_loop(self, *_args, **_kwargs):
            raise AssertionError("explicit meal deletion must not enter tool loop")

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "删除午餐")
        apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=snapshot)],
            source_type="agent",
        )
        response = AgentService(connection, provider=FailIfCalledProvider()).send_message(
            session.session_id,
            AgentMessageRequest(content="删除第一天午餐"),
        )
        operations = json.loads(
            connection.execute(
                "SELECT operations_json FROM itinerary_patches WHERE result_version_id = ?",
                (response.version.id,),
            ).fetchone()[0]
        )

    assert response.execution_mode == "deterministic_fast_path"
    assert response.version is not None
    assert [segment.id for segment in response.itinerary.days[0].segments] == ["seg_command_1", "seg_command_2"]
    assert len(operations) == 1
    assert operations[0]["op"] == "remove_segment"
    assert operations[0]["segmentId"] == "seg_command_lunch"
    preview = next(event for event in response.planning_steps if event.type == "timeline_edit").metadata[
        "resultPreview"
    ]
    assert preview["timelineCommand"]["operation"] == "remove"
    assert preview["changedScope"] == "day_meal_remove_only"
    assert preview["toolLoopEntered"] is False


