    assert sum("月坛公园观景点" in query for query in search_calls) == 1
    assert refreshed_route_pairs == []
    day2 = next(day for day in second.itinerary.days if day.day_number == 2)
    night = next(segment for segment in day2.segments if segment.id == "seg_night_d2_placeholder")
    assert night.poi.name == "月坛公园观景点"
    assert night.poi.source == AMAP_PLACE_SOURCE
    assert night.poi.map_ready is True
    assert "路线提示" in second.assistant_turn.content
    response_text = json.dumps(second.model_dump(mode="json"), ensure_ascii=False)
    assert "POI must come from AMap" not in response_text
    assert "maxToolRounds" not in response_text
    event_types = [event.type for event in second.planning_steps]
    assert "collect_candidates" not in event_types
    assert {"web_search", "ticket_lookup", "amap_weather"}.isdisjoint(set(event_types))
    preview = next(event for event in second.planning_steps if event.type == "timeline_edit").metadata["resultPreview"]
    assert preview["selectedPoiNames"] == ["月坛公园观景点"]
    assert preview["routeImpact"]["level"] in {"high", "unacceptable"}
    assert preview["toolLoopEntered"] is False
    assert "requiresCustomInput" not in json.dumps(preview, ensure_ascii=False)


