def test_timeline_night_view_provider_matrix_rejection_is_zero_write(monkeypatch):
    clear_database()

    class FailIfToolLoopProvider(ControllerTimelineCommandProvider):
        def run_tool_loop(self, *_args, **_kwargs):
            raise AssertionError("route-matrix rejection should not enter provider tool loop")

    def fake_search(_self, city, keyword, category="all", limit=12):
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword,
            category=category,
            providerName=AMAP_PLACE_SOURCE,
            queriedAt=datetime.now(timezone.utc),
            pois=[night_view_map_poi("B0NEARREJECT", "景山公园", 116.3970, 39.9237)],
        )

    def fail_refresh(*_args, **_kwargs):
        raise AssertionError("rejected route matrix must stop before the itinerary writer")

    monkeypatch.setattr(MapPoiService, "search", fake_search)
    monkeypatch.setattr(ItineraryService, "refresh_routes", fail_refresh)
    route_preflight = RecordedProviderRouteInsertionService(
        passed=False,
        failure_reason="route_delta_unacceptable",
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        initial = apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=two_day_pending_night_view_snapshot())],
            source_type="agent",
        )
        record_completed_night_experience_context(
            connection,
            session.session_id,
            allowed_day_numbers=[2],
        )
        version_count_before = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count_before = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        response = AgentService(
            connection,
            provider=FailIfToolLoopProvider(),
            provider_route_insertion_service=route_preflight,
        ).send_message(
            session.session_id,
            AgentMessageRequest(content=clarified_route_ready_request("第二天夜景改成景山公园")),
        )
        version_count_after = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count_after = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()[0]

    assert len(route_preflight.calls) == 1
    assert response.version is None
    assert response.terminal_status == "needs_confirmation"
    assert version_count_after == version_count_before
    assert patch_count_after == patch_count_before
    assert active_version_id == initial.version.id


