def test_deepseek_http_error_body_preview_redacts_credentials():
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    error = HTTPError(
        "https://api.deepseek.test/chat?key=secret-query",
        400,
        "Bad Request",
        {},
        BytesIO(
            b'{"error":"bad","api_key":"sk-test-secret","access_token=tok-secret","message":"bad"} Authorization: Bearer bearer-secret'
        ),
    )

    preview = provider._http_error_body_preview(error)

    assert "sk-test-secret" not in preview
    assert "tok-secret" not in preview
    assert "bearer-secret" not in preview
    assert "secret-query" not in preview
    assert "<redacted>" in preview


