def test_resume_failed_turn_creates_immutable_retry_user_turn_when_version_matches(monkeypatch):
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        service = AgentService(connection, provider=SimpleNamespace())
        user_turn_id = service._insert_turn(session.session_id, "user", "国庆安排北京一天", "active")
        failed_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "Agent 主循环失败",
            "failed",
            agent_request_json={"latestUserMessage": "国庆安排北京一天"},
            agent_response_json={"mode": "tool_loop_failed", "failureReason": "provider_rate_limited"},
            error_json={"message": "provider_rate_limited"},
        )
        connection.execute(
            "UPDATE conversation_turns SET itinerary_version_id = ? WHERE id = ?",
            (session_row["active_version_id"], failed_turn_id),
        )
        called: dict[str, Any] = {}

        def fake_generate(self, session_id, user_turn_id_arg, content, payload, event_sink=None):
            called["session_id"] = session_id
            called["user_turn_id"] = user_turn_id_arg
            called["content"] = content
            called["resumeFeedback"] = payload.context.model_dump(by_alias=True).get("resumeFeedback")
            return "ok"

        monkeypatch.setattr(AgentService, "_generate_for_user_turn", fake_generate)
        monkeypatch.setattr(AgentService, "_finalize_generated_response", lambda _self, _session_id, response: response)

        result = service.resume_failed_turn(session.session_id, failed_turn_id)
        retry_turn = connection.execute(
            "SELECT * FROM conversation_turns WHERE id = ?",
            (called["user_turn_id"],),
        ).fetchone()

    assert result == "ok"
    assert called["user_turn_id"] != user_turn_id
    assert called["content"] == "国庆安排北京一天"
    assert called["resumeFeedback"]["turnId"] == failed_turn_id
    assert called["resumeFeedback"]["sourceUserTurnId"] == user_turn_id
    assert called["resumeFeedback"]["retryUserTurnId"] == called["user_turn_id"]
    assert retry_turn["parent_turn_id"] == failed_turn_id
    assert retry_turn["content"] == "国庆安排北京一天"


def test_resume_failed_turn_respects_session_run_lease():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        service = AgentService(connection, provider=SimpleNamespace())
        service._insert_turn(session.session_id, "user", "国庆安排北京一天", "active")
        failed_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "Agent 主循环失败",
            "failed",
            agent_request_json={"latestUserMessage": "国庆安排北京一天"},
            agent_response_json={
                "mode": "tool_loop_failed",
                "failureReason": "provider_rate_limited",
            },
            error_json={"message": "provider_rate_limited"},
        )
        assert service._acquire_session_run_lease(session.session_id) is True
        try:
            with pytest.raises(HTTPException) as error:
                service.resume_failed_turn(session.session_id, failed_turn_id)
        finally:
            service._release_session_run_lease(session.session_id)

    assert error.value.status_code == 409
    assert error.value.detail["code"] == "run_in_progress"


def test_resume_failed_turn_preserves_failed_portfolio_and_uses_new_source_turn(monkeypatch):
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        service = AgentService(connection, provider=SimpleNamespace())
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "国庆安排北京一天",
            "active",
        )
        failed_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "Agent 主循环失败",
            "failed",
            agent_request_json={"latestUserMessage": "国庆安排北京一天"},
            agent_response_json={
                "mode": "staged_initial_pipeline_failed",
                "failureReason": "no_verified_proposal",
            },
            error_json={"message": "staged_initial_pipeline_failed"},
        )
        now = datetime.now(timezone.utc).isoformat()
        connection.execute(
            """INSERT INTO agent_plan_portfolios (
                id, session_id, source_user_turn_id, source_assistant_turn_id,
                expected_base_version_id, source_observation_fingerprint,
                request_contract_fingerprint, status, selected_proposal_id,
                dominant_proposal_id, summary_json, failure_reason, expires_at,
                created_at, updated_at
            ) VALUES (?, ?, ?, ?, NULL, ?, ?, 'failed', NULL, NULL, '{}', ?, NULL, ?, ?)""",
            (
                "portfolio_failed_empty",
                session.session_id,
                user_turn_id,
                failed_turn_id,
                "o" * 64,
                "r" * 64,
                "portfolio_anchor_target_shortfall:day_1:0/1",
                now,
                now,
            ),
        )
        connection.commit()

        def fake_generate(self, session_id, user_turn_id_arg, content, payload, event_sink=None):
            self.db.execute(
                """INSERT INTO agent_plan_portfolios (
                    id, session_id, source_user_turn_id, source_assistant_turn_id,
                    expected_base_version_id, source_observation_fingerprint,
                    request_contract_fingerprint, status, selected_proposal_id,
                    dominant_proposal_id, summary_json, failure_reason, expires_at,
                    created_at, updated_at
                ) VALUES (?, ?, ?, ?, NULL, ?, ?, 'failed', NULL, NULL, '{}', ?, NULL, ?, ?)""",
                (
                    "portfolio_retry",
                    session_id,
                    user_turn_id_arg,
                    failed_turn_id,
                    "n" * 64,
                    "f" * 64,
                    "retry_test",
                    now,
                    now,
                ),
            )
            self.db.commit()
            return "ok"

        monkeypatch.setattr(AgentService, "_generate_for_user_turn", fake_generate)
        monkeypatch.setattr(
            AgentService,
            "_finalize_generated_response",
            lambda _self, _session_id, response: response,
        )

        result = service.resume_failed_turn(session.session_id, failed_turn_id)
        portfolios = {
            row["id"]: dict(row)
            for row in connection.execute(
                "SELECT * FROM agent_plan_portfolios WHERE session_id = ?",
                (session.session_id,),
            ).fetchall()
        }
        retry_turn = connection.execute(
            "SELECT * FROM conversation_turns WHERE id = ?",
            (portfolios["portfolio_retry"]["source_user_turn_id"],),
        ).fetchone()

    assert result == "ok"
    assert set(portfolios) == {"portfolio_failed_empty", "portfolio_retry"}
    assert portfolios["portfolio_failed_empty"]["source_user_turn_id"] == user_turn_id
    assert portfolios["portfolio_failed_empty"]["failure_reason"] == ("portfolio_anchor_target_shortfall:day_1:0/1")
    assert portfolios["portfolio_retry"]["source_user_turn_id"] != user_turn_id
    assert retry_turn["parent_turn_id"] == failed_turn_id


