def test_travel_tool_registry_bounds_large_tool_result_with_runtime_limit():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        registry = TravelToolRegistry(
            connection,
            session_row,
            {
                "latestUserMessage": "查故宫预约",
                "runtimeLimits": {"maxToolResultChars": 1400},
            },
        )
        tool_def = registry.registered_tools()["web_search"]
        result = {
            "ok": True,
            "toolName": "web_search",
            "providerName": "test-search",
            "fallbackUsed": False,
            "failureReason": None,
            "confidence": 0.8,
            "query": "故宫 预约",
            "results": [
                {
                    "title": f"结果 {index}",
                    "url": f"https://example.test/{index}",
                    "snippet": "长摘要" * 500,
                    "sourceName": "example",
                    "confidence": 0.7,
                }
                for index in range(20)
            ],
        }

        bounded = registry._bounded_tool_result(tool_def, result)

    assert bounded["truncated"] is True
    assert bounded["ok"] is True
    assert bounded["query"] == "故宫 预约"
    assert bounded["resultCount"] == 20
    assert "results" not in bounded
    assert len(json.dumps(bounded, ensure_ascii=False, default=str)) <= 1400


def test_deepseek_tool_loop_context_drops_raw_map_selection_write_authority():
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    messages = provider._build_tool_messages(
        {
            "latestUserMessage": "把选中的餐厅加入第一天",
            "selectedCity": "北京",
            "selectedMapPoi": {"amapId": "amap_1", "name": "测试餐厅"},
            "selectedMapPoiId": "amap_1",
            "candidateMapPois": [{"amapId": "amap_2", "name": "备选餐厅"}],
            "candidatePoiIds": ["amap_2"],
            "pendingAmapPoiCandidates": [{"id": "cand_1", "query": "餐厅"}],
            "activeDay": 1,
            "activeSegment": "seg_1",
            "verifierFeedback": {"hardFailures": ["pending POI candidate cand_1 appears in final itinerary"]},
        }
    )
    context_payload = json.loads(messages[-1]["content"].split("\n", 1)[1])

    assert "selectedMapPoi" not in context_payload
    assert "selectedMapPoiId" not in context_payload
    assert context_payload["candidateMapPois"][0]["amapId"] == "amap_2"
    assert context_payload["candidatePoiIds"] == ["amap_2"]
    assert context_payload["pendingAmapPoiCandidates"][0]["id"] == "cand_1"
    assert context_payload["activeDay"] == 1
    assert context_payload["activeSegment"] == "seg_1"
    assert context_payload["verifierFeedback"]["hardFailures"][0].startswith("pending POI candidate")


