def test_agent_tool_loop_successful_patch_survives_later_rejected_patch_event():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=PatchThenRejectedPatchProvider()).send_message(
            session.session_id,
            AgentMessageRequest(content="帮我安排北京一天时间轴"),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        accepted_patch = connection.execute(
            """
            SELECT *
            FROM itinerary_patches
            WHERE source_turn_id = ?
              AND result_version_id = ?
              AND validation_status = 'accepted'
            """,
            (response.assistant_turn.id, response.version.id),
        ).fetchone()
        rejected_patch_count = connection.execute(
            """
            SELECT COUNT(*)
            FROM itinerary_patches
            WHERE source_turn_id = ?
              AND validation_status = 'rejected'
            """,
            (response.assistant_turn.id,),
        ).fetchone()[0]
        version = connection.execute("SELECT * FROM itinerary_versions WHERE id = ?", (response.version.id,)).fetchone()

    assert response.assistant_turn.status == "active"
    assert response.version is not None
    assert response.itinerary.title == "北京故宫 1 日游"
    assert active["active_version_id"] == response.version.id
    assert accepted_patch is not None
    assert accepted_patch["planning_run_id"] == response.planning_run.id
    assert version["source_patch_id"] == accepted_patch["id"]
    assert rejected_patch_count == 1
    verifier_event = next(event for event in response.tool_events if event.type == "verify")
    assert verifier_event.metadata["patchId"] == accepted_patch["id"]
    failed_patch_event = next(
        event for event in response.tool_events if event.label == "patch_itinerary" and event.status == "failed"
    )
    assert "activeVersionId" not in failed_patch_event.metadata.get("resultPreview", {})


