    assert all(segment.poi.confidence <= 0.45 for segment in segments)
    assert all("高德 POI 待校验" in segment.poi.source_note for segment in segments)
    assert all("开放/预约待确认" in segment.poi.source_note for segment in segments)
    assert all("校园开放、预约" in segment.notes for segment in segments)
    assert any(event.label == "read_itinerary" and event.status == "completed" for event in response.tool_events)
    assert any(event.label == "patch_itinerary" and event.status == "completed" for event in response.tool_events)
    assert not any(event.label == "服务端时间轴草稿写入" for event in response.tool_events)


