def test_agent_tool_loop_unknown_tool_allows_one_repair_then_fails_closed():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        provider = ScriptedDeepSeekProvider(
            [
                {
                    "choices": [
                        {
                            "message": {
                                "role": "assistant",
                                "content": None,
                                "tool_calls": [
                                    {
                                        "id": "call_unknown_1",
                                        "type": "function",
                                        "function": {
                                            "name": "unknown_tool",
                                            "arguments": json.dumps({"query": "故宫"}),
                                        },
                                    }
                                ],
                            }
                        }
                    ]
                },
                {
                    "choices": [
                        {
                            "message": {
                                "role": "assistant",
                                "content": None,
                                "tool_calls": [
                                    {
                                        "id": "call_unknown_2",
                                        "type": "function",
                                        "function": {
                                            "name": "unknown_tool",
                                            "arguments": json.dumps({"query": "故宫"}),
                                        },
                                    }
                                ],
                            }
                        }
                    ]
                },
                {"choices": [{"message": {"role": "assistant", "content": "工具重试仍失败，已停止。"}}]},
            ]
        )
        with pytest.raises(AgentToolLoopError) as raised:
            provider.run_tool_loop(
                {"latestUserMessage": "查询故宫"},
                TravelToolRegistry(connection, session_row, {"latestUserMessage": "查询故宫"}),
            )

    unknown_events = [event for event in raised.value.tool_events if event["toolName"] == "unknown_tool"]
    assert "unknown_tool_after_single_repair" in str(raised.value)
    assert provider.calls == 2
    assert len(unknown_events) == 2
    assert all(event["failureReason"] == "Unregistered tool: unknown_tool" for event in unknown_events)
    assert not any("相同参数执行过该工具" in str(event.get("failureReason")) for event in unknown_events)


def test_agent_tool_loop_successful_patch_reply_includes_real_tool_failure_caveat():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        provider = ScriptedDeepSeekProvider(
            [
                {
                    "choices": [
                        {
                            "message": {
                                "role": "assistant",
                                "content": None,
                                "tool_calls": [
                                    {
                                        "id": "call_unknown",
                                        "type": "function",
                                        "function": {
                                            "name": "unknown_tool",
                                            "arguments": json.dumps({"query": "故宫"}),
                                        },
                                    },
                                    {
                                        "id": "call_patch",
                                        "type": "function",
                                        "function": {
                                            "name": "patch_itinerary",
                                            "arguments": json.dumps(
                                                {"operations": [replace_itinerary_operation()]},
                                                ensure_ascii=False,
                                            ),
                                        },
                                    },
                                ],
                            }
                        }
                    ]
                }
            ]
        )
        request_context = {
            "latestUserMessage": "安排北京一天故宫行程",
            "selectedCity": "北京",
            "requestIntentContract": {
                "routeDecisionContract": canonical_server_route_decision_contract(),
            },
        }
        result = provider.run_tool_loop(
            request_context,
            TravelToolRegistry(
                connection,
                session_row,
                request_context,
                source_turn_id="assistant_caveat",
            ),
        )

    assert provider.calls == 1
    assert "已通过 patch_itinerary 写入并校验" in result.reply
    assert "同时注意" in result.reply
    assert "unknown_tool: Unregistered tool: unknown_tool" in result.reply


def test_successful_patch_hides_recovered_patch_validation_failure_from_user_reply():
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    events = [
        {
            "toolName": "patch_itinerary",
            "label": "patch_itinerary",
            "status": "failed",
            "failureReason": "replace_segment_poi requires resolved AMap POI",
            "metadata": {},
        },
        {
            "toolName": "patch_itinerary",
            "label": "patch_itinerary",
            "status": "succeeded",
            "failureReason": None,
            "metadata": {"resultPreview": {"activeVersionId": "ver_recovered"}},
        },
    ]

    provider._mark_recovered_patch_failures(events)
    reply = provider._final_reply_after_successful_patch(
        {"selectedCity": "北京"},
        {"activeVersionId": "ver_recovered", "itinerary": {"title": "北京一日游"}},
        events,
    )

    assert events[0]["metadata"]["recoveredByLaterPatch"] is True
    assert "requires resolved AMap POI" not in reply
    assert "同时注意" not in reply


