def test_dedicated_simple_continuation_rejects_cross_root_scope_before_generation(monkeypatch):
    from src.services.simple_open_direction_service import SimpleOpenDirectionService

    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "continuation scope")
        service = AgentService(connection, provider=FakeProvider("not used"))
        service.context_builder.build = lambda *_args, **_kwargs: {
            "selectedAgentChoice": {
                "action": "continue_plan_expansion",
                "choiceId": "choice_stale",
                "sourceAssistantTurnId": "turn_stale_source",
                "option": {
                    "id": "choice_stale",
                    "action": "continue_plan_expansion",
                    "scopeKind": "comparison",
                    "kind": "simple_direction_more_plans",
                    "sourceAssistantTurnId": "turn_stale_source",
                    "planningSelectionRootTurnId": "turn_current_root",
                    "rootPortfolioId": "portfolio_current",
                    "requestContractFingerprint": "current-fingerprint",
                },
            }
        }
        monkeypatch.setattr(
            SimpleOpenDirectionService,
            "latest_root",
            lambda _self, **_kwargs: {
                "planningRootId": "turn_current_root",
                "id": "portfolio_current",
                "sourceAssistantTurnId": "turn_current_source",
                "requestContractFingerprint": "current-fingerprint",
            },
        )
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()

        with pytest.raises(HTTPException) as rejected:
            service._build_request_context(
                session_row,
                "继续探索其他方向",
                AgentMessageRequest(content="继续探索其他方向"),
            )

    assert rejected.value.status_code == 409
    assert rejected.value.detail["code"] == "simple_direction_continuation_scope_invalid"


@pytest.mark.parametrize("status", ["executing", "succeeded"])
def test_dedicated_simple_continuation_allows_only_exact_existing_execution_for_stale_source(
    monkeypatch,
    status,
):
    from src.services.simple_open_direction_service import SimpleOpenDirectionService

    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "continuation replay")
        service = AgentService(connection, provider=FakeProvider("not used"))
        selected_choice = {
            "action": "continue_plan_expansion",
            "choiceId": "choice_replay",
            "sourceAssistantTurnId": "turn_prior_source",
            "option": {
                "id": "choice_replay",
                "action": "continue_plan_expansion",
                "scopeKind": "comparison",
                "kind": "simple_direction_more_plans",
                "sourceAssistantTurnId": "turn_prior_source",
                "planningSelectionRootTurnId": "turn_current_root",
                "rootPortfolioId": "portfolio_current",
                "requestContractFingerprint": "current-fingerprint",
            },
        }
        service.context_builder.build = lambda *_args, **_kwargs: {
            "selectedAgentChoice": copy.deepcopy(selected_choice)
        }
        monkeypatch.setattr(
            SimpleOpenDirectionService,
            "latest_root",
            lambda _self, **_kwargs: {
                "planningRootId": "turn_current_root",
                "id": "portfolio_current",
                "sourceAssistantTurnId": "turn_current_source",
                "requestContractFingerprint": "current-fingerprint",
            },
        )
        monkeypatch.setattr(
            service,
            "_claim_fallback_choice_execution",
            lambda *_args, **_kwargs: {"id": "choice_exec_replay", "status": status},
        )
        now = datetime.now(timezone.utc).isoformat()
        connection.execute(
            """INSERT INTO agent_choice_executions (
                id, session_id, source_turn_id, source_user_turn_id, choice_id,
                action, status, execution_turn_id, request_turn_id, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                "choice_exec_replay",
                session.session_id,
                "turn_prior_source",
                "turn_prior_user",
                "choice_replay",
                "continue_plan_expansion",
                status,
                "turn_execution",
                "turn_execution",
                now,
                now,
            ),
        )
        connection.commit()
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()

        context = service._build_request_context(
            session_row,
            "继续探索其他方向",
            AgentMessageRequest(content="继续探索其他方向"),
            current_user_turn_id="turn_execution",
        )

    assert context["fallbackChoiceExecutionClaim"]["id"] == "choice_exec_replay"
    assert context["viewResolution"]["rootPortfolioId"] == "portfolio_current"


