def test_agent_preflight_clarifies_vague_initial_request_without_calling_provider():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        provider = CountingProvider(full_itinerary_output())
        response = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(content="想出去玩"),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        planning_run = connection.execute("SELECT * FROM planning_runs").fetchone()

    assert provider.calls == 0
    assert response.version is None
    assert response.itinerary is None
    assert response.assistant_turn.content.startswith("我需要先补齐这些信息")
    assert "这次大概玩几天" in response.assistant_turn.content
    assert len(re.findall(r"^[1-3][\.、)]\s", response.assistant_turn.content, flags=re.MULTILINE)) == 0
    assert "2 天标准版" not in response.assistant_turn.content
    assert response.assistant_turn.choice_options[-1]["kind"] == "custom_input"
    assert response.assistant_turn.choice_options[1]["value"] == "2 天"
    assert response.planning_run is not None
    assert response.planning_run.run_type == "agent_clarification"
    assert response.planning_run.understood_requirements["isCompleteEnoughToPlan"] is False
    assert "travelDate" in response.planning_run.understood_requirements["missingFields"]
    assert active["active_version_id"] is None
    assert patch_count == 0
    assert planning_run["run_type"] == "agent_clarification"
    assert not any(event.type == "fallback_confirmation_offered" for event in response.planning_steps)
    assert not any("Controller 不可用" in event.detail for event in response.planning_steps)


