def test_night_view_unauthorized_draft_fails_closed_without_provider_repair_and_zero_writes():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        provider = CountingProvider(full_itinerary_output())
        response = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(
                content=(
                    "今年国庆参观北京高校两日游，第一天抵达、第二天返程，"
                    "晚上看北京夜景。10月1日到2日，中等预算，1人，"
                    "公交地铁优先。每天午餐想体验当地特色美食。"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        route_count = connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0]

    assert provider.calls == 0
    assert provider.decision_calls == 1
    assert response.version is None
    assert response.itinerary is None
    assert "夜景" not in response.assistant_turn.content
    assert response.terminal_status == "no_safe_action"
    assert "没有可安全执行的明确动作" in response.assistant_turn.content
    decision_event = next(item for item in response.planning_steps if item.type == "agent_decision")
    assert decision_event.metadata["source"] == "safe_fallback"
    assert decision_event.metadata["schemaRepairAttempts"] == 0
    assert "draft_goal_daily_cardinality_exceeded" in decision_event.metadata["controllerError"]
    assert decision_event.metadata["providerRawDecisions"][0]["primaryAction"] == "draft_itinerary"
    assert not [
        item for item in response.assistant_turn.choice_options if item.get("kind") == "clarification_checkpoint"
    ]
    assert response.planning_run is not None
    assert response.planning_run.run_type == "agent_no_safe_action"
    assert active["active_version_id"] is None
    assert (version_count, patch_count, route_count) == (0, 0, 0)


