class DynamicClarificationCheckpointProvider(IntentContractProviderMixin):
    """A deterministic controller fixture, not a business-question fallback."""

    def __init__(self):
        self.contexts = []
        self.serialized_contexts = []

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        self.contexts.append(context)
        serialized = json.loads(json.dumps(dict(context), ensure_ascii=False))
        self.serialized_contexts.append(serialized)
        answers = (
            serialized.get("clarificationCheckpoint", {}).get("resolvedAnswers", [])
            if isinstance(serialized.get("clarificationCheckpoint"), dict)
            else []
        )
        if len(answers) >= 2:
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "finish",
                "actionDirective": {
                    "type": "finish",
                    "assistantReply": "澄清合同已完整，本轮不写入时间轴。",
                },
            }
        if answers:
            checkpoint = serialized["clarificationCheckpoint"]
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "ask_user",
                "actionDirective": {
                    "type": "ask_user",
                    "question": "已确认夜间次数；每晚更偏好怎样的公共体验？",
                    "dimensionId": "night_view.experience_mode",
                    "checkpointId": checkpoint["checkpointId"],
                    "planningRootId": checkpoint["planningRootId"],
                    "requestFingerprint": checkpoint["requestFingerprint"],
                    "checkpointFingerprint": checkpoint["fingerprint"],
                    "whyItMatters": "体验方式决定候选准入、开放证据和路线绕行门槛。",
                    "allowFreeText": True,
                    "options": [
                        {
                            "id": "public_view",
                            "label": "开放的城市公共视野",
                            "semanticValue": {
                                "experienceFamilies": [
                                    "public_city_view",
                                    "waterfront_evening",
                                    "historic_lit_street",
                                ],
                                "accessPolicy": "public_outdoor_or_verified_controlled_access",
                                "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
                                "timeWindow": {"start": "18:30", "end": "22:00"},
                                "detourTolerance": {
                                    "maxGeneralizedCostDelta": 35,
                                    "maxDetourRatio": 0.35,
                                },
                                "evidenceFreshness": {
                                    "maxAgeHours": 24,
                                    "requiredForControlledAccess": True,
                                },
                                "confidence": 0.95,
                            },
                            "allowsManualInput": False,
                        },
                        {
                            "id": "manual",
                            "label": "我补充偏好",
                            "semanticValue": {
                                "experienceFamilies": ["public_city_view"],
                                "accessPolicy": "custom",
                                "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
                                "timeWindow": {"start": "18:30", "end": "22:00"},
                                "detourTolerance": {
                                    "maxGeneralizedCostDelta": 35,
                                    "maxDetourRatio": 0.35,
                                },
                                "evidenceFreshness": {
                                    "maxAgeHours": 24,
                                    "requiredForControlledAccess": True,
                                },
                                "confidence": 0.5,
                            },
                            "allowsManualInput": True,
                        },
                    ],
                },
            }
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "ask_user",
            "actionDirective": {
                "type": "ask_user",
                "question": "两天的夜间安排希望覆盖几个不同的体验？",
                "dimensionId": "night_view.cardinality",
                "whyItMatters": "频次决定需要几个不同的真实地点和几组路线证据。",
                "allowFreeText": True,
                "options": [
                    {
                        "id": "each_evening",
                        "label": "每个可用晚上各安排一次",
                        "semanticValue": {"occurrencePolicy": "every_available_evening"},
                        "allowsManualInput": False,
                    },
                    {
                        "id": "manual",
                        "label": "我补充偏好",
                        "semanticValue": {"occurrencePolicy": "custom"},
                        "allowsManualInput": True,
                    },
                ],
            },
        }


class ManualPlanningCandidateGapProvider(DynamicClarificationCheckpointProvider):
    """Deterministic controller for the complete manual candidate-gap journey."""

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        serialized = json.loads(json.dumps(dict(context), ensure_ascii=False))
        checkpoint = serialized.get("clarificationCheckpoint")
        answers = checkpoint.get("resolvedAnswers") or [] if isinstance(checkpoint, dict) else []
        resolved_dimension_ids = {
            str(item.get("dimensionId") or "")
            for item in answers
            if isinstance(item, dict) and str(item.get("dimensionId") or "")
        }
        recovery_dimension = next(
            (
                item
                for item in serialized.get("clarificationDimensions") or []
                if isinstance(item, dict) and str(item.get("dimensionId") or "") == "night_view.candidate_recovery"
            ),
            None,
        )
        candidate_gap = serialized.get("candidateGapSummary")
        if recovery_dimension is not None or (
            isinstance(candidate_gap, dict)
            and candidate_gap.get("missingOccurrenceCount")
            and candidate_gap.get("status") == "candidate_refresh_required"
        ):
            self.contexts.append(context)
            self.serialized_contexts.append(serialized)
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "ask_user",
                "actionDirective": {
                    "type": "ask_user",
                    "question": "当前夜景候选不足；下一轮允许检索哪一种精确候选范围？",
                    "dimensionId": "night_view.candidate_recovery",
                    "checkpointId": checkpoint["checkpointId"],
                    "planningRootId": checkpoint["planningRootId"],
                    "requestFingerprint": checkpoint["requestFingerprint"],
                    "checkpointFingerprint": checkpoint["fingerprint"],
                    "whyItMatters": "选择只改变下一轮候选检索范围，不会自动采用地点或写入时间轴。",
                    "allowFreeText": False,
                    "options": [
                        {
                            "id": "public_city_view_only",
                            "label": "继续只找开放城市观景点",
                            "semanticValue": {
                                "experienceFamilies": ["public_city_view"],
                                "accessPolicy": "public_outdoor",
                            },
                            "allowsManualInput": False,
                        },
                        {
                            "id": "verified_controlled_access",
                            "label": "也允许有当前开放证据的受控观景点",
                            "semanticValue": {
                                "experienceFamilies": ["public_city_view"],
                                "accessPolicy": "public_outdoor_or_verified_controlled_access",
                            },
                            "allowsManualInput": False,
                        },
                    ],
                },
            }
        if {
            "night_view.cardinality",
            "night_view.experience_mode",
        }.issubset(resolved_dimension_ids):
            self.contexts.append(context)
            self.serialized_contexts.append(serialized)
            required = [
                item
                for item in serialized.get("goalRequirements") or []
                if isinstance(item, dict) and str(item.get("goalId") or "")
            ]
            goal_ids = [str(item["goalId"]) for item in required]
            hard_goal_ids = [
                str(item["goalId"])
                for item in required
                if str(item.get("requirementLevel") or "required") not in {"soft_experience", "optional"}
            ]
            optional_goal_ids = [item for item in goal_ids if item not in hard_goal_ids]
            dates = (serialized.get("resolvedTripDates") or {}).get("dates") or ["2026-10-01", "2026-10-02"]
            intent_by_goal = {str(item["goalId"]): str(item.get("intentType") or "") for item in required}
            schedule_hints = []
            schedule_by_intent = {
                "campus_visit": ("morning", 1, "09:00", 120),
                "meal": ("noon", 2, "12:00", 75),
                "night_view": ("night", 3, None, 90),
            }
            for day_number, _date in enumerate(dates, start=1):
                for goal_id in [*hard_goal_ids, *optional_goal_ids]:
                    day_part, sequence, preferred_start_time, duration = schedule_by_intent[intent_by_goal[goal_id]]
                    schedule_hints.append(
                        {
                            "goalId": goal_id,
                            "dayNumber": day_number,
                            "dayPart": day_part,
                            "sequence": sequence,
                            "preferredStartTime": preferred_start_time,
                            "durationEstimate": {
                                "min": duration,
                                "preferred": duration,
                                "max": duration,
                            },
                            "estimateSource": "controller_estimate",
                            "confidence": 1.0,
                        }
                    )
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "draft_itinerary",
                "actionDirective": {
                    "type": "draft_itinerary",
                    "goalPriority": goal_ids,
                    "optionalExperienceBudget": len(optional_goal_ids) * len(dates),
                    "routePlanningPolicy": {
                        "objective": "least_generalized_cost",
                        "source": "controller_estimate",
                        "allowExperienceDetour": False,
                        "mobilityProfile": {
                            "transportMode": "transit",
                            "paceClass": "standard",
                        },
                        "detourEnvelope": {
                            "maxGeneralizedCostDelta": 15.0,
                            "maxDetourRatio": 0.15,
                        },
                    },
                    "occurrenceScheduleHints": schedule_hints,
                    "dayStrategies": [
                        {
                            "dayNumber": day_number,
                            "theme": "高校与公共城市夜景",
                            "requiredGoalIds": hard_goal_ids,
                            "requiredGoalCounts": {goal_id: 1 for goal_id in hard_goal_ids},
                            "optionalGoalIds": optional_goal_ids,
                            "pace": "standard",
                            "maxRouteAnchors": 6,
                        }
                        for day_number, _date in enumerate(dates, start=1)
                    ],
                },
            }
        decision = super().decide_autonomy(
            context,
            timeout_seconds=timeout_seconds,
            repair_feedback=repair_feedback,
        )
        directive = decision.get("actionDirective") if isinstance(decision.get("actionDirective"), dict) else {}
        if directive.get("dimensionId") == "night_view.experience_mode":
            option = next(item for item in directive.get("options") or [] if item.get("id") == "public_view")
            option["semanticValue"]["experienceFamilies"] = ["public_city_view"]
        return decision

    def generate_initial_plan(self, context):
        self.contexts.append(context)
        return json.dumps(two_day_initial_day_slot_output(), ensure_ascii=False)

    def run_tool_loop(self, _context, _tool_registry):
        raise AssertionError("manual candidate-gap journey must remain in the staged pipeline")


class RouteDecisionDetourClarificationProvider(IntentContractProviderMixin):
    """Controller fixture for one request-level typed route decision."""

    def __init__(self, *, max_detour_ratio: float = 0.23):
        self.max_detour_ratio = max_detour_ratio
        self.contexts = []
        self.serialized_contexts = []

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        self.contexts.append(context)
        serialized = json.loads(json.dumps(dict(context), ensure_ascii=False))
        self.serialized_contexts.append(serialized)
        checkpoint = serialized.get("clarificationCheckpoint")
        answers = checkpoint.get("resolvedAnswers") or [] if isinstance(checkpoint, dict) else []
        if any(
            isinstance(item, dict) and item.get("dimensionId") == "route_decision.detour_tolerance" for item in answers
        ):
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "finish",
                "actionDirective": {
                    "type": "finish",
                    "assistantReply": "路线容忍度已按结构化选择确认；本轮不写时间轴。",
                },
            }
        checkpoint_identity = (
            {
                "checkpointId": str(checkpoint.get("checkpointId") or ""),
                "planningRootId": str(checkpoint.get("planningRootId") or ""),
                "requestFingerprint": str(checkpoint.get("requestFingerprint") or ""),
                "checkpointFingerprint": str(checkpoint.get("fingerprint") or ""),
            }
            if isinstance(checkpoint, dict) and checkpoint
            else {}
        )
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "ask_user",
            "actionDirective": {
                "type": "ask_user",
                "question": "这次行程可接受多大的路线绕行？",
                "dimensionId": "route_decision.detour_tolerance",
                "whyItMatters": "该数值只用于比较真实 Provider 路线矩阵，不会直接修改时间轴。",
                # Reproduce the live Controller drift from run -01.  The server
                # signer must narrow this persisted-option-only dimension.
                "allowFreeText": True,
                **checkpoint_identity,
                "options": [
                    {
                        "id": "bounded_detour",
                        "label": "较少绕行",
                        "semanticValue": {
                            "detourTolerance": {
                                "maxGeneralizedCostDelta": 27.5,
                                "maxDetourRatio": self.max_detour_ratio,
                            }
                        },
                        "allowsManualInput": False,
                    },
                    {
                        "id": "wider_detour",
                        "label": "可接受更多绕行",
                        "semanticValue": {
                            "detourTolerance": {
                                "maxGeneralizedCostDelta": 41.25,
                                "maxDetourRatio": 0.61,
                            }
                        },
                        "allowsManualInput": False,
                    },
                ],
            },
        }

    def generate(self, context):
        raise AssertionError("route-decision clarification must not enter itinerary generation")


