def test_manual_planning_candidate_gap_keeps_exact_scope_and_returns_typed_clarification(monkeypatch):
    clear_database()
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: True)

    def weak_public_city_view_search(_self, city, keyword, category="all", limit=10):
        keyword_text = str(keyword)
        if any(marker in keyword_text for marker in ("夜景", "观景", "夜游", "灯光")):
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword_text,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[
                    MapPoiResponse(
                        id="B0WEAKPARK1",
                        name="测试水岸湿地公园",
                        type="风景名胜;公园广场;公园",
                        city=city,
                        district="测试区",
                        address="测试地址",
                        longitude=116.31,
                        latitude=39.91,
                        category="scenic",
                        source=AMAP_PLACE_SOURCE,
                        sourceNote="高德 WebService POI 搜索",
                        confidence=0.94,
                        photos=[],
                    )
                ],
            )
        return fake_amap_search_with_keyword_candidate(_self, city, keyword, category, limit)

    monkeypatch.setattr(MapPoiService, "search", weak_public_city_view_search)
    monkeypatch.setattr(MapPoiService, "search_nearby", fake_amap_search_nearby_route_compatible)

    def deterministic_candidate_gap(self, **kwargs):
        report = copy.deepcopy(kwargs["grounding_report"])
        request_context = kwargs["request_context"]
        night_goal = next(
            item
            for item in request_context["requestIntentContract"]["requiredIntents"]
            if item["intentType"] == "night_view"
        )
        target = int(night_goal["requiredMin"])
        report["resultState"] = "candidate_refresh_required"
        report["rootGlobalBlocker"] = {
            "kind": "required_goal_gap",
            "status": "candidate_refresh_required",
            # This is the production regression shape from the manual journey:
            # the root projection retained missingCount but discarded the
            # occurrence target/day/scope that still exists below.
            "goals": [
                {
                    "goalId": night_goal["goalId"],
                    "intentType": "night_view",
                    "missingCount": 1,
                }
            ],
        }
        report["blockingRequiredIntents"] = [
            {
                "goalId": night_goal["goalId"],
                "intentType": "night_view",
                "target": target,
                "resolved": target - 1,
                "missingCount": 1,
                "allowedDayNumbers": list(night_goal["allowedDayNumbers"]),
            }
        ]
        return self._uncreated_staged_pipeline_response(
            kwargs["session_id"],
            kwargs["user_turn_id"],
            kwargs["assistant_turn_id"],
            kwargs["content"],
            request_context,
            kwargs["session_before"],
            kwargs["tool_events"],
            "candidate_refresh_required",
            report,
        )

    monkeypatch.setattr(AgentService, "_stage_creative_portfolio_response", deterministic_candidate_gap)
    request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "manual candidate gap")
        provider = ManualPlanningCandidateGapProvider()
        service = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({}))
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="每晚各安排一次",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        public_view_option = next(
            option for option in second.assistant_turn.choice_options if option["id"].endswith(":public_view")
        )
        third = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="只安排开放的城市公共观景点",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": second.assistant_turn.id,
                        "choiceId": public_view_option["id"],
                    }
                },
            ),
        )
        third_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (third.assistant_turn.id,),
            ).fetchone()["agent_response_json"]
        )
        gap = third_payload.get("candidateGapSummary") or {}
        assert gap.get("goals"), json.dumps(
            {
                "terminalStatus": third.terminal_status,
                "candidateGapSummary": gap,
                "choiceOptions": third.assistant_turn.choice_options,
                "events": [
                    {
                        "type": item.type,
                        "status": item.status,
                        "metadata": item.metadata,
                    }
                    for item in third.planning_steps
                    if item.type
                    in {
                        "agent_decision",
                        "controller_full_failed",
                        "controller_lite_failed",
                        "collect_candidates",
                        "build_persistable_segment_plans",
                        "agent_action_outcome",
                    }
                ],
            },
            ensure_ascii=False,
            indent=2,
            default=str,
        )
        night_gap = next(item for item in gap["goals"] if item["intentType"] == "night_view")
        gap_choice = next(
            option for option in third.assistant_turn.choice_options if option["label"] == "继续确认候选范围"
        )

        assert third.terminal_status == "candidate_refresh_required"
        assert night_gap["targetCount"] > 0
        assert night_gap["targetCount"] == night_gap["resolvedCount"] + night_gap["missingOccurrences"]
        assert night_gap["missingOccurrences"] > 0
        assert night_gap["allowedDayNumbers"]
        assert gap_choice["candidateGapFingerprint"] == gap["fingerprint"]
        assert gap_choice["requestContractFingerprint"]
        assert gap_choice["checkpointFingerprint"]
        assert gap_choice["planningSelectionRootTurnId"]
        assert gap_choice["goalId"] == night_gap["goalId"]
        assert gap_choice["occurrenceId"]
        assert gap_choice["briefId"]
        assert gap_choice["poolId"]
        assert gap_choice["planningSlotId"]
        assert gap_choice["dayNumber"] in night_gap["allowedDayNumbers"]
        assert gap_choice["attemptIdentity"]

        fourth = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="继续确认候选范围",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": third.assistant_turn.id,
                        "choiceId": gap_choice["id"],
                    }
                },
            ),
        )
        fourth_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (fourth.assistant_turn.id,),
            ).fetchone()["agent_response_json"]
        )
        controller_call_count = len(provider.contexts)
        gap_execution = dict(
            connection.execute(
                """SELECT status, attempt, outcome_json
                FROM agent_choice_executions
                WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?""",
                (session.session_id, third.assistant_turn.id, gap_choice["id"]),
            ).fetchone()
        )
        assert gap_execution["status"] == "succeeded", json.dumps(
            {
                "execution": gap_execution,
                "selectedChoice": json.loads(
                    connection.execute(
                        "SELECT agent_request_json FROM conversation_turns WHERE id = ?",
                        (fourth.user_turn.id,),
                    ).fetchone()["agent_request_json"]
                ).get("selectedAgentChoice"),
                "terminalStatus": fourth.terminal_status,
                "choiceOptions": fourth.assistant_turn.choice_options,
                "sourceOption": gap_choice,
            },
            ensure_ascii=False,
            indent=2,
        )
        with pytest.raises(HTTPException) as duplicate_gap_choice_error:
            service.send_message(
                session.session_id,
                AgentMessageRequest(
                    content="重复继续确认候选范围",
                    context={
                        "selectedAgentChoice": {
                            "sourceAssistantTurnId": third.assistant_turn.id,
                            "choiceId": gap_choice["id"],
                        }
                    },
                ),
            )
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        route_count = connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0]

    assert fourth.terminal_status == "needs_confirmation"
    assert fourth.assistant_turn.status == "active"
    assert fourth.assistant_turn.choice_options
    assert all(option["kind"] == "clarification_checkpoint" for option in fourth.assistant_turn.choice_options), (
        json.dumps(
            {
                "terminalStatus": fourth.terminal_status,
                "content": fourth.assistant_turn.content,
                "choiceOptions": fourth.assistant_turn.choice_options,
                "events": [
                    {"type": item.type, "status": item.status, "metadata": item.metadata}
                    for item in fourth.planning_steps
                    if item.type in {"agent_decision", "controller_full_failed", "controller_lite_failed"}
                ],
            },
            ensure_ascii=False,
            indent=2,
            default=str,
        )
    )
    assert fourth_payload["clarificationCheckpoint"]["nextQuestionDimensionId"] == "night_view.candidate_recovery"
    assert "本轮没有可安全执行的明确动作" not in fourth.assistant_turn.content
    assert gap_execution["status"] == "succeeded"
    assert gap_execution["attempt"] == 1
    assert json.loads(gap_execution["outcome_json"])["reason"] == "candidate_gap_clarification_checkpoint_created"
    assert duplicate_gap_choice_error.value.detail["code"] == "agent_choice_consumed"
    assert len(provider.contexts) == controller_call_count
    assert version_count == patch_count == route_count == 0


def test_candidate_gap_summary_fails_closed_when_coverage_sources_conflict():
    request_context = {
        "requestIntentContract": {
            "requiredIntents": [
                {
                    "goalId": "goal_night_view",
                    "intentType": "night_view",
                    "requiredMin": 2,
                    "allowedDayNumbers": [1, 2],
                }
            ]
        },
        "goalOccurrencePlan": {
            "occurrences": [
                {
                    "occurrenceId": "night_day_1",
                    "sourceGoalId": "goal_night_view",
                    "intentType": "night_view",
                    "dayNumber": 1,
                },
                {
                    "occurrenceId": "night_day_2",
                    "sourceGoalId": "goal_night_view",
                    "intentType": "night_view",
                    "dayNumber": 2,
                },
            ]
        },
    }
    grounding_report = {
        "resultState": "candidate_refresh_required",
        "rootGlobalBlocker": {
            "status": "candidate_refresh_required",
            "goals": [
                {
                    "goalId": "goal_night_view",
                    "intentType": "night_view",
                    "requiredCount": 2,
                    "missingCount": 1,
                }
            ],
        },
        "blockingRequiredIntents": [
            {
                "goalId": "goal_night_view",
                "intentType": "night_view",
                "poolId": "pool_night",
                "targetCount": 2,
                "selectedCount": 1,
                "missingCount": 1,
            }
        ],
        # Same pool, but a stale coverage projection claims that both
        # occurrences resolved.  The recovery choice must not guess which
        # projection is current.
        "requiredIntentCoverage": [
            {
                "goalId": "goal_night_view",
                "intentType": "night_view",
                "poolId": "pool_night",
                "targetCount": 2,
                "selectedCount": 2,
                "missingCount": 0,
            }
        ],
        "poolReports": [
            {
                "sourceGoalId": "goal_night_view",
                "intentType": "night_view",
                "briefId": "brief_public_view",
                "poolId": "pool_night",
                "targetCount": 2,
                "selectedCount": 1,
                "missingCount": 1,
                "requiredSlotIds": ["slot_night_1", "slot_night_2"],
                "resolvedSlotIds": ["slot_night_1"],
                "unresolvedSlotIds": ["slot_night_2"],
                "slotDayNumbers": {"slot_night_1": 1, "slot_night_2": 2},
            }
        ],
    }

    summary = AgentService._candidate_gap_summary(grounding_report, request_context)

    assert summary["scopeStatus"] == "inconsistent"
    assert summary["goals"] == []
    assert summary["missingOccurrenceScopes"] == []


def test_invalid_next_controller_question_preserves_checkpoint_and_only_offers_retry():
    clear_database()
    request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "invalid clarification")
        provider = InvalidSecondClarificationCheckpointProvider()
        service = AgentService(connection, provider=provider)
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        first_checkpoint = service._turn_response(first.assistant_turn.id).clarification_checkpoint
        first_option = first.assistant_turn.choice_options[0]
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="每晚各安排一次",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first_option["id"],
                    }
                },
            ),
        )
        refreshed_second = service._turn_response(second.assistant_turn.id)
        counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert counts == (0, 0, 0)
    assert len(second.assistant_turn.choice_options) == 1
    retry = second.assistant_turn.choice_options[0]
    assert retry["kind"] == "safe_fallback_action"
    assert retry["action"] == "retry_model_planning"
    assert retry["label"] == "重试生成澄清问题"
    serialized = json.dumps(
        {
            "reply": second.assistant_turn.content,
            "choices": second.assistant_turn.choice_options,
        },
        ensure_ascii=False,
    )
    assert "INVALID_CONTROLLER" not in serialized
    assert refreshed_second.clarification_checkpoint["checkpointId"] == first_checkpoint["checkpointId"]
    assert refreshed_second.clarification_checkpoint["resolvedAnswers"][-1]["semanticValue"] == {
        "occurrencePolicy": "every_available_evening"
    }


def test_invalid_question_after_completed_clarification_retries_planning_not_clarification():
    clear_database()
    request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "completed clarification fallback")
        provider = InvalidAfterCompletedClarificationCheckpointProvider()
        service = AgentService(connection, provider=provider)
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="每晚各安排一次",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        third = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="接受公共户外夜景",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": second.assistant_turn.id,
                        "choiceId": second.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        refreshed_third = service._turn_response(third.assistant_turn.id)
        third_request = json.loads(
            connection.execute(
                "SELECT agent_request_json FROM conversation_turns WHERE id = ?",
                (third.user_turn.id,),
            ).fetchone()[0]
        )
        counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert counts == (0, 0, 0)
    checkpoint = refreshed_third.clarification_checkpoint
    assert checkpoint["status"] == "answered"
    assert checkpoint["unresolvedDimensions"] == []
    assert checkpoint["nextQuestionDimensionId"] is None
    assert len(third.assistant_turn.choice_options) == 1
    retry = third.assistant_turn.choice_options[0]
    assert retry["kind"] == "safe_fallback_action"
    assert retry["action"] == "retry_model_planning"
    assert retry["label"] == "重试生成行程"
    assert retry["sourceUserTurnId"] == first.user_turn.id
    assert retry["planningSelectionRootTurnId"] == first.user_turn.id
    assert retry["attempt"] == 1
    assert retry["requestContractFingerprint"] == ClarificationCheckpointService._fingerprint(
        third_request["requestIntentContract"]
    )
    assert "controller_contract_invalid" in third.assistant_turn.content
    assert "澄清问题未通过" not in third.assistant_turn.content
    serialized = json.dumps(
        {
            "reply": third.assistant_turn.content,
            "choices": third.assistant_turn.choice_options,
        },
        ensure_ascii=False,
    )
    assert "INVALID_EXTRA_CONTROLLER" not in serialized


def test_retry_after_completed_clarification_no_progress_does_not_offer_third_fresh_retry():
    clear_database()
    request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "retry no progress exhausted")
        provider = InvalidAfterCompletedClarificationCheckpointProvider()
        service = AgentService(connection, provider=provider)
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="每晚各安排一次",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        third = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="接受公共户外夜景",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": second.assistant_turn.id,
                        "choiceId": second.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        retry = third.assistant_turn.choice_options[0]
        fourth = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="选择 Agent 选项",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": third.assistant_turn.id,
                        "choiceId": retry["id"],
                    }
                },
            ),
        )
        execution = dict(
            connection.execute(
                """SELECT status, attempt, outcome_json
                FROM agent_choice_executions
                WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?""",
                (session.session_id, third.assistant_turn.id, retry["id"]),
            ).fetchone()
        )
        counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert counts == (0, 0, 0)
    assert fourth.version is None
    assert fourth.itinerary is None
    assert fourth.terminal_status == "no_safe_action"
    assert fourth.assistant_turn.choice_options == []
    assert "已按相同已确认需求重试一次" in fourth.assistant_turn.content
    assert execution["status"] == "failed_terminal"
    assert execution["attempt"] == 1
    assert json.loads(execution["outcome_json"])["reason"] == "no_material_progress"


@pytest.mark.parametrize(
    "tampered_field",
    [
        "checkpointId",
        "planningRootId",
        "requestFingerprint",
        "checkpointFingerprint",
    ],
)
def test_tampered_controller_checkpoint_identity_is_zero_write_and_recoverable(
    tampered_field,
):
    clear_database()
    request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", f"tampered {tampered_field}")
        provider = TamperedSecondClarificationIdentityProvider(tampered_field)
        service = AgentService(connection, provider=provider)
        first = service.send_message(
            session.session_id,
            AgentMessageRequest(content=request),
        )
        first_checkpoint = service._turn_response(first.assistant_turn.id).clarification_checkpoint
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="每晚各安排一次",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first.assistant_turn.choice_options[0]["id"],
                    }
                },
            ),
        )
        refreshed = service._turn_response(second.assistant_turn.id)
        counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert counts == (0, 0, 0)
    assert second.assistant_turn.choice_options[0]["action"] == ("retry_model_planning")
    assert refreshed.clarification_checkpoint["checkpointId"] == (first_checkpoint["checkpointId"])
    assert refreshed.clarification_checkpoint["status"] == "awaiting_agent_resolution"
    assert refreshed.clarification_checkpoint["unresolvedDimensions"] == ["night_view.experience_mode"]
    assert refreshed.clarification_checkpoint["nextQuestionDimensionId"] is None
    assert refreshed.clarification_checkpoint["resolvedAnswers"][-1]["semanticValue"] == {
        "occurrencePolicy": "every_available_evening"
    }


