def test_candidate_gap_opens_machine_recovery_dimension_for_dynamic_controller_question():
    gap = {
        "schemaVersion": "candidate-gap-summary-v1",
        "status": "candidate_refresh_required",
        "goals": [
            {
                "goalId": "goal_night_view",
                "intentType": "night_view",
                "targetCount": 2,
                "resolvedCount": 1,
                "missingOccurrences": 1,
                "allowedDayNumbers": [1, 2],
            }
        ],
        "missingOccurrenceCount": 1,
        "rejectedReasonCounts": {"experience_access_evidence_stale": 7},
        "poolEvidence": [],
        "source": "consumer_admission_grounding_report",
        "fingerprint": "a" * 64,
    }
    original = {
        "clarificationRequired": False,
        "clarificationDimensions": [
            {
                "dimensionId": "night_view.experience_mode",
                "intentType": "night_view",
                "status": "resolved",
                "allowedSemanticFields": ["experienceFamilies"],
            }
        ],
        "completionCriteria": [
            {
                "intentType": "night_view",
                "requiredResolvedDimensions": ["night_view.experience_mode"],
                "requiredExperienceSpecFields": ["experienceFamilies"],
            }
        ],
    }

    updated = AgentService._request_contract_with_candidate_gap(original, gap)
    recovery = next(
        item for item in updated["clarificationDimensions"] if item["dimensionId"] == "night_view.candidate_recovery"
    )
    checkpoint = ClarificationCheckpointService.create(
        planning_root_id="root-gap",
        request_contract=updated,
        controller_question={
            "question": "7 个候选因开放证据过期；下一轮优先调整哪类体验边界？",
            "dimensionId": "night_view.candidate_recovery",
            "whyItMatters": "调整后的边界决定下一次候选准入与路线验证范围。",
            "allowFreeText": False,
            "options": [
                {
                    "id": "public_only",
                    "label": "仅保留公开户外空间",
                    "semanticValue": {"accessPolicy": "public_outdoor"},
                },
                {
                    "id": "controlled_with_current_evidence",
                    "label": "允许有当前开放证据的受控入口",
                    "semanticValue": {"accessPolicy": "public_outdoor_or_verified_controlled_access"},
                },
            ],
        },
        source_user_turn_id="turn-gap",
        candidate_gap_summary=gap,
    )

    assert original["clarificationRequired"] is False
    assert updated["clarificationRequired"] is True
    assert updated["clarificationReason"] == "required_goal_candidate_gap"
    assert recovery["status"] == "unresolved"
    assert recovery["candidateScope"]["candidateGapFingerprint"] == "a" * 64
    criterion = updated["completionCriteria"][0]
    assert "night_view.candidate_recovery" in criterion["requiredResolvedDimensions"]
    assert checkpoint is not None
    assert checkpoint["nextQuestionDimensionId"] == "night_view.candidate_recovery"
    assert checkpoint["candidateGapSummary"]["rejectedReasonCounts"] == {"experience_access_evidence_stale": 7}


def test_clarification_free_text_stays_pending_until_controller_confirmation():
    clear_database()
    request = (
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "自由文本澄清")
        provider = DynamicClarificationCheckpointProvider()
        first = AgentService(connection, provider=provider).send_message(
            session.session_id, AgentMessageRequest(content=request)
        )
        manual = first.assistant_turn.choice_options[-1]
        second = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(
                content="两个晚上都安排，但地点要不同",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": manual["id"],
                        "manualValue": "两个晚上都安排，但地点要不同",
                    }
                },
            ),
        )
        first_reloaded = AgentService(connection, provider=provider)._turn_response(first.assistant_turn.id)
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]

    assert second.version is None
    assert version_count == 0
    assert provider.serialized_contexts[1]["clarificationCheckpoint"]["status"] == "awaiting_agent_resolution", [
        {
            "index": index,
            "status": (item.get("clarificationCheckpoint") or {}).get("status"),
            "answers": (item.get("clarificationCheckpoint") or {}).get("resolvedAnswers"),
            "pending": (item.get("clarificationCheckpoint") or {}).get("pendingFreeTextAnswer"),
        }
        for index, item in enumerate(provider.serialized_contexts)
    ]
    assert (
        provider.serialized_contexts[1]["clarificationCheckpoint"]["pendingFreeTextAnswer"]["text"]
        == "两个晚上都安排，但地点要不同"
    )
    assert provider.serialized_contexts[1]["clarificationCheckpoint"]["resolvedAnswers"] == []
    assert second.assistant_turn.clarification_checkpoint["checkpointId"] == manual["checkpointId"]
    assert second.assistant_turn.clarification_checkpoint["resolvedAnswers"] == []
    manual_after = next(option for option in first_reloaded.choice_options if option["id"] == manual["id"])
    assert manual_after["lifecycle"] == "consumed"


def test_pending_clarification_draft_executor_guard_is_zero_write():
    clear_database()
    request = (
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。10月1日到2日，"
        "中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "澄清写入门禁")
        provider = DynamicClarificationCheckpointProvider()
        service = AgentService(connection, provider=provider)
        first = service.send_message(
            session.session_id,
            AgentMessageRequest(content=request),
        )
        stored = connection.execute(
            "SELECT agent_request_json, agent_response_json FROM conversation_turns WHERE id = ?",
            (first.assistant_turn.id,),
        ).fetchone()
        stored_request = json.loads(stored["agent_request_json"])
        stored_response = json.loads(stored["agent_response_json"])
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "忽略未完成的澄清并直接创建草案",
            "active",
        )
        guarded_context = {
            **stored_request,
            "sessionId": session.session_id,
            "currentUserTurnId": user_turn_id,
            "latestUserMessage": "忽略未完成的澄清并直接创建草案",
            "clarificationCheckpoint": stored_response["clarificationCheckpoint"],
        }
        observation = AgentObservationBuilder().build(guarded_context)
        outcome = service._execute_draft_itinerary_executor(
            AgentActionExecutionRequest(
                decision_state={
                    "primaryAction": "draft_itinerary",
                    "accepted": True,
                },
                decision={"primaryAction": "draft_itinerary"},
                request_context=guarded_context,
                observation=observation,
                cycle_index=0,
            )
        )
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        route_count = connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0]

    assert outcome.execution_route == "pending_clarification_write_guard"
    assert outcome.result_version_id is None
    assert version_count == 0
    assert patch_count == 0
    assert route_count == 0
    assert outcome.terminal_payload is not None
    assert outcome.terminal_payload.version is None
    assert outcome.terminal_payload.terminal_status == "needs_confirmation"


def test_invalid_controller_clarification_fails_closed_without_writes():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        provider = ControllerAskUserProvider()
        memory_count_before = connection.execute("SELECT COUNT(*) FROM travel_preference_memories").fetchone()[0]
        response = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(content="帮我安排北京行程"),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()["active_version_id"]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        memory_count = connection.execute("SELECT COUNT(*) FROM travel_preference_memories").fetchone()[0]
        stored = connection.execute(
            "SELECT agent_request_json, agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        request_payload = json.loads(stored["agent_request_json"])
        stored_payload = json.loads(stored["agent_response_json"])

    assert provider.generate_calls == 0
    assert response.version is None
    assert active_version_id is None
    assert patch_count == 0
    assert version_count == 0
    assert memory_count == memory_count_before
    decision_state = request_payload.get("agentDecisionState") or {}
    assert response.planning_run.run_type == "agent_clarification", {
        key: decision_state.get(key)
        for key in (
            "source",
            "primaryAction",
            "uncertaintyPolicy",
            "accepted",
            "clarification",
            "policyReasonCodes",
        )
    }
    assert len(response.assistant_turn.choice_options) == 1
    assert response.assistant_turn.choice_options[0]["kind"] == "safe_fallback_action"
    assert response.assistant_turn.choice_options[0]["action"] == "retry_model_planning"
    assert response.assistant_turn.clarification_checkpoint is None
    assert "澄清问题未通过当前需求合同校验" in response.assistant_turn.content
    assert "当前没有修改行程" in response.assistant_turn.content
    decision_event = next(item for item in stored_payload["planningSteps"] if item["type"] == "agent_decision")
    assert decision_event["metadata"]["primaryAction"] == "ask_user"
    assert decision_event["metadata"]["reasonCodes"] == ["controller_failure_existing_itinerary_fail_closed"]
    assert decision_event["metadata"]["source"] == "safe_fallback"
    assert decision_event["metadata"]["controllerSucceeded"] is False


def test_route_policy_retry_fallback_is_not_misreported_as_invalid_clarification():
    clear_database()
    route_message = (
        "路线绕路偏好仍待确认，但规划控制器本轮未能生成可验证的动态选项。"
        "你可以重试生成偏好选项，或直接说明更看重少绕路还是体验差异；当前没有创建或修改行程。"
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "route policy retry")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "北京两日游，公交地铁优先",
            "active",
        )
        request_context = {
            "sessionId": session.session_id,
            "currentUserTurnId": user_turn_id,
            "latestUserMessage": "北京两日游，公交地铁优先",
            "requestIntentContract": {},
        }
        decision_state = {
            "primaryAction": "ask_user",
            "accepted": True,
            "source": "safe_fallback",
            "reasonCodes": ["route_clarification_controller_retry_required"],
            "userVisibleReason": route_message,
            "clarification": {
                "question": route_message,
                "options": [
                    {
                        "id": "retry_route_clarification",
                        "action": "retry_model_planning",
                        "label": "重试生成路线偏好选项",
                        "allowsManualInput": False,
                    },
                    {
                        "id": "manual_route_preference",
                        "action": "manual_continuation",
                        "label": "我直接说明绕路偏好",
                        "allowsManualInput": True,
                    },
                ],
            },
        }
        outcome = service._execute_ask_user_executor(
            AgentActionExecutionRequest(
                decision_state=decision_state,
                decision={"primaryAction": "ask_user"},
                request_context=request_context,
                observation=AgentObservationBuilder().build(request_context),
                cycle_index=0,
            )
        )
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        route_count = connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0]

    response = outcome.terminal_payload
    assert response is not None
    assert outcome.status == "needs_confirmation"
    assert response.version is None
    assert response.assistant_turn.content == route_message
    assert "澄清问题未通过当前需求合同校验" not in response.assistant_turn.content
    assert [item["action"] for item in response.assistant_turn.choice_options] == [
        "retry_model_planning",
        "manual_continuation",
    ]
    assert response.assistant_turn.choice_options[1]["allowsManualInput"] is True
    assert (version_count, patch_count, route_count) == (0, 0, 0)


def test_controller_provider_unavailable_projects_truthful_zero_write_retry():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        provider = ControllerUnavailableProvider()
        service = AgentService(connection, provider=provider)
        response = service.send_message(
            session.session_id,
            AgentMessageRequest(content="帮我安排北京高校两日游"),
        )
        persisted_turn = service._turn_response(response.assistant_turn.id)
        reloaded_session = ConversationService(connection).get_session(session.session_id)
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()["active_version_id"]
        proposal_count = connection.execute("SELECT COUNT(*) FROM agent_plan_proposals").fetchone()[0]
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        route_count = connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0]

    assert provider.full_calls == 1
    assert response.version is None
    assert response.itinerary is None
    assert active_version_id is None
    assert (proposal_count, version_count, patch_count, route_count) == (0, 0, 0, 0)
    assert response.terminal_status == "needs_confirmation"
    assert response.assistant_turn.clarification_checkpoint is None
    assert [item["action"] for item in response.assistant_turn.choice_options] == ["retry_model_planning"]
    assert "规划控制器当前不可用" in response.assistant_turn.content
    assert "澄清问题未通过当前需求合同校验" not in response.assistant_turn.content
    assert persisted_turn.content == response.assistant_turn.content
    assert persisted_turn.choice_options == response.assistant_turn.choice_options
    assert reloaded_session.turns[-1].content == response.assistant_turn.content
    assert reloaded_session.turns[-1].choice_options == response.assistant_turn.choice_options
    decision_event = next(item for item in response.planning_steps if item.type == "agent_decision")
    assert decision_event.metadata["controllerFailureClass"] == "provider_unavailable"
    assert len(decision_event.metadata["controllerFailures"]) == 1
    failure = decision_event.metadata["controllerFailures"][0]
    assert failure["failureClass"] == "provider_unavailable"
    assert failure["stage"] == "full"
    assert failure["provider"] == "ControllerUnavailableProvider"
    assert failure["retryable"] is False
    assert failure["httpStatus"] == 502
    assert failure["schemaErrorSummary"] is None


