class ControllerReadProvider(IntentContractProviderMixin):
    def __init__(self):
        self.tool_contexts = []

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "read_itinerary",
            "confidence": 0.94,
            "decisionSummary": "读取当前行程",
            "userVisibleReason": "先读取当前行程后回答。",
            "reasonCodes": ["read_only_request"],
            "requiredTools": ["read_itinerary", "patch_itinerary"],
            "actionDirective": {"type": "read_itinerary", "queryType": "timeline_summary"},
            "proposedWriteRisk": "high",
            "stopCondition": {"type": "read_complete"},
        }

    def run_tool_loop(self, context, tool_registry):
        self.tool_contexts.append(context)
        tool_registry.execute("call_read_phase1", "read_itinerary", {})
        return AgentToolLoopResult(reply="当前还没有可读取的行程。", tool_events=tool_registry.events)


