class ControllerSingleSegmentTimeProvider(IntentContractProviderMixin):
    def __init__(self, base_version_id: str):
        self.base_version_id = base_version_id

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        last_outcome = (context.get("observation") or {}).get("lastOutcome") or {}
        if last_outcome.get("action") == "patch_itinerary" and last_outcome.get("status") == "success":
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "finish",
                "confidence": 0.99,
                "decisionSummary": "已重新观察时间修改结果",
                "actionDirective": {"type": "finish", "assistantReply": "时间修改已保存。"},
                "stopCondition": {"type": "verified_patch_observed"},
            }
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "patch_itinerary",
            "confidence": 0.96,
            "decisionSummary": "修改单个 segment 时间",
            "userVisibleReason": "已把目标行程调整到 10:00。",
            "reasonCodes": ["single_segment_time_edit"],
            "requiredTools": ["read_itinerary", "patch_itinerary", "web_search"],
            "actionDirective": {
                "type": "patch_itinerary",
                "operationIntent": "replace_segment_start_time",
                "baseVersionId": self.base_version_id,
                "targetSegmentIds": ["seg_command_1"],
                "requestedOutcome": "把上午目标调整到 10:00",
                "startTime": "10:00",
            },
            "proposedWriteRisk": "none",
            "stopCondition": {"type": "verified_patch"},
        }


