def test_patch_executor_single_segment_time_edit_uses_existing_patch_and_verifier():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        initial = apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=accepted_action_valid_timeline_snapshot())],
            source_type="agent",
        )
        response = AgentService(
            connection,
            provider=ControllerSingleSegmentTimeProvider(initial.version.id),
        ).send_message(
            session.session_id,
            AgentMessageRequest(content="把上午那一项改到十点"),
        )
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]

    assert response.version is not None
    assert response.version.id != initial.version.id
    assert patch_count == 2
    assert version_count == 2
    assert response.itinerary.days[0].segments[0].id == "seg_command_1"
    assert response.itinerary.days[0].segments[0].start_time == "10:00"
    assert response.itinerary.days[0].segments[1].id == "seg_command_2"
    timeline_event = next(item for item in response.planning_steps if item.type == "timeline_edit")
    assert timeline_event.metadata["resultPreview"]["executorOwner"] == "timeline_mutation_executor"
    assert timeline_event.metadata["resultPreview"]["changedSegmentIds"] == ["seg_command_1"]
    decision_event = next(item for item in response.planning_steps if item.type == "agent_decision")
    assert decision_event.metadata["effectiveWriteRisk"] == "medium"
    assert decision_event.metadata["effectiveTools"] == [
        "patch_itinerary",
        "read_itinerary",
        "resolve_poi",
    ]


def test_patch_executor_stale_or_duplicate_time_edit_is_noop_without_extra_version():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        initial = apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=accepted_action_valid_timeline_snapshot())],
            source_type="agent",
        )
        provider = ControllerSingleSegmentTimeProvider(initial.version.id)
        first = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(content="把上午那一项改到十点"),
        )
        second = AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(content="重复刚才的时间修改"),
        )
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        version_count = connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0]

    assert first.version is not None
    assert second.version is None
    assert second.terminal_status == "needs_confirmation"
    assert patch_count == 2
    assert version_count == 2
    terminal_decision = [item for item in second.planning_steps if item.type == "agent_decision"][-1]
    assert terminal_decision.metadata["primaryAction"] == "ask_user"
    assert terminal_decision.metadata["accepted"] is True
    gate_event = [item for item in second.planning_steps if item.type == "agent_policy_gate"][-1]
    assert gate_event.metadata["accepted"] is True
    stop_event = next(item for item in second.planning_steps if item.type == "agent_stop")
    assert stop_event.metadata["stopReason"] == "needs_confirmation"


