class ModelOwnedMultiCycleInitialProvider(IntentContractProviderMixin):
    def __init__(self, output: dict[str, Any]):
        self.output = output
        self.calls = 0
        self.decision_calls = 0
        self.contexts: list[dict[str, Any]] = []
        self.tool_loop_calls = 0

    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        self.decision_calls += 1
        if self.decision_calls == 1:
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "draft_itinerary",
                "confidence": 0.96,
                "decisionSummary": "按用户目标起草两日行程",
                "requiredCapabilities": ["poi_grounding", "route", "versioned_write"],
                "requiredTools": ["resolve_poi", "patch_itinerary"],
                "actionDirective": {
                    "type": "draft_itinerary",
                    "goalPriority": ["goal_campus_visit", "goal_night_view"],
                    "dayStrategies": [
                        {
                            "dayNumber": 1,
                            "theme": "高校与夜景",
                            "requiredGoalIds": ["goal_campus_visit", "goal_night_view"],
                            "requiredGoalCounts": {"goal_campus_visit": 1, "goal_night_view": 1},
                            "optionalGoalIds": [],
                            "pace": "standard",
                            "maxRouteAnchors": 4,
                        },
                        {
                            "dayNumber": 2,
                            "theme": "高校与夜景",
                            "requiredGoalIds": ["goal_campus_visit", "goal_night_view"],
                            "requiredGoalCounts": {"goal_campus_visit": 1, "goal_night_view": 1},
                            "optionalGoalIds": [],
                            "pace": "standard",
                            "maxRouteAnchors": 4,
                        },
                    ],
                    "optionalExperienceBudget": 0,
                    "routePlanningPolicy": {
                        "objective": "least_generalized_cost",
                        "source": "controller_estimate",
                        "allowExperienceDetour": False,
                        "mobilityProfile": {
                            "transportMode": "transit",
                            "paceClass": "standard",
                        },
                        "detourEnvelope": {
                            "maxGeneralizedCostDelta": 15.0,
                            "maxDetourRatio": 0.15,
                        },
                    },
                    "occurrenceScheduleHints": [
                        {
                            "goalId": goal_id,
                            "dayNumber": day_number,
                            "dayPart": "morning" if goal_id == "goal_campus_visit" else "night",
                            "sequence": 1 if goal_id == "goal_campus_visit" else 2,
                            "preferredStartTime": "09:00" if goal_id == "goal_campus_visit" else "19:00",
                            "durationEstimate": {
                                "min": 60,
                                "preferred": 90,
                                "max": 120,
                            },
                            "estimateSource": "controller_estimate",
                            "confidence": 0.95,
                        }
                        for day_number in (1, 2)
                        for goal_id in ("goal_campus_visit", "goal_night_view")
                    ],
                    "searchPriority": ["hard_constraint", "required"],
                    "candidateSelectionPolicy": {
                        "autoSelectWhenDominant": True,
                        "askWhenMaterialTradeoff": True,
                        "preferLowDetour": True,
                        "avoidRecentEntities": True,
                    },
                    "schedulePolicy": {
                        "respectOpeningWindowsWhenKnown": True,
                        "allowProvisionalWhenUnknown": True,
                    },
                },
                "stopCondition": {"type": "verified_goal_state_or_material_choice"},
            }
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "finish",
            "confidence": 0.92,
            "decisionSummary": "已根据持久化结果完成本轮",
            "actionDirective": {"type": "finish", "assistantReply": "已完成可验证草稿。"},
            "stopCondition": {"type": "verified_goal_state"},
        }

    def generate_initial_plan(self, context):
        self.contexts.append(context)
        self.calls += 1
        return json.dumps(self.output, ensure_ascii=False)

    def run_tool_loop(self, _context, _tool_registry):
        self.tool_loop_calls += 1
        raise AssertionError("model-selected staged draft must not enter generic tool loop")


