class ModelOwnedDraftResolvePatchProvider(ModelOwnedMultiCycleInitialProvider):
    def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
        self.decision_calls += 1
        observation = context.get("observation") or {}
        if self.decision_calls == 1:
            self.decision_calls -= 1
            return super().decide_autonomy(context, timeout_seconds=timeout_seconds, repair_feedback=repair_feedback)
        if self.decision_calls == 2:
            unresolved = observation.get("unresolvedSlots") or []
            segment_id = next(
                str(item.get("segmentId"))
                for item in unresolved
                if item.get("segmentId") and item.get("goalId") == "goal_campus_visit"
            )
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "resolve_poi",
                "confidence": 0.97,
                "decisionSummary": "为未落地高校段收集真实候选",
                "requiredTools": ["resolve_poi"],
                "actionDirective": {
                    "type": "resolve_poi",
                    "targetGoalId": "goal_campus_visit",
                    "targetSegmentIds": [segment_id],
                    "searchIntent": "高校",
                    "searchMode": "text",
                    "maxCandidates": 4,
                    "autoSelectPolicy": "dominant_safe_candidate_only",
                    "askUserPolicy": "material_tradeoff_only",
                },
                "stopCondition": {"type": "candidate_observation"},
            }
        last_outcome = observation.get("lastOutcome") or {}
        if last_outcome.get("action") == "patch_itinerary" and last_outcome.get("status") == "success":
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "finish",
                "confidence": 0.99,
                "decisionSummary": "候选写入并验证完成",
                "actionDirective": {"type": "finish", "assistantReply": "地点替换已完成。"},
                "stopCondition": {"type": "verified_patch_observed"},
            }
        group = next(
            item
            for item in observation.get("candidateState", {}).get("pendingGroups", [])
            if item.get("safeCandidates")
        )
        candidate = group["safeCandidates"][0]
        segment_id = str(group["sourceSegmentId"])
        version_id = str(observation["versionLineage"]["currentVersionId"])
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "patch_itinerary",
            "confidence": 0.98,
            "decisionSummary": "唯一安全候选可直接写入",
            "requiredTools": ["patch_itinerary"],
            "actionDirective": {
                "type": "patch_itinerary",
                "operationIntent": "replace_segment_poi_from_candidate",
                "baseVersionId": version_id,
                "targetSegmentIds": [segment_id],
                "candidateId": str(group["id"]),
                "amapPoiId": str(candidate["id"]),
                "requestedOutcome": "写入唯一安全候选",
                "preserve": ["other_days", "other_segments"],
                "maxChangedSegmentCount": 1,
            },
            "stopCondition": {"type": "verified_patch"},
        }


