def test_patch_itinerary_tool_schema_exposes_poi_timeline_edit_fields():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        registry = TravelToolRegistry(connection, session_row, {})

    patch_tool = next(tool for tool in registry.tool_definitions() if tool["function"]["name"] == "patch_itinerary")
    variants = patch_tool["function"]["parameters"]["properties"]["operations"]["items"]["anyOf"]
    by_op = {variant["properties"]["op"]["enum"][0]: variant["properties"] for variant in variants}
    assert "amapPoi" in by_op["replace_segment_poi"]
    assert "dayId" in by_op["refresh_routes_for_day"]
    assert "segmentId" in by_op["remove_segment"]
    assert "orderedSegmentIds" in by_op["reorder_segments"]
    assert "durationMinutes" in by_op["add_segment"]
    full_itinerary_schema = by_op["replace_itinerary"]["fullItinerary"]
    budget_target_schema = full_itinerary_schema["properties"]["budgetTarget"]
    segment_schema = full_itinerary_schema["properties"]["days"]["items"]["properties"]["segments"]["items"]
    poi_schema = segment_schema["properties"]["poi"]
    assert budget_target_schema["anyOf"] == [{"type": "number"}, {"type": "null"}]
    assert "中等/低/高" in budget_target_schema["description"]
    assert "poi" in segment_schema["required"]
    assert poi_schema["required"] == [
        "name",
        "city",
        "category",
        "source",
        "sourceNote",
        "confidence",
        "latitude",
        "longitude",
    ]
    assert "agent-text-timeline" in poi_schema["description"]
    assert "directly on this segment object" in segment_schema["description"]


