def test_patch_itinerary_tool_skips_unneeded_expand_for_concrete_poi_without_error():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        registry = TravelToolRegistry(
            connection,
            session_row,
            successful_tool_request_context("替换为具体 POI"),
        )
        write_result = registry.execute(
            "call_write_concrete_poi",
            "patch_itinerary",
            {"operations": [replace_itinerary_operation()]},
        )
        segment_id = connection.execute(
            "SELECT id FROM itinerary_segments WHERE plan_id = ? ORDER BY segment_order LIMIT 1",
            (session.active_plan_id,),
        ).fetchone()["id"]
        version_after_write = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

        expand_result = registry.execute(
            "call_expand_concrete_poi",
            "patch_itinerary",
            {"operations": [{"op": "expand_area_poi_candidates", "segmentId": segment_id, "radius": 1500}]},
        )
        version_after_expand = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

    assert write_result["ok"] is True
    assert expand_result["ok"] is True
    assert expand_result["activeVersionId"] == version_after_write
    assert version_after_expand == version_after_write
    assert expand_result["skippedOperations"] == [
        {"op": "expand_area_poi_candidates", "segmentId": segment_id, "reason": "segment_already_concrete"}
    ]
    assert expand_result["failureReason"] is None


def test_patch_itinerary_tool_does_not_skip_expand_for_routeable_anchor_poi():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        registry = TravelToolRegistry(
            connection,
            session_row,
            successful_tool_request_context("展开待核对 POI"),
        )
        write_result = registry.execute(
            "call_write_anchor_poi",
            "patch_itinerary",
            {"operations": [replace_itinerary_operation()]},
        )
        segment = connection.execute(
            "SELECT id, poi_id FROM itinerary_segments WHERE plan_id = ? ORDER BY segment_order LIMIT 1",
            (session.active_plan_id,),
        ).fetchone()
        connection.execute(
            """
            UPDATE pois
            SET source = ?, amap_id = ?, longitude = ?, latitude = ?, source_note = ?
            WHERE id = ?
            """,
            (
                "agent-text-timeline",
                "BANCHOR",
                116.397026,
                39.918058,
                "groundingStatus：routeable_anchor；地图锚点：天安门广场；仍需用户确认具体目标",
                segment["poi_id"],
            ),
        )
        connection.commit()
        version_after_write = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

        expand_result = registry.execute(
            "call_expand_anchor_poi",
            "patch_itinerary",
            {"operations": [{"op": "expand_area_poi_candidates", "segmentId": segment["id"], "radius": 1500}]},
        )
        version_after_expand = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

    assert write_result["ok"] is True
    assert expand_result["ok"] is False
    assert "skippedOperations" not in expand_result
    assert "expand_area_poi_candidates" in expand_result["error"]
    assert version_after_expand == version_after_write


