def test_patch_itinerary_validation_error_adds_structured_retry_feedback_to_next_round():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        context = {
            "latestUserMessage": "今年国庆北京高校两日游，晚上北京夜景",
            "activeConversationTurns": [],
            "selectedCity": "北京",
            "requiredToolSequence": ["read_itinerary", "patch_itinerary"],
            "timelineWriteContract": {"required": True},
            "requestIntentContract": {
                "routeDecisionContract": canonical_server_route_decision_contract(),
            },
        }
        provider = ScriptedDeepSeekProvider(
            [
                read_itinerary_tool_response(),
                patch_itinerary_tool_response(
                    call_id="call_bad_patch",
                    operation=invalid_missing_poi_itinerary_operation(),
                ),
                patch_itinerary_tool_response(
                    call_id="call_fixed_patch",
                    operation=replace_itinerary_operation(),
                ),
            ]
        )
        result = provider.run_tool_loop(
            context,
            TravelToolRegistry(connection, session_row, context, source_turn_id="assistant_validation_retry"),
        )

    retry_messages = [
        str(message.get("content") or "")
        for message in provider.payloads[2]["messages"]
        if message.get("role") in {"user", "tool"}
    ]
    assert "已通过 patch_itinerary 写入" in result.reply
    assert provider.payloads[2]["tool_choice"] == {"type": "function", "function": {"name": "patch_itinerary"}}
    assert any("tool_argument_schema_error" in message for message in retry_messages)
    assert any("segments[0].poi" in message for message in retry_messages)
    patch_events = [event for event in result.tool_events if event["toolName"] == "patch_itinerary"]
    assert [event["status"] for event in patch_events] == ["failed", "succeeded"]


