def test_agent_full_itinerary_is_converted_to_validated_patch_and_version():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(
            connection,
            provider=FakeProvider(full_itinerary_output()),
            poi_resolution_service=FakePoiResolver(
                {
                    "故宫": poi_fixture("B000PALACE", "故宫博物院"),
                    "景山": poi_fixture("B000JINGSHAN", "景山公园"),
                }
            ),
        ).send_message(session.session_id, AgentMessageRequest(content="帮我安排北京一天"))
        patch = connection.execute("SELECT * FROM itinerary_patches").fetchone()
        planning_run = connection.execute("SELECT * FROM planning_runs").fetchone()
        pois = connection.execute("SELECT amap_id, source FROM pois ORDER BY amap_id").fetchall()

    assert response.version is not None
    assert response.planning_run is not None
    assert response.planning_run.run_type == "agent_message"
    assert response.planning_run.feasibility_report is not None
    assert response.itinerary.weather_signals
    assert response.itinerary.ticket_lookup_results
    assert response.itinerary.poi_risk_alerts
    assert response.planning_run.tool_calls
    assert any(tool.id == "amap-weather" for tool in response.planning_run.tool_calls)
    assert any(tool.id == "web-search-ticket" for tool in response.planning_run.tool_calls)
    assert response.itinerary.weather_signals[0].provider_name
    assert response.itinerary.ticket_lookup_results[0].provider_name
    assert response.planning_run.understood_requirements["isCompleteEnoughToPlan"] is False
    assert "出行日期" in response.planning_run.final_summary
    assert "以下关键信息仍待确认" in response.warnings[0]
    assert planning_run["run_type"] == "agent_message"
    assert "可行性" in planning_run["final_summary"] or "已生成北京 1 日行程" in planning_run["final_summary"]
    assert "以下关键信息仍待确认" in planning_run["final_summary"]
    assert response.itinerary.title == "北京轻松 1 日游"
    assert len(response.itinerary.days[0].segments) == 2
    assert response.assistant_turn.itinerary_version_id == response.version.id
    assert patch["validation_status"] == "accepted"
    assert "replace_itinerary" in patch["operations_json"]
    assert [row["amap_id"] for row in pois] == ["B000JINGSHAN", "B000PALACE"]
    assert {row["source"] for row in pois} == {"amap-place-search"}


