def test_candidate_selection_path_auto_selects_close_route_dominant_candidate(monkeypatch):
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        itinerary_service = ItineraryService(connection)
        intent = PoiIntent(
            raw_need="夜景观景点",
            city="北京",
            day_number=1,
            time_window="18:00-20:00",
            intent_type="night_view",
            specificity="functional",
            target_count=1,
        )
        slot = DaySlot(
            slot_id="slot_night",
            day_number=1,
            date="2026-10-01",
            time_window="18:00-20:00",
            start_time="18:00",
            duration_minutes=120,
            kind="visit",
            raw_need="夜景观景点",
            route_anchor=True,
        )
        dominant = CandidateScore(
            candidate=MapPoiResponse(
                id="amap_dominant",
                name="路线占优观景塔",
                type="风景名胜;观景点",
                city="北京",
                district="朝阳区",
                address="测试地址一",
                longitude=116.40,
                latitude=40.03,
                category="scenic",
                source=AMAP_PLACE_SOURCE,
                sourceNote="来源：高德地图",
                confidence=0.93,
                photos=[],
            ),
            score=1.10,
            components={},
        )
        alternative = CandidateScore(
            candidate=MapPoiResponse(
                id="amap_alternative",
                name="偏绕观景塔",
                type="风景名胜;观景点",
                city="北京",
                district="海淀区",
                address="测试地址二",
                longitude=116.30,
                latitude=39.92,
                category="scenic",
                source=AMAP_PLACE_SOURCE,
                sourceNote="来源：高德地图",
                confidence=0.93,
                photos=[],
            ),
            score=1.04,
            components={},
        )

        def route_score(item, *_args, **_kwargs):
            risk = 0.0 if item is dominant else 0.06
            item.route_aware = {
                "straightLineDistanceKm": 4.96 if item is dominant else 10.28,
                "geoClusterScore": 0.08,
                "routeRiskPenalty": risk,
                "transportPreferencePenalty": 0.0,
                "routeInsertionPenalty": 0.0,
            }
            item.components = {
                "geoClusterScore": 0.08,
                "routeRiskPenalty": -risk,
                "transportPreferencePenalty": 0.0,
                "routeInsertionPenalty": 0.0,
            }
            return item.score

        monkeypatch.setattr(service, "_route_aware_adjusted_candidate_score", route_score)
        available = [dominant, alternative]
        selected = service._pop_next_pool_candidate_score(
            available,
            itinerary_service,
            intent,
            slot,
            day_seen=set(),
            trip_seen=set(),
            existing_day_pois=[],
            transport_mode="transit",
            threshold=0.72,
        )

    assert selected is dominant
    assert available == [alternative]


