    supplements = service._simple_open_contract_daily_soft_supplement_occurrences(
        {
            "requestIntentContract": contract,
            "resolvedTripDates": {"dayCount": 2},
        },
        directive,
    )
    assert {(item["sourceGoalId"], item["dayNumber"], item["intentType"]) for item in supplements} == {
        ("goal_meal", 1, "meal"),
        ("goal_meal", 2, "meal"),
    }


