def test_simple_open_invalid_initial_json_uses_same_authoritative_contract_fallback(monkeypatch):
    """A healthy Controller must not make malformed initial JSON fatal.

    The Controller authorizes the draft, while the sealed request contract owns
    explicit per-day occurrences.  This reproduces the production-only branch
    where the legacy rule fallback is deliberately disabled.
    """

    clear_database()
    message = (
        "今年国庆参观北京市985高校两日游，每天晚上逛公园。"
        "10月1日到2日，中等预算，1人，公交地铁优先。"
        "每天午餐想体验北京当地特色美食。"
    )
    with open_db() as connection:
        service = AgentService(connection)
        meal_policy = service.meal_grounding_policy.analyze(
            message,
            city="北京",
            budget="medium",
            day_count=2,
        )
        contract = service._request_intent_contract(
            message,
            {"dates": ["2026-10-01", "2026-10-02"]},
            meal_policy,
            simple_open_profile=True,
        )
        directive = {
            "type": "draft_itinerary",
            "dayStrategies": [
                {
                    "dayNumber": 1,
                    "requiredGoalIds": ["goal_campus_visit", "goal_park"],
                    "requiredGoalCounts": {"goal_campus_visit": 1, "goal_park": 1},
                    "optionalGoalIds": ["goal_meal"],
                    "maxRouteAnchors": 4,
                },
                {
                    "dayNumber": 2,
                    "requiredGoalIds": ["goal_campus_visit", "goal_park"],
                    "requiredGoalCounts": {"goal_campus_visit": 1, "goal_park": 1},
                    "optionalGoalIds": ["goal_meal"],
                    "maxRouteAnchors": 4,
                },
            ],
            "optionalExperienceBudget": 2,
        }
        pipeline_context = {
            "latestUserMessage": message,
            "effectiveUserMessage": message,
            "selectedCity": "北京",
            "serverExecutionProfile": "simple_open_v1",
            "requestIntentContract": contract,
            "understoodRequirements": {
                "fields": {
                    "travelDate": "2026-10-01 到 2026-10-02",
                    "travelDays": "2天",
                    "partySize": "1人",
                    "budget": "中等预算",
                    "transportPreference": "公交地铁优先",
                }
            },
            "resolvedTripDates": {
                "status": "resolved",
                "startDate": "2026-10-01",
                "endDate": "2026-10-02",
                "dayCount": 2,
                "dates": ["2026-10-01", "2026-10-02"],
            },
            "agentDecisionState": {
                "source": "controller",
                "accepted": True,
                "primaryAction": "draft_itinerary",
                "actionDirective": copy.deepcopy(directive),
            },
            "planningDirective": copy.deepcopy(directive),
        }

        assert service._rule_initial_fallback_allowed(pipeline_context) is False
        monkeypatch.setattr(service, "_call_initial_plan_provider", lambda _context: "{invalid-json")
        monkeypatch.setattr(
            service.output_repair_service,
            "repair",
            lambda *_args, **_kwargs: (None, {"status": "skipped"}),
        )
        events: list[dict] = []
        fallback = service._generate_initial_day_slot_output(pipeline_context, events)

    assert fallback.mode == "day_slots"
    assert len([slot for slot in fallback.day_slots if slot.kind == "campus"]) == 2
    assert len([slot for slot in fallback.day_slots if slot.kind == "park"]) == 2
    assert len([slot for slot in fallback.day_slots if slot.kind == "meal"]) == 2
    assert "DAY_SLOT_FALLBACK_UNAVAILABLE" not in fallback.warnings
    provider_event = next(event for event in events if event["type"] == "initial_day_slot_provider")
    assert provider_event["status"] == "fallback"
    assert provider_event["metadata"]["resultPreview"]["fallbackReason"] == "parse_error"
    assert provider_event["metadata"]["resultPreview"]["fallbackType"] == ("simple_open_contract_slot_fallback")


