def test_simple_open_invalid_initial_json_uses_answered_route_contract_when_legacy_transport_is_pending(
    monkeypatch,
):
    """A signed route answer must satisfy the fallback transport gate.

    The live browser request intentionally omits transport so the server asks a
    structured clarification.  After that answer is sealed, the authoritative
    route contract is ready even though the older requirement-card projection
    still says ``transportPreference=待确认``.  Invalid DaySlot JSON must not
    turn that stale display value into ``DAY_SLOT_FALLBACK_UNAVAILABLE``.
    """

    clear_database()
    message = "今年国庆参观北京高校两日游，晚上看北京夜景。10月1日到2日，中等预算，1人。每天午餐想体验当地特色美食。"
    with open_db() as connection:
        service = AgentService(connection)
        meal_policy = service.meal_grounding_policy.analyze(
            message,
            city="北京",
            budget="medium",
            day_count=2,
        )
        contract = service._request_intent_contract(
            message,
            {"dates": ["2026-10-01", "2026-10-02"]},
            meal_policy,
            simple_open_profile=True,
        )
        signed_context = signed_route_fallback_context()
        route_contract = copy.deepcopy(signed_context["requestIntentContract"]["routeDecisionContract"])
        assert route_contract["schemaVersion"] == "route-decision-contract-v2"
        assert route_contract["status"] == "ready"
        assert route_contract["missingFields"] == []
        assert route_contract["provenance"]["transportMode"] == "transit"
        assert RouteInsertionScorer.normalized_route_decision_contract(route_contract) is not None
        contract["routeDecisionContract"] = route_contract
        contract["clarificationRequired"] = False
        contract["clarificationReason"] = None
        contract["clarificationCheckpointId"] = signed_context["requestIntentContract"]["clarificationCheckpointId"]
        contract["clarificationDecisionSource"] = "controller_semantic_choice"
        contract["clarificationAnswers"] = copy.deepcopy(signed_context["clarificationCheckpoint"]["resolvedAnswers"])
        directive = {
            "type": "draft_itinerary",
            "dayStrategies": [
                {
                    "dayNumber": day_number,
                    "requiredGoalIds": ["goal_campus_visit"],
                    "requiredGoalCounts": {"goal_campus_visit": 1},
                    "optionalGoalIds": ["goal_meal"],
                    "maxRouteAnchors": 4,
                }
                for day_number in (1, 2)
            ],
            "optionalExperienceBudget": 2,
        }
        pipeline_context = {
            "latestUserMessage": "按服务端选项继续",
            "effectiveUserMessage": message,
            "selectedCity": "北京",
            "serverExecutionProfile": "simple_open_v1",
            "simpleOpenInitialRequestSufficient": True,
            "clarificationCheckpoint": copy.deepcopy(signed_context["clarificationCheckpoint"]),
            "requestIntentContract": contract,
            "understoodRequirements": {
                "fields": {
                    "travelDate": "2026-10-01 到 2026-10-02",
                    "travelDays": "2天",
                    "partySize": "1人",
                    "budget": "中等预算",
                    "transportPreference": "待确认",
                }
            },
            "resolvedTripDates": {
                "status": "resolved",
                "startDate": "2026-10-01",
                "endDate": "2026-10-02",
                "dayCount": 2,
                "dates": ["2026-10-01", "2026-10-02"],
            },
            "agentDecisionState": {
                "source": "controller",
                "accepted": True,
                "primaryAction": "draft_itinerary",
                "actionDirective": copy.deepcopy(directive),
            },
            "planningDirective": copy.deepcopy(directive),
        }

        assert service._rule_initial_fallback_allowed(pipeline_context) is False
        monkeypatch.setattr(service, "_call_initial_plan_provider", lambda _context: "{invalid-json")
        monkeypatch.setattr(
            service.output_repair_service,
            "repair",
            lambda *_args, **_kwargs: (None, {"status": "skipped"}),
        )
        events: list[dict] = []
        fallback = service._generate_initial_day_slot_output(pipeline_context, events)
        write_counts = {
            table: connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            for table in (
                "agent_plan_proposals",
                "itinerary_versions",
                "itinerary_patches",
                "route_options",
            )
        }

    assert fallback.mode == "day_slots"
    assert fallback.day_slots
    assert fallback.intent_pools
    assert "DAY_SLOT_FALLBACK_UNAVAILABLE" not in fallback.warnings
    provider_event = next(event for event in events if event["type"] == "initial_day_slot_provider")
    assert provider_event["status"] == "fallback"
    assert provider_event["metadata"]["resultPreview"]["fallbackReason"] == "parse_error"
    assert provider_event["metadata"]["resultPreview"]["fallbackType"] == ("simple_open_contract_slot_fallback")
    assert write_counts == {
        "agent_plan_proposals": 0,
        "itinerary_versions": 0,
        "itinerary_patches": 0,
        "route_options": 0,
    }


def test_simple_open_invalid_initial_json_uses_typed_sufficiency_when_legacy_days_and_budget_are_pending(
    monkeypatch,
):
    """A completed typed checkpoint must not be re-blocked by stale UI fields.

    This mirrors the real browser request ``今年国庆打算一个人去北京的985大学旅游``:
    the server has resolved a holiday date range and the user has answered the
    two signed route questions, while the legacy requirement-card projection
    still reports ``travelDays`` and ``budget`` as pending.  Those display
    fields are not additional planning authority once Simple Open has sealed
    ``simpleOpenInitialRequestSufficient`` and the route/checkpoint contract.
    """

    clear_database()
    context = signed_route_fallback_context(legacy_transport="待确认")
    # The production mobility question deliberately keeps a manual-input escape
    # hatch, but this run selected the exact server-authored structured option.
    # ``allowFreeText`` describes the question's capabilities; it must not taint
    # an otherwise signed ``structured_option`` answer.
    mobility_question = next(
        question
        for question in context["clarificationCheckpoint"]["questions"]
        if question["dimensionId"] == "route_decision.mobility_profile"
    )
    mobility_question["allowFreeText"] = True
    context["clarificationCheckpoint"]["fingerprint"] = ClarificationCheckpointService._fingerprint(
        {key: value for key, value in context["clarificationCheckpoint"].items() if key != "fingerprint"}
    )
    route_contract = context["requestIntentContract"]["routeDecisionContract"]
    route_contract["provenance"]["compactnessPolicy"]["checkpointFingerprint"] = context["clarificationCheckpoint"][
        "fingerprint"
    ]
    resealed_route_contract = RouteInsertionScorer.build_route_decision_contract(
        source=route_contract["source"],
        provenance=route_contract["provenance"],
        detour_tolerance=route_contract["detourTolerance"],
        mobility_profile=route_contract["mobilityProfile"],
        adjacent_leg_constraint=route_contract["adjacentLegConstraint"],
        topology_constraint=route_contract["topologyConstraint"],
    )
    assert resealed_route_contract is not None
    route_contract["fingerprint"] = resealed_route_contract["fingerprint"]
    context["effectiveUserMessage"] = "今年国庆打算一个人去北京的985大学旅游，你有什么建议吗"
    context["latestUserMessage"] = "确认并开始规划"
    context["understoodRequirements"] = {
        "fields": {
            "destination": "北京",
            "travelDate": "国庆",
            "travelDays": "待确认",
            "partySize": "1人",
            "budget": "待确认",
            "transportPreference": "待确认",
            "travelPurpose": "高校参观",
        },
        "missingFields": ["travelDays", "budget", "transportPreference"],
        "isCompleteEnoughToPlan": False,
    }
    context["resolvedTripDates"] = {
        "status": "resolved",
        "resolutionSource": "holiday_inferred",
        "startDate": "2026-10-01",
        "endDate": "2026-10-07",
        "dayCount": 7,
        "dates": [f"2026-10-{day:02d}" for day in range(1, 8)],
    }
    directive = {
        "type": "draft_itinerary",
        "goalPriority": ["goal_campus_visit"],
        "dayStrategies": [
            {
                "dayNumber": 1,
                "theme": "北京校园参观",
                "requiredGoalIds": ["goal_campus_visit"],
                "requiredGoalCounts": {"goal_campus_visit": 1},
                "optionalGoalIds": [],
                "maxRouteAnchors": 2,
            }
        ],
        "optionalExperienceBudget": 0,
    }
    context["agentDecisionState"] = {
        "source": "controller",
        "accepted": True,
        "primaryAction": "draft_itinerary",
        "actionDirective": copy.deepcopy(directive),
    }
    context["planningDirective"] = copy.deepcopy(directive)

    with open_db() as connection:
        service = AgentService(connection)
        assert service._rule_initial_fallback_allowed(context) is False
        monkeypatch.setattr(service, "_call_initial_plan_provider", lambda _context: "{invalid-json")
        events: list[dict] = []
        fallback = service._generate_initial_day_slot_output(context, events)
        write_counts = {
            table: connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            for table in (
                "agent_plan_proposals",
                "itinerary_versions",
                "itinerary_patches",
                "route_options",
            )
        }

    assert fallback.mode == "day_slots"
    assert any(slot.kind == "campus" for slot in fallback.day_slots)
    assert "DAY_SLOT_FALLBACK_UNAVAILABLE" not in fallback.warnings
    provider_event = next(event for event in events if event["type"] == "initial_day_slot_provider")
    assert provider_event["status"] == "fallback"
    provider_preview = provider_event["metadata"]["resultPreview"]
    assert provider_preview["fallbackType"] == "simple_open_contract_slot_fallback"
    assert provider_preview["repairStatus"] == "skipped"
    assert provider_preview["repairAttemptCount"] == 0
    assert provider_preview["repairFailureReason"] == "provider_repair_method_missing"
    assert write_counts == {
        "agent_plan_proposals": 0,
        "itinerary_versions": 0,
        "itinerary_patches": 0,
        "route_options": 0,
    }


def test_simple_open_final_checkpoint_resign_rebinds_compactness_policy_before_invalid_json_fallback(
    monkeypatch,
):
    """A POI-free meal policy can change the final signed checkpoint identity.

    The route contract is compiled before ``_apply_resolved_clarification_checkpoint``
    copies the completed meal policy back into the checkpoint and re-signs it.
    That final re-sign must also update the strict compactness policy and the
    portable route-contract fingerprint; otherwise the typed fallback gate
    correctly rejects its own stale provenance and an invalid DaySlot response
    becomes ``DAY_SLOT_FALLBACK_UNAVAILABLE``.
    """

    clear_database()
    message = "今年国庆参观北京高校两日游，晚上看北京夜景。10月1日到2日，中等预算，1人。每天午餐想体验当地特色美食。"
    with open_db() as connection:
        service = AgentService(connection)
        meal_policy = service.meal_grounding_policy.analyze(
            message,
            city="北京",
            budget="medium",
            day_count=2,
        )
        initial_contract = service._request_intent_contract(
            message,
            {"dates": ["2026-10-01", "2026-10-02"]},
            meal_policy,
            simple_open_profile=True,
        )
        request_context = signed_route_fallback_context()
        checkpoint = request_context["clarificationCheckpoint"]
        meal_spec = {
            "intentType": "meal",
            "frequency": "one",
            "allowedDayNumbers": [1, 2],
            "experienceFamilies": ["meal"],
            "accessPolicy": "verified_amap_food_service",
            "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
            "timeWindow": {"start": "12:00", "end": "13:15"},
            "detourTolerance": None,
            "evidenceFreshness": {
                "maxAgeHours": 24,
                "requiredForControlledAccess": False,
                "requiredForPublicOutdoor": False,
                "allowExplicitNoClosure": False,
            },
            "confidence": 0.9,
            "unresolvedDimensions": ["meal.detourTolerance"],
            "source": "server_authored_meal_experience_policy",
        }
        checkpoint["experienceSpecs"] = [copy.deepcopy(meal_spec)]
        checkpoint["fingerprint"] = ClarificationCheckpointService._fingerprint(
            {key: value for key, value in checkpoint.items() if key != "fingerprint"}
        )
        initial_contract.update(
            {
                "clarificationRequired": False,
                "clarificationReason": None,
                "clarificationCheckpointId": checkpoint["checkpointId"],
                "clarificationDecisionSource": "controller_semantic_choice",
                "clarificationAnswers": copy.deepcopy(checkpoint["resolvedAnswers"]),
                # Model the first typed compile: the resolved option supplies
                # the compact policy, rather than reusing a pre-existing v2
                # adjacent contract that would hide the final-resign timing.
                "routeDecisionContract": {
                    key: copy.deepcopy(request_context["requestIntentContract"]["routeDecisionContract"][key])
                    for key in (
                        "mobilityProfile",
                        "detourTolerance",
                        "detourToleranceSource",
                    )
                },
            }
        )
        request_context["requestIntentContract"] = service._request_contract_after_clarification(
            initial_contract,
            checkpoint,
            request_context,
        )
        pre_final_resign_fingerprint = checkpoint["fingerprint"]
        request_context["canonicalRequestContext"] = {
            "requestIntentContract": copy.deepcopy(request_context["requestIntentContract"]),
            "clarificationCheckpoint": copy.deepcopy(checkpoint),
            "experienceSpecs": copy.deepcopy(checkpoint["experienceSpecs"]),
        }
        request_context["routeDecisionContract"] = {"fingerprint": "stale_top_level_alias"}

        service._apply_resolved_clarification_checkpoint(request_context, checkpoint)

        final_checkpoint = request_context["clarificationCheckpoint"]
        route_contract = request_context["requestIntentContract"]["routeDecisionContract"]
        compactness_policy = route_contract["provenance"]["compactnessPolicy"]
        assert final_checkpoint["fingerprint"] != pre_final_resign_fingerprint
        assert final_checkpoint["experienceSpecs"][0]["detourTolerance"] == route_contract["detourTolerance"]
        assert compactness_policy["checkpointFingerprint"] == final_checkpoint["fingerprint"]
        assert RouteInsertionScorer.normalized_route_decision_contract(route_contract) is not None
        assert (
            request_context["canonicalRequestContext"]["requestIntentContract"]
            == request_context["requestIntentContract"]
        )
        assert request_context["canonicalRequestContext"]["clarificationCheckpoint"] == final_checkpoint
        assert request_context["routeDecisionContract"] == route_contract
        assert service._can_fallback_initial_day_slots(request_context) is True

        monkeypatch.setattr(service, "_call_initial_plan_provider", lambda _context: "{invalid-json")
        monkeypatch.setattr(
            service.output_repair_service,
            "repair",
            lambda *_args, **_kwargs: (None, {"status": "skipped"}),
        )
        events: list[dict] = []
        fallback = service._generate_initial_day_slot_output(request_context, events)
        write_counts = {
            table: connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            for table in (
                "agent_plan_proposals",
                "itinerary_versions",
                "itinerary_patches",
                "route_options",
            )
        }

    assert fallback.mode == "day_slots"
    assert "DAY_SLOT_FALLBACK_UNAVAILABLE" not in fallback.warnings
    assert write_counts == {
        "agent_plan_proposals": 0,
        "itinerary_versions": 0,
        "itinerary_patches": 0,
        "route_options": 0,
    }


def test_signed_compactness_rebind_requires_finally_validated_relative_strict_option_policy():
    """A persisted trigger is not authority to self-sign a new checkpoint."""

    context = signed_route_fallback_context()
    route_contract = copy.deepcopy(context["requestIntentContract"]["routeDecisionContract"])
    original = copy.deepcopy(route_contract)

    assert (
        AgentService._rebind_signed_compactness_policy_checkpoint(
            route_contract,
            checkpoint_fingerprint="f" * 64,
        )
        is False
    )
    assert route_contract == original


