@pytest.mark.parametrize("legacy_transport", ["待确认", "公交地铁优先"])
@pytest.mark.parametrize(
    "broken_boundary",
    [
        "request_not_sufficient",
        "clarification_still_required",
        "checkpoint_unresolved",
        "route_contract_not_ready",
        "route_contract_missing_fields",
        "route_contract_fingerprint_drift",
        "route_contract_source_drift",
        "route_contract_v2_without_topology",
        "route_contract_product_policy_drift",
        "request_checkpoint_identity_drift",
        "city_missing",
        "signed_checkpoint_source_drift",
        "signed_option_semantic_drift",
        "compactness_checkpoint_fingerprint_drift",
        "checkpoint_source_user_turn_missing",
        "route_answer_source_drift",
        "route_answer_source_user_turn_drift",
    ],
)
def test_simple_open_typed_transport_fallback_gate_fails_closed(
    broken_boundary,
    legacy_transport,
):
    context = signed_route_fallback_context(legacy_transport=legacy_transport)
    route_contract = context["requestIntentContract"]["routeDecisionContract"]

    def reseal_route_contract() -> None:
        portable = RouteInsertionScorer.build_route_decision_contract(
            source="request_intent_contract",
            provenance=route_contract["provenance"],
            detour_tolerance=route_contract["detourTolerance"],
            mobility_profile=route_contract["mobilityProfile"],
            adjacent_leg_constraint=route_contract["adjacentLegConstraint"],
            topology_constraint=route_contract["topologyConstraint"],
        )
        assert portable is not None
        route_contract.update(portable)

    def reseal_checkpoint() -> None:
        checkpoint = context["clarificationCheckpoint"]
        checkpoint["fingerprint"] = ClarificationCheckpointService._fingerprint(
            {key: value for key, value in checkpoint.items() if key != "fingerprint"}
        )

    if broken_boundary == "request_not_sufficient":
        context["simpleOpenInitialRequestSufficient"] = False
    elif broken_boundary == "clarification_still_required":
        context["requestIntentContract"]["clarificationRequired"] = True
    elif broken_boundary == "checkpoint_unresolved":
        context["clarificationCheckpoint"]["status"] = "awaiting_answer"
        context["clarificationCheckpoint"]["unresolvedDimensions"] = ["route_decision.mobility_profile"]
        context["clarificationCheckpoint"]["fingerprint"] = ClarificationCheckpointService._fingerprint(
            {key: value for key, value in context["clarificationCheckpoint"].items() if key != "fingerprint"}
        )
    elif broken_boundary == "route_contract_not_ready":
        route_contract["status"] = "awaiting_clarification"
    elif broken_boundary == "route_contract_missing_fields":
        route_contract["missingFields"] = ["mobilityProfile"]
    elif broken_boundary == "route_contract_fingerprint_drift":
        route_contract["fingerprint"] = "0" * 64
    elif broken_boundary == "route_contract_source_drift":
        portable = RouteInsertionScorer.build_route_decision_contract(
            source="client_attempt",
            provenance=route_contract["provenance"],
            detour_tolerance=route_contract["detourTolerance"],
            mobility_profile=route_contract["mobilityProfile"],
            adjacent_leg_constraint=route_contract["adjacentLegConstraint"],
            topology_constraint=route_contract["topologyConstraint"],
        )
        assert portable is not None
        route_contract.update(portable)
    elif broken_boundary == "route_contract_v2_without_topology":
        portable = RouteInsertionScorer.build_route_decision_contract(
            source="request_intent_contract",
            provenance=route_contract["provenance"],
            detour_tolerance=route_contract["detourTolerance"],
            mobility_profile=route_contract["mobilityProfile"],
        )
        assert portable is not None
        for key in (
            "adjacentLegConstraint",
            "adjacentLegConstraintSource",
            "topologyConstraint",
            "topologyConstraintSource",
        ):
            route_contract.pop(key, None)
        route_contract.update(portable)
        route_contract["schemaVersion"] = "route-decision-contract-v2"
    elif broken_boundary == "route_contract_product_policy_drift":
        route_contract["adjacentLegConstraint"] = {
            "candidateSearchRadiusMeters": 4900.0,
            "maxProviderTravelMinutes": 44.0,
        }
        route_contract["topologyConstraint"] = {"maxBacktrackRatio": 0.14}
        reseal_route_contract()
    elif broken_boundary == "request_checkpoint_identity_drift":
        context["requestIntentContract"]["clarificationCheckpointId"] = "clarify_other"
    elif broken_boundary == "city_missing":
        context["selectedCity"] = ""
    elif broken_boundary == "signed_checkpoint_source_drift":
        context["clarificationCheckpoint"]["sourceAssistantTurnId"] = "turn_other"
        context["clarificationCheckpoint"]["fingerprint"] = ClarificationCheckpointService._fingerprint(
            {key: value for key, value in context["clarificationCheckpoint"].items() if key != "fingerprint"}
        )
    elif broken_boundary == "signed_option_semantic_drift":
        answer = next(
            item
            for item in context["clarificationCheckpoint"]["resolvedAnswers"]
            if item["dimensionId"] == "route_decision.detour_tolerance"
        )
        answer["semanticValue"]["detourTolerance"]["maxDetourRatio"] = 0.2
        reseal_checkpoint()
    elif broken_boundary == "compactness_checkpoint_fingerprint_drift":
        route_contract["provenance"]["compactnessPolicy"]["checkpointFingerprint"] = "f" * 64
        reseal_route_contract()
    elif broken_boundary == "checkpoint_source_user_turn_missing":
        context["clarificationCheckpoint"].pop("sourceUserTurnId")
        reseal_checkpoint()
        route_contract["provenance"]["compactnessPolicy"]["checkpointFingerprint"] = context["clarificationCheckpoint"][
            "fingerprint"
        ]
        reseal_route_contract()
    elif broken_boundary == "route_answer_source_drift":
        context["clarificationCheckpoint"]["questions"][0]["allowFreeText"] = True
        context["clarificationCheckpoint"]["resolvedAnswers"][0]["source"] = "manual_normalized"
        context["requestIntentContract"]["clarificationAnswers"] = copy.deepcopy(
            context["clarificationCheckpoint"]["resolvedAnswers"]
        )
        reseal_checkpoint()
        route_contract["provenance"]["compactnessPolicy"]["checkpointFingerprint"] = context["clarificationCheckpoint"][
            "fingerprint"
        ]
        reseal_route_contract()
    elif broken_boundary == "route_answer_source_user_turn_drift":
        context["clarificationCheckpoint"]["resolvedAnswers"][0]["sourceUserTurnId"] = "turn_other"
        context["requestIntentContract"]["clarificationAnswers"] = copy.deepcopy(
            context["clarificationCheckpoint"]["resolvedAnswers"]
        )
        reseal_checkpoint()
        route_contract["provenance"]["compactnessPolicy"]["checkpointFingerprint"] = context["clarificationCheckpoint"][
            "fingerprint"
        ]
        reseal_route_contract()

    with open_db() as connection:
        service = AgentService(connection)
        assert service._can_fallback_initial_day_slots(context) is False


