def test_explicit_soft_meal_builds_complete_stable_poi_free_experience_spec():
    clear_database()
    message = route_ready_request("北京两日游，路途中品尝北京当地特色美食")
    with open_db() as connection:
        service = AgentService(connection)
        meal_policy = service.meal_grounding_policy.analyze(
            message,
            city="北京",
            budget="medium",
            day_count=2,
        )
        first = service._request_intent_contract(
            message,
            {"dates": ["2026-10-01", "2026-10-02"]},
            meal_policy,
        )
        second = service._request_intent_contract(
            message,
            {"dates": ["2026-10-01", "2026-10-02"]},
            meal_policy,
        )

    first_spec = next(item for item in first["experienceSpecs"] if item["intentType"] == "meal")
    second_spec = next(item for item in second["experienceSpecs"] if item["intentType"] == "meal")
    assert first_spec == second_spec
    assert first_spec == {
        "intentType": "meal",
        "frequency": "one",
        "allowedDayNumbers": [1, 2],
        "experienceFamilies": ["meal"],
        "accessPolicy": "verified_amap_food_service",
        "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
        "timeWindow": {"start": "12:00", "end": "13:15"},
        "detourTolerance": {
            "maxGeneralizedCostDelta": 20.0,
            "maxDetourRatio": 0.2,
        },
        "evidenceFreshness": {
            "maxAgeHours": 24,
            "requiredForControlledAccess": False,
            "requiredForPublicOutdoor": False,
            "allowExplicitNoClosure": False,
        },
        "confidence": 0.84,
        "unresolvedDimensions": [],
        "source": "server_authored_meal_experience_policy",
        "fieldProvenance": {
            "frequency": "goal_ledger.meal_cardinality",
            "allowedDayNumbers": "goal_ledger.meal_allowed_days",
            "experienceFamilies": "meal_grounding_policy.authoritative_request_semantics",
            "accessPolicy": "meal_grounding_policy.amap_food_service_contract",
            "distinctnessPolicy": "goal_ledger.meal_occurrence_distribution",
            "timeWindow": "meal_grounding_policy.meal_label_schedule",
            "detourTolerance": "route_decision_contract.detour_tolerance",
            "evidenceFreshness": "meal_grounding_policy.consumer_evidence_contract",
            "confidence": "meal_grounding_policy.route_anchor_confidence",
        },
        "specFingerprint": first_spec["specFingerprint"],
    }
    assert len(first_spec["specFingerprint"]) == 64
    runtime_policy = service._experience_spec_policy_for_intent(
        first,
        "meal",
        next(item for item in first["requiredIntents"] if item["intentType"] == "meal"),
    )
    assert runtime_policy["localExperienceConstraint"] == first["localExperienceConstraint"]
    runtime_policy_without_fingerprint = copy.deepcopy(runtime_policy)
    runtime_policy_without_fingerprint.pop("specFingerprint")
    assert runtime_policy["specFingerprint"] == ClarificationCheckpointService._fingerprint(
        {
            "schemaVersion": "experience-spec-runtime-policy-v1",
            **runtime_policy_without_fingerprint,
        }
    )
    assert not {
        "poi",
        "candidate",
        "amapId",
        "name",
        "address",
        "longitude",
        "latitude",
    }.intersection(first_spec)


