def test_server_generic_fallback_uses_each_eligible_night_for_plain_and_every_night_requests():
    clear_database()
    base_context = {
        "selectedCity": "北京",
        "understoodRequirements": {
            "fields": {
                "travelDate": "2026-10-01 到 2026-10-02",
                "travelDays": "2天",
                "partySize": "1人",
                "budget": "中等预算",
                "transportPreference": "公交地铁优先",
            }
        },
        "resolvedTripDates": {"status": "resolved", "dates": ["2026-10-01", "2026-10-02"]},
    }
    with open_db() as connection:
        service = AgentService(connection)
        singular_message = "北京高校两日游，晚上看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先。"
        singular_contract = service._request_intent_contract(
            singular_message,
            base_context["resolvedTripDates"],
            SimpleNamespace(meal_slots=[]),
        )
        singular = service._server_generic_day_slots_fallback(
            {**base_context, "latestUserMessage": singular_message, "requestIntentContract": singular_contract},
            [],
            fallback_reason="test",
        )
        every_message = singular_message.replace("晚上看", "每晚都看")
        every_contract = service._request_intent_contract(
            every_message,
            base_context["resolvedTripDates"],
            SimpleNamespace(meal_slots=[]),
        )
        every = service._server_generic_day_slots_fallback(
            {**base_context, "latestUserMessage": every_message, "requestIntentContract": every_contract},
            [],
            fallback_reason="test",
        )

    assert singular is not None and every is not None
    assert len([slot for slot in singular.day_slots if slot.kind == "night_view"]) == 2
    assert {slot.day_number for slot in singular.day_slots if slot.kind == "night_view"} == {1, 2}
    assert len([slot for slot in every.day_slots if slot.kind == "night_view"]) == 2
    assert {slot.day_number for slot in every.day_slots if slot.kind == "night_view"} == {1, 2}


