def test_structured_entity_binding_is_independent_of_raw_need_language():
    for raw_need in ("夜景", "night view", "城市夜游"):
        intent = PoiIntent(
            raw_need=raw_need,
            city="北京",
            day_number=1,
            time_window="19:00-21:00",
            intent_type="night_view",
            specificity="exact_entity",
            entity_binding_mode="category",
        )
        assert AgentService._exact_entity_requirement(intent) is None

    exact = PoiIntent(
        raw_need="夜景",
        city="北京",
        day_number=1,
        time_window="19:00-21:00",
        intent_type="night_view",
        specificity="exact_entity",
        entity_binding_mode="exact_entity",
        exact_entity="中央电视塔",
    )
    assert AgentService._exact_entity_requirement(exact) == "中央电视塔"


