def test_selected_choice_replay_reuses_committed_patch_after_consume_crash():
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        session = ConversationService(connection).create_session("北京", "choice replay")
        now = datetime.now(timezone.utc).isoformat()
        source_assistant = service._insert_turn(
            session.session_id,
            "assistant",
            "请选择候选",
            "active",
            agent_response_json={
                "choiceOptions": [
                    {
                        "id": "choice_poi",
                        "kind": "poi_candidate",
                        "segmentId": "seg_a",
                        "candidateRecordId": "candidate_a",
                    }
                ]
            },
        )
        source_user = service._insert_turn(
            session.session_id,
            "user",
            "选择 Agent 选项",
            "active",
            agent_request_json={
                "selectedAgentChoice": {"sourceAssistantTurnId": source_assistant, "choiceId": "choice_poi"}
            },
        )
        connection.execute(
            "INSERT INTO itinerary_versions (id, session_id, plan_id, version_number, source_type, source_turn_id, source_patch_id, snapshot_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                "ver_choice",
                session.session_id,
                session.active_plan_id,
                1,
                "agent",
                source_user,
                "patch_choice",
                "{}",
                now,
            ),
        )
        connection.execute(
            "UPDATE conversation_sessions SET active_version_id = ? WHERE id = ?",
            ("ver_choice", session.session_id),
        )
        connection.execute(
            "INSERT INTO itinerary_patches (id, session_id, plan_id, base_version_id, result_version_id, source_type, source_turn_id, planning_run_id, operations_json, validation_status, validation_errors_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                "patch_choice",
                session.session_id,
                session.active_plan_id,
                None,
                "ver_choice",
                "agent",
                source_user,
                None,
                json.dumps(
                    [{"op": "replace_segment_poi_from_candidate", "segmentId": "seg_a", "candidateId": "candidate_a"}]
                ),
                "accepted",
                "[]",
                now,
            ),
        )
        connection.commit()
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()
        user_turn = service._turn_response(source_user)
        request_context = {
            "selectedAgentChoice": {
                "sourceAssistantTurnId": source_assistant,
                "choiceId": "choice_poi",
                "option": {"segmentId": "seg_a", "candidateRecordId": "candidate_a"},
            }
        }
        response = service._replay_selected_agent_choice_if_committed(
            session.session_id, user_turn, session_row, request_context, request_context["selectedAgentChoice"]
        )

        assert response is not None
        assert response.version and response.version.id == "ver_choice"
        assert connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0] == 1
        persisted = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?", (source_assistant,)
            ).fetchone()[0]
        )
        assert persisted["consumedChoiceIds"] == ["choice_poi"]


def test_structured_retry_dispatches_to_bounded_staged_executor_without_generic_tools(monkeypatch):
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        session = ConversationService(connection).create_session("北京", "structured retry")
        seeded = apply_recorded_agent_patch(
            connection,
            session.active_plan_id,
            [ItineraryPatchOperation(op="replace_itinerary", fullItinerary=two_day_pending_night_view_snapshot())],
            source_type="agent",
        )
        connection.execute(
            "UPDATE itinerary_segments SET notes = ? WHERE id = ?",
            (
                "groundingStatus: waiting_for_poi_grounding; retry fixture",
                "seg_night_d2_placeholder",
            ),
        )
        connection.commit()
        user_turn_id = service._insert_turn(session.session_id, "user", "选择 Agent 选项", "active")
        session_row = service._session(session.session_id)
        captured: dict[str, Any] = {}
        sentinel = object()

        def fake_staged(session_id, turn_id, content, context):
            captured.update({"sessionId": session_id, "turnId": turn_id, "content": content, "context": context})
            return sentinel

        monkeypatch.setattr(service, "_generate_with_initial_staged_pipeline", fake_staged)
        selected = {
            "sourceAssistantTurnId": "turn_source",
            "choiceId": "retry:seg_night_d2_placeholder",
            "option": {
                "kind": "retry_unresolved_slot",
                "slotId": "seg_night_d2_placeholder",
                "segmentId": "seg_night_d2_placeholder",
                "dayNumber": 2,
                "timeWindow": "19:30-21:00",
                "reason": "waiting_for_poi_grounding",
                "activeVersionId": seeded.version.id,
            },
        }

        response = service._dispatch_selected_agent_choice(
            session.session_id,
            user_turn_id,
            "选择 Agent 选项",
            service._turn_response(user_turn_id),
            session_row,
            {"selectedAgentChoice": selected},
            selected,
        )

    assert response is sentinel
    assert captured["context"]["selectedRetrySlotId"] == "seg_night_d2_placeholder"
    assert captured["context"]["allowedToolsOverride"] == ["read_itinerary", "resolve_poi", "patch_itinerary"]
    assert "ticket_lookup" not in captured["context"]["allowedToolsOverride"]
    assert "web_search" not in captured["context"]["allowedToolsOverride"]


