def test_selected_clarification_choice_recompiles_stale_night_cardinality_contract():
    clear_database()
    source_request = route_ready_request(
        "今年国庆参观北京高校两日游，晚上看北京城市夜景。"
        "10月1日到2日，中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
    )
    clarification_value = "只安排一晚街区或滨水夜游，不登塔"
    semantic_message = f"{source_request}\n{clarification_value}"
    stale_contract = {
        "schemaVersion": "request-intent-contract-v2",
        "requiredIntents": [
            {
                "goalId": "goal_campus_visit",
                "intentType": "campus_visit",
                "requiredMin": 2,
                "preferredCount": 2,
                "maxCount": 2,
            },
            {
                "goalId": "goal_night_view",
                "intentType": "night_view",
                "requiredMin": 1,
                "preferredCount": 2,
                "maxCount": 2,
                "cardinalitySource": "clarification_required",
            },
        ],
        "clarificationRequired": True,
        "clarificationReason": "night_view_cardinality_ambiguous",
    }
    dates = {
        "status": "resolved",
        "startDate": "2026-10-01",
        "endDate": "2026-10-02",
        "dayCount": 2,
        "dates": ["2026-10-01", "2026-10-02"],
    }

    with open_db() as connection:
        service = AgentService(connection)
        session = ConversationService(connection).create_session(
            "北京",
            "night clarification restore",
        )
        source_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "请选择夜景频次。",
            "active",
            agent_request_json={
                "sourceUserRequest": source_request,
                "effectiveUserMessage": source_request,
                "resolvedTripDates": dates,
                "requestIntentContract": stale_contract,
                "activeVersionId": None,
            },
        )
        context: dict[str, Any] = {
            "selectedCity": "北京",
            "latestUserMessage": "只安排一晚街区或滨水夜游，不以登塔观景为目标。",
            "selectedAgentChoice": {
                "sourceAssistantTurnId": source_turn_id,
                "choiceId": "index:3",
                "action": None,
                "semanticMessage": semantic_message,
                "option": {
                    "index": 3,
                    "kind": "preset",
                    "label": "只安排一晚街区或滨水夜游，不以登塔观景为目标。",
                    "value": clarification_value,
                },
            },
        }

        service._restore_request_intent_contract(session.session_id, context)

    contract = context["requestIntentContract"]
    night = next(item for item in contract["requiredIntents"] if item["intentType"] == "night_view")
    assert context["effectiveUserMessage"] == semantic_message
    assert night["requiredMin"] == 1
    assert night["preferredCount"] == 1
    assert night["maxCount"] == 1
    assert night["cardinalitySource"] == "explicit_single_evening"
    assert contract["clarificationRequired"] is False
    assert context["canonicalRequestContext"]["requestIntentContract"] == contract


