def test_initial_staged_pipeline_creates_version_without_react_search_loop(monkeypatch):
    clear_database()
    weather_provider_calls: list[str] = []
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)

    def fail_if_weather_provider_called(*_args, **_kwargs):
        weather_provider_calls.append("called")
        raise AssertionError("unsupported staged dates must not call the weather provider")

    monkeypatch.setattr(ItineraryService, "_refresh_weather_signal", fail_if_weather_provider_called)
    provider = StagedInitialProvider(two_day_initial_day_slot_output())
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，安排一次北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        weather_rows = connection.execute(
            "SELECT date, data_status, failure_reason, provider_name FROM weather_signals"
        ).fetchall()
        ticket_count = connection.execute("SELECT COUNT(*) FROM ticket_lookup_results").fetchone()[0]
        version_sources = connection.execute(
            "SELECT source_type FROM itinerary_versions ORDER BY version_number ASC"
        ).fetchall()
        patch_row = connection.execute(
            "SELECT id, result_version_id, planning_run_id FROM itinerary_patches WHERE source_turn_id = ? AND validation_status = 'accepted'",
            (response.assistant_turn.id,),
        ).fetchone()

    today = date.today()
    expected_year = today.year if date(today.year, 10, 1) >= today else today.year + 1
    expected_dates = [f"{expected_year}-10-01", f"{expected_year}-10-02"]
    assert provider.tool_loop_calls == 0
    assert provider.calls == 1
    assert provider.contexts[0]["resolvedTripDates"]["startDate"] == expected_dates[0]
    assert provider.contexts[0]["resolvedTripDates"]["endDate"] == expected_dates[1]
    assert provider.contexts[0]["toolBudget"]["web_search"] == 0
    assert provider.contexts[0]["toolBudget"]["ticket_lookup"] == 0
    assert provider.contexts[0]["toolBudget"]["amap_weather"] == 0
    assert response.version is None
    assert response.itinerary is None
    assert response.terminal_status == "candidate_refresh_required"
    assert active["active_version_id"] is None
    assert response.preference_memory is not None
    assert "高校/校园参观" in response.preference_memory.memory_text
    assert "夜景/城市观景" in response.preference_memory.memory_text
    assert "中等预算" in response.preference_memory.memory_text
    assert "1 人" in response.preference_memory.memory_text
    assert patch_row is None
    assert response.planning_run.run_type == "agent_staged_pipeline_waiting"
    assert version_sources == []
    assert weather_rows == []
    assert weather_provider_calls == []
    assert ticket_count == 0
    event_names = {event.label for event in response.planning_steps}
    assert "web_search" not in event_names
    assert "ticket_lookup" not in event_names
    assert "amap_weather" not in event_names
    assert "patch_itinerary" not in event_names
    assert not any("maxToolRounds" in warning for warning in response.warnings)
    assert {event.type for event in response.planning_steps} >= {
        "generate_day_slots",
        "decompose_intent_pools",
        "collect_candidates",
    }
    assert not any("deterministic_fallback_full_itinerary" in warning for warning in response.warnings)
    output = AgentInitialPlanOutput.model_validate(two_day_initial_day_slot_output())
    assert output.intent_pools[0].candidate_hints
    assert output.intent_pools[0].hint_policy == "llm_common_knowledge_hint"


def test_generic_local_food_can_remain_unmaterialized_without_city_answer_fallback(monkeypatch):
    clear_database()
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: False)
    food_pois = [
        MapPoiResponse(
            id=f"B0000FOOD{index:02d}",
            name=f"北京本地菜餐厅{index}",
            type="餐饮服务;中餐厅",
            city="北京",
            district="测试区",
            address=f"北京本地菜餐厅{index} 地址",
            longitude=116.397026 + index * 0.002,
            latitude=39.918058 + index * 0.002,
            category="food",
            source=AMAP_PLACE_SOURCE,
            sourceNote="高德 WebService POI 搜索",
            confidence=0.94,
            providerTypeCode="050100",
            tags=["地方风味"],
            sourceClaims=[
                {
                    "claimKey": "local_food_context",
                    "stance": "support",
                    "sourceName": "fixture-guide",
                    "sourceUrlHash": "a" * 64,
                }
            ],
            photos=[],
        )
        for index in range(1, 7)
    ]

    def search_with_food_candidates(self, city, keyword, category="all", limit=10):
        if category == "food" or "餐" in str(keyword) or "美食" in str(keyword):
            meal_name = re.sub(r"^(北京|北京市)\s*", "", str(keyword)).strip() or "北京菜"
            scoped_food_pois = [
                poi.model_copy(
                    update={
                        "id": f"B{abs(hash((meal_name, index))) % 10**12:012d}",
                        "name": f"北京本地菜餐厅·{meal_name}{index}号店",
                    }
                )
                for index, poi in enumerate(food_pois, start=1)
            ]
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=scoped_food_pois,
            )
        return fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)

    monkeypatch.setattr(MapPoiService, "search", search_with_food_candidates)
    monkeypatch.setattr(MapPoiService, "search_nearby", fake_amap_search_nearby_route_compatible)
    payload = two_day_initial_day_slot_output()
    payload["daySlots"] = [item for item in payload["daySlots"] if not str(item["slotId"]).endswith("afternoon_campus")]
    payload["intentPools"][0]["assignToSlots"] = ["day1_morning_campus", "day2_morning_campus"]
    payload["intentPools"][0]["targetCount"] = 2
    provider = StagedInitialProvider(payload)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游。10月1日到2日，2天，中等预算，1人。路途中能品尝北京当地特色美食。"
                )
            ),
        )

        assert response.itinerary is not None, json.dumps(
            {
                "reply": response.assistant_turn.content,
                "events": [
                    {
                        "type": item.type,
                        "metadata": item.metadata,
                    }
                    for item in response.planning_steps
                ],
            },
            ensure_ascii=False,
            sort_keys=True,
        )
    meal_segments = [segment for day in response.itinerary.days for segment in day.segments if segment.kind == "meal"]
    assert meal_segments == []
    assert all(
        segment.poi.source == AMAP_PLACE_SOURCE
        for day in response.itinerary.days
        for segment in day.segments
        if segment.poi.amap_id
    )


def test_candidate_hints_are_query_seeds_and_matching_amap_result_can_be_persisted(monkeypatch):
    clear_database()
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: False)
    search_calls: list[str] = []
    payload = two_day_initial_day_slot_output()
    payload["daySlots"] = [item for item in payload["daySlots"] if item["slotId"] != "day2_night_view"]
    payload["intentPools"][1]["targetCount"] = 1
    payload["intentPools"][1]["assignToSlots"] = ["day1_night_view"]
    payload["intentPools"][1]["candidateHints"] = ["中国尊", "奥林匹克塔"]

    def search_with_amap_variant(self, city, keyword, category="all", limit=10):
        search_calls.append(str(keyword))
        if str(keyword) == "中国尊":
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[
                    MapPoiResponse(
                        id="B0CHINAZUN1",
                        name="中国尊城市广场夜景观景点",
                        type="风景名胜;广场;城市地标;夜景观景点",
                        city=city,
                        district="测试区",
                        address="光华路",
                        longitude=116.397026,
                        latitude=39.918058,
                        category=category,
                        source=AMAP_PLACE_SOURCE,
                        sourceNote="高德 WebService POI 搜索",
                        confidence=0.94,
                        openTimeToday="00:00-24:00",
                        photos=[],
                    )
                ],
            )
        return fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)

    monkeypatch.setattr(MapPoiService, "search", search_with_amap_variant)
    provider = StagedInitialProvider(payload)
    request_text = "今年国庆参观北京高校两日游，只在第一晚安排一次北京夜景。10月1日到2日，2天，中等预算，1人"
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        record_completed_night_experience_context(
            connection,
            session.session_id,
            allowed_day_numbers=[1],
            trip_day_count=2,
            source_request_override=route_ready_request(request_text),
        )
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(content=clarified_route_ready_request(request_text)),
        )
        pending_candidate_ids = {
            str(item.get("id") or item.get("amapId") or "")
            for row in connection.execute(
                "SELECT candidates_json FROM amap_poi_candidates WHERE session_id = ?",
                (session.session_id,),
            ).fetchall()
            for item in json.loads(row["candidates_json"] or "[]")
            if isinstance(item, dict)
        }

    assert "中国尊" in search_calls
    assert response.version is not None
    names = [
        segment.poi.name
        for day in response.itinerary.days
        for segment in day.segments
        if segment.kind in {"visit", "activity"}
    ]
    assert "中国尊城市广场夜景观景点" in names
    assert "中国尊" not in names
    assert "B0CHINAZUN1" not in pending_candidate_ids
    assert not any(slot.intent_type == "night_view" for day in response.itinerary.days for slot in day.pending_slots)


def test_fixed_single_night_portfolio_runs_real_staging_and_terminalizes_selected_anchors(monkeypatch):
    """Exercise the fixed Goal through the real Portfolio producer/consumer path.

    The deterministic candidates below locate contract breaks only.  They are
    not recorded-real evidence and cannot satisfy the external Route gate.
    """

    clear_database()
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: True)
    payload = two_day_initial_day_slot_output()
    payload["daySlots"] = [item for item in payload["daySlots"] if item["slotId"] != "day2_night_view"]
    payload["intentPools"][1]["targetCount"] = 1
    payload["intentPools"][1]["assignToSlots"] = ["day1_night_view"]
    payload["intentPools"][1]["candidateHints"] = ["北京城市公共观景台"]
    search_calls: list[dict[str, object]] = []

    def fixed_goal_search(self, city, keyword, category="all", limit=10):
        keyword_text = str(keyword)
        observed_at = datetime.now(timezone.utc).isoformat()
        if any(marker in keyword_text for marker in ("观景", "夜景", "夜游", "中信大厦", "奥林匹克塔")):
            night_name = next(
                (marker for marker in ("北京城市公共观景台", "中信大厦", "奥林匹克塔") if marker in keyword_text),
                keyword_text,
            )
            pois = [
                MapPoiResponse(
                    id="B0WEAKPARK2",
                    name="测试水岸湿地公园",
                    type="风景名胜;公园广场;公园",
                    city=city,
                    district="测试区",
                    address="测试水岸地址",
                    longitude=116.419,
                    latitude=39.919,
                    category="scenic",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="deterministic rejected-family contract candidate",
                    providerTypeCode="110101",
                    tags=["湿地", "水岸", "公园"],
                    nightAvailabilityStatus="verified_open",
                    openTimeToday="18:00-23:00",
                    providerEvidenceQueriedAt=observed_at,
                    confidence=0.95,
                    photos=[],
                ),
                MapPoiResponse(
                    id="B0CITYVIEW1",
                    name=night_name,
                    type="风景名胜;旅游景点;城市阳台",
                    city=city,
                    district="测试区",
                    address="测试城市公共空间",
                    longitude=116.421,
                    latitude=39.921,
                    category="scenic",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="deterministic recorded-shaped contract candidate",
                    providerTypeCode="110000",
                    tags=["公共空间", "城市夜景", "天际线", "夜间观景"],
                    nightAvailabilityStatus="verified_open",
                    openTimeToday="18:00-23:00",
                    providerEvidenceQueriedAt=observed_at,
                    sourceClaims=[
                        {
                            "claimKey": "public_city_view_access",
                            "stance": "support",
                            "summary": "公共户外观景空间在夜间开放。",
                            "sourceName": "deterministic-contract-source",
                            "sourceUrlHash": "e" * 64,
                            "freshness": observed_at,
                        }
                    ],
                    confidence=0.95,
                    photos=[],
                ),
            ]
        elif category == "campus" or any(
            marker in keyword_text for marker in ("大学", "学院", "高等院校", "校区", "高校")
        ):
            campus_identity = hashlib.sha256(keyword_text.encode("utf-8")).hexdigest()[:10].upper()
            pois = [
                MapPoiResponse(
                    id=f"B0{campus_identity}",
                    name=f"测试大学{campus_identity[:4]}",
                    type="科教文化服务;学校;高等院校",
                    city=city,
                    district="测试区",
                    address="测试高校地址",
                    longitude=116.31 + int(campus_identity[:2], 16) / 10000,
                    latitude=39.96 + int(campus_identity[2:4], 16) / 10000,
                    category="campus",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="deterministic canonical-shape contract candidate",
                    providerTypeCode="141201",
                    confidence=0.95,
                    photos=[],
                )
            ]
        elif category == "food" or any(marker in keyword_text for marker in ("美食", "餐饮", "午餐", "小吃")):
            pois = [
                MapPoiResponse(
                    id=f"B0MEAL000{index}",
                    name=f"测试地方餐饮候选{index}",
                    type="餐饮服务;中餐厅;地方菜",
                    city=city,
                    district="测试区",
                    address=f"测试餐饮地址{index}",
                    longitude=116.37 + index * 0.004,
                    latitude=39.90 + index * 0.004,
                    category="food",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="deterministic canonical-shape contract candidate",
                    providerTypeCode="050100",
                    tags=["地方风味"],
                    sourceClaims=[
                        {
                            "claimKey": "local_food",
                            "stance": "support",
                            "locality": city,
                            "evidenceSource": "provider_city_specific_fact",
                        }
                    ],
                    confidence=0.95,
                    photos=[],
                )
                for index in (1, 2)
            ]
        else:
            pois = []
        search_calls.append(
            {
                "keyword": keyword_text,
                "category": str(category),
                "candidateIds": [poi.id for poi in pois[:limit]],
                "candidateNames": [poi.name for poi in pois[:limit]],
            }
        )
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword,
            category=category,
            providerName="deterministic-contract-amap",
            queriedAt=datetime.now(timezone.utc),
            pois=pois[:limit],
        )

    def fixed_goal_nearby(
        self,
        city,
        longitude,
        latitude,
        keyword,
        category="all",
        radius=1500,
        limit=12,
        bypass_cache=False,
        **_kwargs,
    ):
        keyword_text = str(keyword)
        if any(marker in keyword_text for marker in ("观景", "夜景", "夜游", "中信大厦", "奥林匹克塔")):
            observed_at = datetime.now(timezone.utc).isoformat()
            poi = MapPoiResponse(
                id="B0CITYVIEW1",
                name="北京城市公共观景台",
                type="风景名胜;旅游景点;城市阳台",
                city=city,
                district="测试区",
                address="路线锚点附近的测试城市公共空间",
                longitude=float(longitude) + 0.0002,
                latitude=float(latitude) + 0.0002,
                category="scenic",
                source=AMAP_PLACE_SOURCE,
                sourceNote="deterministic recorded-shaped route-scoped contract candidate",
                providerTypeCode="110000",
                tags=["公共空间", "城市夜景", "天际线", "夜间观景"],
                nightAvailabilityStatus="verified_open",
                openTimeToday="18:00-23:00",
                providerEvidenceQueriedAt=observed_at,
                sourceClaims=[
                    {
                        "claimKey": "public_city_view_access",
                        "stance": "support",
                        "summary": "公共户外观景空间在夜间开放。",
                        "sourceName": "deterministic-contract-source",
                        "sourceUrlHash": "e" * 64,
                        "freshness": observed_at,
                    }
                ],
                confidence=0.95,
                photos=[],
            )
            search_calls.append(
                {
                    "keyword": keyword_text,
                    "category": str(category),
                    "candidateIds": [poi.id],
                    "candidateNames": [poi.name],
                }
            )
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="deterministic-contract-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[poi],
            )
        if any(marker in keyword_text for marker in ("市场", "市集", "菜市场")):
            observed_at = datetime.now(timezone.utc).isoformat()
            pois = [
                MapPoiResponse(
                    id=f"B0MARKET0{index}",
                    name=f"测试社区传统市场{index}",
                    type="购物服务;综合市场;农贸市场",
                    city=city,
                    district="测试区",
                    address=f"测试市场地址{index}",
                    longitude=float(longitude) + index * 0.0002,
                    latitude=float(latitude) + index * 0.0002,
                    category="market",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="deterministic recorded-shaped market contract candidate",
                    providerTypeCode="060703",
                    tags=["农贸市场", "社区商业", "传统市集"],
                    sourceClaims=[
                        {
                            "claimKey": "resident_market",
                            "stance": "support",
                            "summary": "面向附近居民的日常采购市场",
                            "sourceName": "deterministic-contract-source",
                            "sourceUrlHash": f"{index}" * 64,
                            "freshness": observed_at,
                        }
                    ],
                    confidence=0.95,
                    photos=[],
                )
                for index in (1, 2, 3)
            ][:limit]
            search_calls.append(
                {
                    "keyword": keyword_text,
                    "category": str(category),
                    "candidateIds": [poi.id for poi in pois],
                    "candidateNames": [poi.name for poi in pois],
                }
            )
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="deterministic-contract-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=pois,
            )
        return fake_amap_search_nearby_route_compatible(
            self,
            city,
            longitude,
            latitude,
            keyword,
            category=category,
            radius=radius,
            limit=limit,
            bypass_cache=bypass_cache,
        )

    monkeypatch.setattr(MapPoiService, "search", fixed_goal_search)
    monkeypatch.setattr(MapPoiService, "search_nearby", fixed_goal_nearby)

    class FixedGoalStagedProvider(StagedInitialProvider):
        def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
            checkpoint = context.get("clarificationCheckpoint")
            answers = checkpoint.get("resolvedAnswers") or [] if isinstance(checkpoint, dict) else []
            if not any(
                isinstance(item, dict) and item.get("dimensionId") == "route_decision.detour_tolerance"
                for item in answers
            ):
                return RouteDecisionDetourClarificationProvider().decide_autonomy(
                    context,
                    timeout_seconds=timeout_seconds,
                    repair_feedback=repair_feedback,
                )
            return super().decide_autonomy(
                context,
                timeout_seconds=timeout_seconds,
                repair_feedback=repair_feedback,
            )

    provider = FixedGoalStagedProvider(payload)
    fixed_request = (
        "2026年10月1日至10月2日，北京高校主题两日游，1人，公共交通，每日午餐体验当地特色美食，仅安排一晚公共城市夜景。"
    )

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "fixed single-night producer consumer")
        service = AgentService(
            connection,
            provider=provider,
            poi_resolution_service=FakePoiResolver({}),
        )
        clarification = service.send_message(
            session.session_id,
            AgentMessageRequest(content=fixed_request),
        )
        detour_choice = clarification.assistant_turn.choice_options[0]
        response = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="采用有界公交绕路容忍度并继续规划",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": clarification.assistant_turn.id,
                        "choiceId": detour_choice["id"],
                    }
                },
            ),
        )
        assistant_request_row = connection.execute(
            "SELECT agent_request_json, agent_response_json FROM conversation_turns WHERE id = ?",
            (response.assistant_turn.id,),
        ).fetchone()
        assistant_request_context = json.loads(assistant_request_row["agent_request_json"] or "{}")
        assistant_response_context = json.loads(assistant_request_row["agent_response_json"] or "{}")
        portfolio_rows = []
        for row in connection.execute(
            "SELECT status, failure_reason, summary_json FROM agent_plan_portfolios"
        ).fetchall():
            summary = json.loads(row["summary_json"] or "{}")
            portfolio_rows.append(
                {
                    "status": row["status"],
                    "failureReason": row["failure_reason"],
                    "proposalIds": summary.get("proposalIds"),
                    "visibleProposalIds": summary.get("visibleProposalIds"),
                    "failureReasonCounts": summary.get("failureReasonCounts"),
                    "classificationCounts": summary.get("classificationCounts"),
                    "briefMetrics": [
                        {
                            key: metric.get(key)
                            for key in (
                                "briefId",
                                "status",
                                "failureReason",
                                "reasonCodes",
                                "candidateEvaluationCount",
                                "routePairCount",
                                "routeStatus",
                                "verifierPassed",
                                "readinessStatus",
                            )
                        }
                        for metric in (summary.get("briefMetrics") or [])
                        if isinstance(metric, dict)
                    ],
                }
            )
        proposal_options = [
            item for item in response.assistant_turn.choice_options if item.get("action") == "select_plan_proposal"
        ]
        assert proposal_options, json.dumps(
            {
                "terminalStatus": response.terminal_status,
                "warnings": response.warnings,
                "buildPreviews": [
                    {
                        key: preview.get(key)
                        for key in (
                            "routeAnchorSelectedCount",
                            "persistableGroundedAnchorCount",
                            "requiredIntentCoverage",
                            "finalizationStatus",
                        )
                    }
                    for item in response.planning_steps
                    if item.type == "build_persistable_segment_plans"
                    and isinstance(
                        preview := item.metadata.get("resultPreview"),
                        dict,
                    )
                ],
                "stagingPreviews": [
                    item.metadata.get("resultPreview")
                    for item in response.planning_steps
                    if item.type == "portfolio_staging_performance"
                ],
                "actionOutcomes": [
                    {
                        "type": item.type,
                        "status": item.status,
                        "failureReason": item.failure_reason,
                        "resultPreview": item.metadata.get("resultPreview"),
                    }
                    for item in response.planning_steps
                    if item.type in {"agent_action_outcome", "agent_stop"}
                ],
                "eventTypes": [item.type for item in response.planning_steps],
                "pipelineFlags": {
                    "creativePortfolioMode": assistant_request_context.get("creativePortfolioMode"),
                    "explicitRuleSafeDraft": assistant_request_context.get("explicitRuleSafeDraft"),
                    "actualExecutionRoute": assistant_request_context.get("actualExecutionRoute"),
                },
                "persistedGroundingBlocker": (assistant_response_context.get("grounding") or {}).get(
                    "rootGlobalBlocker"
                ),
                "persistedStagingPerformance": (assistant_response_context.get("grounding") or {}).get(
                    "portfolioStagingPerformance"
                ),
                "portfolioRows": portfolio_rows,
                "searchCallCount": len(search_calls),
            },
            ensure_ascii=False,
            indent=2,
            default=str,
        )
        proposal_option = proposal_options[0]
        pre_adoption_counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )
        adopted = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="采用这个方案",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": response.assistant_turn.id,
                        "choiceId": proposal_option["id"],
                    }
                },
            ),
        )
        post_adoption_counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )
        duplicate_adoption = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="重复采用这个方案",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": response.assistant_turn.id,
                        "choiceId": proposal_option["id"],
                    }
                },
            ),
        )
        post_duplicate_counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    event_types = [item.type for item in response.planning_steps]
    assert "build_persistable_segment_plans" in event_types, json.dumps(
        {
            "terminalStatus": response.terminal_status,
            "assistantStatus": response.assistant_turn.status,
            "warnings": response.warnings,
            "choiceOptions": response.assistant_turn.choice_options,
            "events": [
                {
                    "type": item.type,
                    "status": item.status,
                    "failureReason": item.failure_reason,
                    "metadata": item.metadata,
                }
                for item in response.planning_steps
            ],
        },
        ensure_ascii=False,
        indent=2,
        default=str,
    )
    build_preview = next(
        item.metadata["resultPreview"]
        for item in response.planning_steps
        if item.type == "build_persistable_segment_plans"
    )
    assert build_preview["routeAnchorSelectedCount"] > 0
    assert build_preview["persistableGroundedAnchorCount"] == 0
    projection = proposal_options[0]["comparisonProjection"]
    materialized_segments = [
        segment for day in projection["days"] for segment in day.get("segments") or [] if isinstance(segment, dict)
    ]
    pending_slots = [item for item in projection.get("pendingSlots") or [] if isinstance(item, dict)]
    selected_slot_ids = {
        str(slot_id)
        for coverage in build_preview["requiredIntentCoverage"]
        for slot_id in coverage.get("resolvedSlotIds") or []
        if str(slot_id)
    }
    terminal_slot_ids = {
        str((segment.get("semanticMetadata") or {}).get("planningSlotId") or "") for segment in materialized_segments
    } | {str(item.get("planningSlotId") or "") for item in pending_slots}
    assert selected_slot_ids <= terminal_slot_ids, {
        "selectedSlotIds": sorted(selected_slot_ids),
        "terminalSlotIds": sorted(terminal_slot_ids),
    }
    assert materialized_segments
    assert all(
        (segment.get("semanticMetadata") or {}).get("consumerAdmissionReport", {}).get("scoreEligible") is True
        for segment in materialized_segments
    )
    night_segments = [
        (day["dayNumber"], segment)
        for day in projection["days"]
        for segment in day.get("segments") or []
        if isinstance(segment, dict)
        and str((segment.get("semanticMetadata") or {}).get("intentType") or "") == "night_view"
    ]
    assert len(night_segments) == 1
    assert night_segments[0][0] in {1, 2}
    assert "public_city_view" in json.dumps(
        night_segments[0][1].get("semanticMetadata") or {},
        ensure_ascii=False,
        sort_keys=True,
    )
    assert all(str((segment.get("poi") or {}).get("id") or "") != "B0WEAKPARK2" for segment in materialized_segments)
    assert not any(str(item.get("intentType") or "") == "night_view" for item in pending_slots)
    assert int(projection["routeExpectedLegCount"]) == int(projection["routeVerifiedLegCount"])
    assert int(projection["routeExpectedLegCount"]) == len(projection.get("routeEvidence") or [])
    assert projection.get("routePreconditionFailureReason") is None
    assert projection["adoptionReady"] is True
    has_more_choices = [
        item for item in response.assistant_turn.choice_options if item.get("kind") == "portfolio_more_plans"
    ]
    assert has_more_choices
    assert all(
        str(((item.get("continuationCheckpoint") or {}).get("frontierCursor") or {}).get("nextBriefId") or "")
        or (item.get("continuationCheckpoint") or {}).get("acceptedDirectionSignatures")
        for item in has_more_choices
    )
    assert pre_adoption_counts == (0, 0, 0)
    assert adopted.version is not None
    assert post_adoption_counts[0] - pre_adoption_counts[0] == 1
    assert post_adoption_counts[1] - pre_adoption_counts[1] == 1
    assert duplicate_adoption.version is not None
    assert duplicate_adoption.version.id == adopted.version.id
    assert post_duplicate_counts == post_adoption_counts


