def test_singular_night_view_contract_does_not_expand_to_each_day():
    clear_database()
    slots = [
        DaySlot("d1_campus", 1, "2026-10-01", "09:00-11:00", "09:00", 120, "visit", "高校参观", True),
        DaySlot("d1_night", 1, "2026-10-01", "19:00-20:30", "19:00", 90, "visit", "夜景观景点", True),
        DaySlot("d2_campus", 2, "2026-10-02", "09:00-11:00", "09:00", 120, "visit", "高校参观", True),
        DaySlot("d2_rest", 2, "2026-10-02", "18:30-20:00", "18:30", 90, "rest", "休息自由活动", False),
    ]
    with open_db() as connection:
        service = AgentService(connection, provider=FakeProvider("{}"), poi_resolution_service=FakePoiResolver({}))
        completed = service._ensure_required_repeating_day_slots(
            slots,
            {
                "latestUserMessage": "北京高校两日游，晚上看北京夜景",
                "requestIntentContract": {
                    "requiredIntents": [
                        {
                            "goalId": "goal_night_view",
                            "intentType": "night_view",
                            "target": 1,
                            "preferredCount": 1,
                            "maxCount": 1,
                            "allowedDayNumbers": [1, 2],
                        }
                    ]
                },
            },
        )

    night_slots = [
        slot
        for slot in completed
        if slot.route_anchor
        and service._intent_type_for_slot(slot, {"latestUserMessage": "晚上看北京夜景"}) == "night_view"
    ]
    assert [(slot.day_number, slot.route_anchor, slot.raw_need) for slot in night_slots] == [
        (1, True, "夜景观景点"),
    ]
    assert any(slot.slot_id == "d2_rest" for slot in completed)


def test_every_night_contract_completes_one_night_view_per_allowed_day():
    clear_database()
    slots = [
        DaySlot("d1_campus", 1, "2026-10-01", "09:00-11:00", "09:00", 120, "visit", "高校参观", True),
        DaySlot("d1_night", 1, "2026-10-01", "19:00-20:30", "19:00", 90, "visit", "夜景观景点", True),
        DaySlot("d2_campus", 2, "2026-10-02", "09:00-11:00", "09:00", 120, "visit", "高校参观", True),
        DaySlot("d2_rest", 2, "2026-10-02", "18:30-20:00", "18:30", 90, "rest", "休息自由活动", False),
    ]
    context = {
        "latestUserMessage": "北京高校两日游，每晚看北京夜景，公交地铁优先",
        "requestIntentContract": {
            "requiredIntents": [
                {
                    "goalId": "goal_night_view",
                    "intentType": "night_view",
                    "target": 2,
                    "preferredCount": 2,
                    "maxCount": 2,
                    "distributionPolicy": "every_allowed_day",
                    "allowedDayNumbers": [1, 2],
                }
            ],
            "experienceSpecs": [
                {
                    "intentType": "night_view",
                    "frequency": "every_available_evening",
                    "allowedDayNumbers": [1, 2],
                    "experienceFamilies": [
                        "public_city_view",
                        "waterfront_evening",
                    ],
                    "accessPolicy": "public_outdoor_or_verified_controlled_access",
                    "distinctnessPolicy": "distinct_physical_identity_per_occurrence",
                    "timeWindow": {"start": "18:30", "end": "22:00"},
                    "detourTolerance": {
                        "maxGeneralizedCostDelta": 35,
                        "maxDetourRatio": 0.35,
                    },
                    "evidenceFreshness": {
                        "maxAgeHours": 24,
                        "requiredForControlledAccess": True,
                    },
                    "confidence": 0.9,
                    "unresolvedDimensions": [],
                }
            ],
        },
    }
    context["requestIntentContract"]["routeDecisionContract"] = AgentService._compile_route_decision_contract(
        request_text=context["latestUserMessage"],
        experience_specs=context["requestIntentContract"]["experienceSpecs"],
    )
    with open_db() as connection:
        service = AgentService(connection, provider=FakeProvider("{}"), poi_resolution_service=FakePoiResolver({}))
        completed = service._ensure_required_repeating_day_slots(slots, context)

    night_slots = [
        slot for slot in completed if slot.route_anchor and service._intent_type_for_slot(slot, context) == "night_view"
    ]
    assert [(slot.day_number, slot.route_anchor, slot.raw_need) for slot in night_slots] == [
        (1, True, "夜景观景点"),
        (2, True, "夜景观景点"),
    ]
    assert {slot.time_window for slot in night_slots} == {"18:30-22:00"}
    assert all(
        slot.grounding_policy["accessPolicy"] == "public_outdoor_or_verified_controlled_access" for slot in night_slots
    )
    assert all(
        slot.grounding_policy["distinctnessPolicy"] == "distinct_physical_identity_per_occurrence"
        for slot in night_slots
    )
    assert all(slot.evidence_policy["evidenceFreshness"]["maxAgeHours"] == 24 for slot in night_slots)
    assert all(
        slot.route_context["detourTolerance"] == {"maxGeneralizedCostDelta": 35, "maxDetourRatio": 0.35}
        for slot in night_slots
    )
    assert all(
        slot.route_context["requiresProviderInsertionDecision"] is True
        and len(slot.route_context["experienceSpecFingerprint"]) == 64
        and slot.route_context["routeDecisionContract"]["status"] == "ready"
        for slot in night_slots
    )
    assert not any(slot.slot_id == "d2_rest" for slot in completed)


