def test_initial_timeout_generic_fallback_retries_hint_provider_and_creates_version(monkeypatch):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    search_calls: list[str] = []
    hint_names = {
        "清华大学",
        "北京大学",
        "中国人民大学",
        "北京航空航天大学",
        "奥林匹克塔",
        "中信大厦",
    }

    def search_with_verified_hint_variant(self, city, keyword, category="all", limit=10):
        search_calls.append(str(keyword))
        if str(keyword) in hint_names:
            is_campus = str(keyword) in {"清华大学", "北京大学", "中国人民大学", "北京航空航天大学"}
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[
                    MapPoiResponse(
                        id=f"amap_verified_{abs(hash(str(keyword)))}",
                        name=f"{keyword}(高德验证)",
                        type="科教文化服务;学校;高等院校" if is_campus else "风景名胜;观景点",
                        city=city,
                        district="测试区",
                        address=f"{keyword} 地址",
                        longitude=116.30 + len(search_calls) * 0.001,
                        latitude=39.90 + len(search_calls) * 0.001,
                        category=category,
                        source=AMAP_PLACE_SOURCE,
                        sourceNote="高德 WebService POI 搜索",
                        confidence=0.95,
                        photos=[],
                    )
                ],
            )
        return fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)

    hint_payload = {
        "hints": [
            {
                "poolId": "campus_visit_pool",
                "candidateHints": ["清华大学", "北京大学", "中国人民大学", "北京航空航天大学"],
                "hintPolicy": "llm_common_knowledge_hint",
            },
            {
                "poolId": "night_view_pool",
                "candidateHints": ["奥林匹克塔", "中信大厦"],
                "hintPolicy": "llm_common_knowledge_hint",
            },
        ],
        "warnings": [],
    }
    monkeypatch.setattr(MapPoiService, "search", search_with_verified_hint_variant)
    provider = HintRetryInitialProvider(hint_payload)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        poi_names = [row[0] for row in connection.execute("SELECT name FROM pois").fetchall()]

    assert provider.calls == 1
    assert provider.hint_calls == 1
    assert provider.hint_contexts[0]["latestUserMessage"]
    assert "daySlots" not in provider.hint_contexts[0]
    assert provider.hint_intent_pools[0][0]["poolId"] == "campus_visit_pool"
    assert response.version is not None
    assert all(name in search_calls for name in hint_names)
    assert "清华大学" not in poi_names
    assert "北京大学" not in poi_names
    assert any(name.startswith("清华大学(") for name in poi_names)
    hint_event = next(event for event in response.planning_steps if event.type == "candidate_hints_provider")
    assert hint_event.status == "completed"
    assert hint_event.metadata["resultPreview"]["candidateHintsAdded"] == 6
    collect_events = [event for event in response.planning_steps if event.type == "collect_candidates"]
    assert len(collect_events) == 1
    collect_preview = collect_events[0].metadata["resultPreview"]
    assert collect_preview["poolReports"][0]["candidateHintCount"] == 4
    assert collect_preview["poolReports"][0]["selectionThreshold"] == 0.72
    assert search_calls[:4] == ["清华大学", "北京大学", "中国人民大学", "北京航空航天大学"]


