def test_creative_portfolio_timeout_is_not_reported_as_schema_invalid():
    class TimeoutPortfolioProvider:
        def generate_initial_portfolio(self, _context, *, repair_feedback=""):
            raise TimeoutError("portfolio provider timed out")

    service = AgentService.__new__(AgentService)
    service.provider = TimeoutPortfolioProvider()
    service._pipeline_event_perf = None
    events: list[dict] = []

    with pytest.raises(ValueError, match="CREATIVE_PORTFOLIO_PROVIDER_TIMEOUT"):
        service._generate_initial_creative_portfolio(
            {"selectedCity": "北京", "requestIntentContract": {"requiredIntents": []}},
            events,
        )

    assert events[-1]["status"] == "failed"
    assert "超时" in events[-1]["detail"]


@pytest.mark.parametrize(
    "request_content",
    [
        route_ready_request(
            "今年国庆参观北京高校两日游，每晚都看北京夜景。"
            "10月1日到2日，2天，中等预算，1人，公交地铁优先。"
            "每天午餐想体验当地特色美食。"
        ),
        route_ready_request(
            "今年国庆参观北京高校两日游，晚上看北京城市夜景。"
            "10月1日到2日，中等预算，1人，公交地铁优先。"
            "每天午餐想体验当地特色美食。\n"
            "每个可用晚上安排不同的夜景地点"
        ),
    ],
    ids=["explicit-every-night", "persisted-every-available-evening-choice"],
)
def test_deepseek_controller_unavailable_uses_server_cardinality_draft_and_enters_staged_pipeline(
    monkeypatch,
    request_content,
):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    full_calls = 0
    lite_calls = 0
    initial_calls = 0

    def timeout_full(_context: dict, **_kwargs):
        nonlocal full_calls
        full_calls += 1
        raise TimeoutError("controller_decision_timeout")

    def timeout_lite(_context: dict, **_kwargs):
        nonlocal lite_calls
        lite_calls += 1
        if _context.get("schemaVersion") == "conversation-intent-context-v1":
            return _intent_contract_for_test_context(_context)
        raise TimeoutError("controller_lite_timeout")

    def recorded_initial_provider(_context: dict) -> str:
        nonlocal initial_calls
        initial_calls += 1
        return json.dumps(two_day_initial_day_slot_output(), ensure_ascii=False)

    def fail_hint_provider(_context: dict, _intent_pools: list[dict]) -> str:
        raise AssertionError("deterministic quick path should use static candidate hints")

    provider.decide_autonomy = timeout_full  # type: ignore[method-assign]
    provider.decide_autonomy_lite = timeout_lite  # type: ignore[method-assign]
    provider.generate_initial_plan = recorded_initial_provider  # type: ignore[method-assign]
    provider.generate_candidate_hints = fail_hint_provider  # type: ignore[method-assign]

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(content=request_content),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

    assert full_calls == 1
    # One read-only conversation-intent classification plus the existing
    # business-controller Lite fallback.
    assert lite_calls == 2
    assert initial_calls == 1
    assert response.version is None
    assert response.itinerary is None
    assert response.terminal_status == "candidate_refresh_required"
    assert active_version_id is None
    assert "模型规划暂不可用" not in response.assistant_turn.content
    decision_event = next(event for event in response.planning_steps if event.type == "agent_decision")
    assert decision_event.metadata["primaryAction"] == "draft_itinerary"
    assert decision_event.metadata["decisionPath"] == "fallback"
    assert decision_event.metadata["source"] == "safe_fallback"
    assert decision_event.metadata["controllerFullSucceeded"] is False
    assert decision_event.metadata["controllerLiteSucceeded"] is False
    assert decision_event.metadata["actualExecutionRoute"] == "staged_initial_pipeline"
    assert "server_directive_after_controller_timeout" in decision_event.metadata["reasonCodes"]


def test_deepseek_controller_repair_failure_stops_without_lite_or_server_draft(monkeypatch):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    full_calls = 0
    lite_calls = 0
    initial_calls = 0

    def invalid_full(_context: dict, **kwargs):
        nonlocal full_calls
        full_calls += 1
        if kwargs.get("repair_feedback"):
            raise json.JSONDecodeError("unterminated controller response", "{", 1)
        return {
            "schemaVersion": "agent-decision-v3",
            "primaryAction": "draft_itinerary",
            "confidence": 0.9,
            "decisionSummary": "missing required day strategies",
            "actionDirective": {"type": "draft_itinerary", "requestIntentContract": {}},
            "stopCondition": {"type": "verified_draft"},
        }

    def invalid_lite(_context: dict, **_kwargs):
        nonlocal lite_calls
        lite_calls += 1
        if _context.get("schemaVersion") == "conversation-intent-context-v1":
            return _intent_contract_for_test_context(_context)
        raise json.JSONDecodeError("unterminated lite response", "{", 1)

    def recorded_initial_provider(_context: dict) -> str:
        nonlocal initial_calls
        initial_calls += 1
        return json.dumps(two_day_initial_day_slot_output(), ensure_ascii=False)

    provider.decide_autonomy = invalid_full  # type: ignore[method-assign]
    provider.decide_autonomy_lite = invalid_lite  # type: ignore[method-assign]
    provider.generate_initial_plan = recorded_initial_provider  # type: ignore[method-assign]
    provider.generate_candidate_hints = lambda *_args, **_kwargs: (_ for _ in ()).throw(  # type: ignore[method-assign]
        AssertionError("deterministic quick path should use static candidate hints")
    )

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京首轮会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
                )
            ),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

    assert full_calls == 2
    # Only the read-only conversation-intent classification remains.  A failed
    # unique repair is terminal and cannot start Lite or the staged draft.
    assert lite_calls == 1
    assert initial_calls == 0
    assert response.version is None
    assert response.itinerary is None
    assert response.terminal_status == "needs_confirmation"
    assert active_version_id is None
    assert "当前没有修改行程" in response.assistant_turn.content
    decision_event = next(event for event in response.planning_steps if event.type == "agent_decision")
    assert decision_event.metadata["primaryAction"] == "ask_user"
    assert decision_event.metadata["decisionPath"] == "fallback"
    assert decision_event.metadata["source"] == "safe_fallback"
    assert decision_event.metadata["actualExecutionRoute"] == "clarification"
    assert "server_directive_after_controller_invalid_response" not in decision_event.metadata["reasonCodes"]


def test_controller_full_timeout_then_lite_draft_enters_verified_staged_pipeline(monkeypatch):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    full_calls: list[dict] = []
    lite_calls: list[dict] = []

    def full(context: dict, **_kwargs):
        full_calls.append(context)
        raise TimeoutError("controller_decision_timeout")

    def lite(context: dict, **_kwargs):
        lite_calls.append(context)
        if context.get("schemaVersion") == "conversation-intent-context-v1":
            return _intent_contract_for_test_context(context)
        return {
            "schemaVersion": "agent-decision-lite-v1",
            "primaryAction": "draft_itinerary",
            "confidence": 0.94,
            "reasonCode": "complete_initial_trip_request",
            "userVisibleReason": "信息已足够，可起草行程。",
        }

    provider.decide_autonomy = full  # type: ignore[method-assign]
    provider.decide_autonomy_lite = lite  # type: ignore[method-assign]
    provider.generate_initial_plan = lambda _context: json.dumps(  # type: ignore[method-assign]
        two_day_initial_day_slot_output(), ensure_ascii=False
    )

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "lite draft")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content="今年国庆参观北京高校两日游，每晚都看北京夜景，想体验当地特色美食。10月1日到2日，2天，中等预算，1人，公交地铁优先"
            ),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()["active_version_id"]

    decision = next(event for event in response.planning_steps if event.type == "agent_decision")
    assert len(full_calls) == 1
    assert len(lite_calls) == 2
    assert response.version is None
    assert response.itinerary is None
    assert response.terminal_status == "candidate_refresh_required"
    assert active_version_id is None
    assert decision.metadata["decisionPath"] == "lite"
    assert decision.metadata["controllerFullCalled"] is True
    assert decision.metadata["controllerFullSucceeded"] is False
    assert decision.metadata["controllerLiteCalled"] is True
    assert decision.metadata["controllerLiteSucceeded"] is True
    assert decision.metadata["actualExecutionRoute"] == "staged_initial_pipeline"
    assert any(event.type == "controller_full_failed" for event in response.planning_steps)
    assert any(
        event.type == "controller_lite_completed" and event.status == "completed" for event in response.planning_steps
    )


def test_controller_timeout_retry_is_zero_write_with_required_goal_gap(
    monkeypatch,
):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: True)
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    monkeypatch.setattr(MapPoiService, "search_nearby", fake_amap_search_nearby_route_compatible)
    provider = _install_intent_contract(DeepSeekAgentProvider(api_key="", model="deepseek-test", timeout_seconds=7))
    initial_provider_calls = 0

    def safe_draft_amap(_self, city, keyword, category="all", limit=10):
        keyword_text = str(keyword)
        if category == "food" or re.search(r"(午餐|美食|餐厅|小吃|炸酱面)", keyword_text):
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword_text,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[],
            )
        if re.search(r"(夜景|观景|夜游|灯光|奥林匹克塔|中信大厦)", keyword_text):
            pois = (
                [night_view_map_poi("B0OLYMTOWER", "奥林匹克塔", 116.3946, 40.0086)]
                if "奥林匹克塔" in keyword_text
                else []
            )
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword_text,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=pois,
            )
        if category == "campus" or re.search(r"(高校|大学|学院|校园|校区|高等院校)", keyword_text):
            return fake_amap_search_with_keyword_candidate(_self, city, keyword, category, limit)
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword_text,
            category=category,
            providerName="fake-amap",
            queriedAt=datetime.now(timezone.utc),
            pois=[],
        )

    def no_nearby_meals(*_args, **_kwargs):
        return MapPoiSearchResponse(
            city="北京",
            keyword="餐饮",
            category="food",
            providerName="fake-amap",
            queriedAt=datetime.now(timezone.utc),
            pois=[],
        )

    def fail_initial_provider(_context: dict) -> str:
        nonlocal initial_provider_calls
        initial_provider_calls += 1
        raise AssertionError("confirmed rule-safe draft must not call the model planner")

    provider.generate_initial_plan = fail_initial_provider  # type: ignore[method-assign]
    monkeypatch.setattr(MapPoiService, "search", safe_draft_amap)
    monkeypatch.setattr(MapPoiService, "search_nearby", no_nearby_meals)

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "fallback confirmation")
        service = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({}))
        creative_portfolio_calls = 0
        original_generate_creative_portfolio = service._generate_initial_creative_portfolio

        def track_generate_creative_portfolio(*args, **kwargs):
            nonlocal creative_portfolio_calls
            creative_portfolio_calls += 1
            return original_generate_creative_portfolio(*args, **kwargs)

        service._generate_initial_creative_portfolio = track_generate_creative_portfolio  # type: ignore[method-assign]
        monkeypatch.setattr(service.itinerary_diversity_policy, "variant_seed", lambda *_parts: 0)
        first = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先。每天午餐想体验当地特色美食。"
            ),
        )
        options = first.assistant_turn.choice_options
        retry_option = next(option for option in options if option["action"] == "retry_model_planning")

        assert retry_option["id"].startswith("controller-retry:")
        assert retry_option["kind"] == "safe_fallback_action"
        assert retry_option["sourceUserTurnId"] == first.user_turn.id
        assert first.version is None
        assert first.itinerary is None
        memory_before = tuple(
            connection.execute(
                "SELECT memory_text, structured_facts_json, compiled_rules_json, updated_at FROM session_preference_memories WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()
        )

        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="选择 Agent 选项",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": retry_option["id"],
                    }
                },
            ),
        )
        execution = connection.execute(
            "SELECT status, action, result_version_id, attempt FROM agent_choice_executions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()
        version_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()[0]
        memory_after = tuple(
            connection.execute(
                "SELECT memory_text, structured_facts_json, compiled_rules_json, updated_at FROM session_preference_memories WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()["active_version_id"]
        # Controller failure cannot bypass a root-level required-goal gap. The
        # retry stays recoverable and remains a truthful zero-write outcome.
        assert initial_provider_calls == 0
        assert second.version is None
        assert second.itinerary is None
        assert second.terminal_status == "needs_confirmation"
        assert active_version_id is None
        assert version_count == 0
        assert execution["action"] == "retry_model_planning"
        assert execution["result_version_id"] is None
        assert memory_after == memory_before
        return
        assert initial_provider_calls == 0
        committed_snapshot = json.loads(
            connection.execute(
                "SELECT snapshot_json FROM itinerary_versions WHERE id = ? AND session_id = ?",
                (active_version_id, session.session_id),
            ).fetchone()["snapshot_json"]
        )
        saved_request_context = json.loads(
            connection.execute(
                "SELECT agent_request_json FROM conversation_turns WHERE id = ? AND session_id = ?",
                (second.user_turn.id, session.session_id),
            ).fetchone()["agent_request_json"]
        )
        deterministic_plan = service._server_generic_day_slots_fallback(
            saved_request_context,
            [],
            fallback_reason="test_evidence",
        )
        creative_portfolio_calls_before_expansion = creative_portfolio_calls
        more_plans_option = next(
            option for option in second.assistant_turn.choice_options if option.get("action") == "retry_model_planning"
        )
        comparison_root = next(
            option["comparisonProjection"]["planningSelectionRootTurnId"]
            for option in second.assistant_turn.choice_options
            if isinstance(option.get("comparisonProjection"), dict)
        )
        checkpoint_source_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (second.assistant_turn.id,),
            ).fetchone()[0]
        )
        expansion_resume_evidence = service._partial_plan_expansion_resume_plan(
            session_id=session.session_id,
            source_assistant_turn_id=second.assistant_turn.id,
            root_portfolio_id=str(more_plans_option.get("rootPortfolioId") or ""),
            planning_root_id=str(more_plans_option.get("planningSelectionRootTurnId") or ""),
            request_fingerprint=str(more_plans_option.get("requestContractFingerprint") or ""),
            focus_brief_id=str(more_plans_option.get("focusBriefId") or ""),
        )
        source_has_portfolio_checkpoint = all(
            isinstance(checkpoint_source_payload.get(key), dict)
            for key in ("constraintLedger", "creativePortfolio", "groundingCheckpoint")
        )
        assert (expansion_resume_evidence is not None) is source_has_portfolio_checkpoint
        recovered_controller_contexts: list[dict] = []
        original_controller_decide = service.autonomy_controller.decide

        def capture_recovered_controller(_latest_message, context, *_args, **kwargs):
            recovered_controller_contexts.append(copy.deepcopy(context))
            return original_controller_decide(_latest_message, context, *_args, **kwargs)

        service.autonomy_controller.decide = capture_recovered_controller  # type: ignore[method-assign]
        third = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="选择 Agent 选项",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": second.assistant_turn.id,
                        "choiceId": more_plans_option["id"],
                    }
                },
            ),
        )
        version_count_after_retry = connection.execute(
            "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()[0]
        expansion_execution = connection.execute(
            """SELECT status, continuation_json, outcome_json
            FROM agent_choice_executions
            WHERE session_id = ? AND action = 'retry_model_planning'
            ORDER BY created_at DESC LIMIT 1""",
            (session.session_id,),
        ).fetchone()
        expansion_continuation = json.loads(expansion_execution["continuation_json"])
        expansion_outcome = json.loads(expansion_execution["outcome_json"])
        expansion_source = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (second.assistant_turn.id,),
            ).fetchone()[0]
        )

    assert initial_provider_calls == 0
    if source_has_portfolio_checkpoint:
        assert creative_portfolio_calls == creative_portfolio_calls_before_expansion
    assert second.version is not None, {
        "assistantStatus": second.assistant_turn.status,
        "assistantContent": second.assistant_turn.content,
        "activeVersionId": active_version_id,
        "choiceExecution": dict(execution),
        "planningSteps": [
            {
                "type": event.type,
                "status": event.status,
                "failureReason": event.failure_reason,
                "resultPreview": event.metadata.get("resultPreview"),
            }
            for event in second.planning_steps
        ],
    }
    assert execution["status"] == "succeeded"
    assert second.user_turn.structured_choice_trace["executionStatus"] == "succeeded"
    assert execution["action"] == "confirm_rule_safe_draft"
    assert execution["result_version_id"] == second.version.id
    assert execution["attempt"] == 1
    assert version_count == 1
    assert version_count_after_retry == 1
    assert expansion_execution["status"] == "failed_terminal"
    assert expansion_continuation["kind"] == "expand_partial_portfolio"
    assert expansion_continuation["activeVersionId"] == second.version.id
    assert expansion_continuation["proposalIdsBefore"] == []
    assert expansion_continuation["visibleProposalCountBefore"] == 0
    assert expansion_outcome["reason"] == "no_verified_proposal_delta"
    assert expansion_outcome["proposalDelta"] == len(expansion_outcome["newProposalIds"])
    # Only material that survives the read-only identity/novelty gates may be
    # persisted. The rejected sibling must not inflate the proposal delta.
    assert expansion_outcome["proposalDelta"] == 1
    assert expansion_outcome["qualifiedProposalIds"] == []
    assert expansion_outcome["versionDelta"] == 0
    assert expansion_outcome["patchDelta"] == 0
    assert expansion_outcome["routeWriteDelta"] == 0
    assert expansion_outcome["boundedAttemptConsumed"] is True
    assert expansion_outcome["cursorAdvanced"] is True or expansion_outcome["cursorExhausted"] is True
    assert more_plans_option["id"] in expansion_source.get("consumedChoiceIds", [])
    assert third.version is not None
    assert third.version.id == second.version.id
    assert third.user_turn.structured_choice_trace["executionStatus"] == "failed_terminal"
    assert third.user_turn.structured_choice_trace["planningSelectionRootTurnId"] == comparison_root
    assert third.user_turn.structured_choice_trace["rootPortfolioId"] == expansion_outcome["rootPortfolioId"]
    assert (
        third.user_turn.structured_choice_trace["requestContractFingerprint"]
        == expansion_outcome["requestContractFingerprint"]
    )
    assert third.user_turn.structured_choice_trace["executionRoute"] == "controller_choice_resume"
    assert third.user_turn.structured_choice_trace["versionDelta"] == 0
    assert third.user_turn.structured_choice_trace["patchDelta"] == 0
    assert third.user_turn.structured_choice_trace["routeWriteDelta"] == 0
    assert "当前方案" in third.assistant_turn.content
    assert "未发生变化" in third.assistant_turn.content
    if expansion_outcome["cursorAdvanced"]:
        next_option = next(
            option for option in third.assistant_turn.choice_options if option.get("action") == "retry_model_planning"
        )
        if expansion_outcome.get("continuationFocusMode") == "discover_next":
            assert expansion_outcome["nextBriefId"] is None
            assert next_option["expansionFocusMode"] == "discover_next"
            assert next_option["focusBriefId"] == expansion_outcome["activePartialFocusBriefId"]
            assert next_option["focusBriefId"] != expansion_outcome["resolvedFocusBriefId"]
        else:
            assert next_option["focusBriefId"] == expansion_outcome["nextBriefId"]
            assert next_option["focusBriefId"] != expansion_outcome["resolvedFocusBriefId"]
    else:
        assert expansion_outcome["nextBriefId"] is None
    decision = next(event for event in third.planning_steps if event.type == "agent_decision")
    assert decision.metadata["controllerFullCalled"] is False
    assert decision.metadata["controllerLiteCalled"] is False
    assert recovered_controller_contexts == []
    assert any(event.type == "fallback_confirmation_selected" for event in second.planning_steps)
    assert memory_after == memory_before
    assert committed_snapshot["status"] == "partial"
    assert committed_snapshot["portfolioPartialTimeline"]["status"] == "partial"
    assert deterministic_plan is not None
    assert [slot.day_number for slot in deterministic_plan.day_slots if slot.kind == "meal"] == [1, 2]
    meal_slots = [
        item for item in committed_snapshot["portfolioPendingSlots"] if item.get("sourceGoalId") == "goal_meal"
    ]
    meal_segments = [
        {
            "dayNumber": day.get("dayNumber"),
            "id": segment.get("id"),
            "poi": segment.get("poi"),
            "semanticMetadata": segment.get("semanticMetadata"),
        }
        for day in committed_snapshot.get("days") or []
        for segment in day.get("segments") or []
        if isinstance(segment, dict)
        and (segment.get("kind") == "meal" or (segment.get("semanticMetadata") or {}).get("intentType") == "meal")
    ]
    assert [item["dayNumber"] for item in meal_slots] == [1, 2], json.dumps(
        {"pending": committed_snapshot["portfolioPendingSlots"], "segments": meal_segments},
        ensure_ascii=False,
        indent=2,
    )
    assert all(item.get(key) for item in meal_slots for key in ("briefId", "poolId", "planningSlotId", "timeWindow"))
    projections = [
        option["comparisonProjection"]
        for option in second.assistant_turn.choice_options
        if isinstance(option.get("comparisonProjection"), dict)
    ]
    assert len(projections) == 1
    projection = projections[0]
    assert projection["isPartial"] is True
    assert projection["activeVersionId"] == second.version.id
    assert projection["expectedBaseVersionId"] == second.version.id
    assert len(projection["pendingSlots"]) == 3
    projected_night_days = {
        int(day["dayNumber"])
        for day in projection["days"]
        for segment in day["segments"]
        if segment.get("intentType") == "night_view"
    } | {int(slot["dayNumber"]) for slot in projection["pendingSlots"] if slot.get("intentType") == "night_view"}
    assert projected_night_days == {1, 2}


def test_controller_retry_timeout_consumes_old_choice_and_offers_fresh_retry_without_rule_draft(monkeypatch):
    clear_database()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = _install_intent_contract(DeepSeekAgentProvider(api_key="", model="deepseek-test", timeout_seconds=7))

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "retry timeout")
        service = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({}))
        first = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="今年国庆参观北京高校两日游，每晚都看北京夜景，想体验当地特色美食。10月1日到2日，2天，中等预算，1人，公交地铁优先"
            ),
        )
        old_option = next(
            option for option in first.assistant_turn.choice_options if option["action"] == "retry_model_planning"
        )

        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="选择 Agent 选项",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": old_option["id"],
                    }
                },
            ),
        )
        new_option = next(
            option for option in second.assistant_turn.choice_options if option["action"] == "retry_model_planning"
        )
        first_request = json.loads(
            connection.execute(
                "SELECT agent_request_json FROM conversation_turns WHERE id = ?",
                (first.assistant_turn.id,),
            ).fetchone()[0]
        )
        source_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?", (first.assistant_turn.id,)
            ).fetchone()[0]
        )
        execution = connection.execute(
            "SELECT status, action, result_version_id, attempt FROM agent_choice_executions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()
        version_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()[0]

    assert second.version is None
    assert new_option["id"] != old_option["id"]
    assert new_option["kind"] == "safe_fallback_action"
    assert new_option["label"] == "重试生成行程"
    assert new_option["attempt"] == 2
    assert new_option["sourceUserTurnId"] == first.user_turn.id
    assert new_option["planningSelectionRootTurnId"] == first.user_turn.id
    assert new_option["requestContractFingerprint"] == ClarificationCheckpointService._fingerprint(
        first_request["requestIntentContract"]
    )
    assert "规划控制器" in second.assistant_turn.content
    assert "澄清问题未通过当前需求合同校验" not in second.assistant_turn.content
    assert old_option["id"] not in source_payload.get("consumedChoiceIds", [])
    assert execution["status"] == "failed_retryable"
    assert second.user_turn.structured_choice_trace["executionStatus"] == "failed_retryable"
    assert execution["action"] == "retry_model_planning"
    assert execution["result_version_id"] is None
    assert execution["attempt"] == 1
    assert version_count == 0
    assert not any(event.metadata.get("deterministicInitialPlanUsed") is True for event in second.planning_steps)


def test_partial_plan_expansion_success_requires_new_visible_verified_projected_proposal():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "proposal truth")
        service = AgentService(connection, provider=SimpleNamespace())
        now = datetime.now(timezone.utc).isoformat()
        connection.execute(
            """INSERT INTO agent_plan_portfolios (
                id, session_id, source_user_turn_id, source_assistant_turn_id,
                expected_base_version_id, source_observation_fingerprint,
                request_contract_fingerprint, status, selected_proposal_id,
                dominant_proposal_id, summary_json, failure_reason, expires_at,
                created_at, updated_at
            ) VALUES (?, ?, ?, NULL, NULL, ?, ?, 'failed', NULL, NULL, ?, NULL, NULL, ?, ?)""",
            (
                "portfolio_root",
                session.session_id,
                "turn_root",
                "obs_fp",
                "request_fp",
                json.dumps({"proposalIds": [], "visibleProposalIds": []}),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO itinerary_versions "
            "(id, session_id, plan_id, version_number, source_type, source_turn_id, "
            "source_patch_id, snapshot_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                "ver_existing",
                session.session_id,
                session.active_plan_id,
                1,
                "agent",
                "turn_root",
                None,
                "{}",
                now,
            ),
        )
        connection.execute(
            "UPDATE conversation_sessions SET active_version_id = ? WHERE id = ?",
            ("ver_existing", session.session_id),
        )
        claim = service._partial_plan_expansion_claim_state(
            session_id=session.session_id,
            plan_id=session.active_plan_id,
            root_portfolio_id="portfolio_root",
            planning_root_id="turn_root",
            request_fingerprint="request_fp",
            active_version_id="ver_existing",
        )
        claim.update(
            {
                "focusBriefId": "brief_new",
                "expansionFocusMode": "exact",
            }
        )
        connection.execute(
            """INSERT INTO agent_plan_proposals (
                id, portfolio_id, choice_id, rank_index, status, brief_json,
                snapshot_json, score_json, verifier_json, evidence_json,
                canonical_signature, generation_lineage_json, created_at, updated_at
            ) VALUES (?, ?, ?, 0, 'offered', ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                "proposal_new",
                "portfolio_root",
                "portfolio_choice_proposal_new",
                json.dumps({"briefId": "brief_new", "title": "高校夜景"}),
                json.dumps({"days": []}),
                json.dumps({"hardConstraintPassed": True}),
                json.dumps({"passed": True}),
                json.dumps({"grounded": []}),
                "signature_new",
                json.dumps({"planningSelectionRootTurnId": "turn_root"}),
                now,
                now,
            ),
        )
        connection.execute(
            """UPDATE agent_plan_portfolios
            SET status = 'awaiting_selection', summary_json = ? WHERE id = ?""",
            (
                json.dumps(
                    {
                        "proposalIds": ["proposal_new"],
                        "visibleProposalIds": ["proposal_new"],
                    }
                ),
                "portfolio_root",
            ),
        )
        connection.commit()
        request_context = {
            "partialPlanExpansionClaim": claim,
            "_partialPlanExpansionAuthorized": True,
        }
        response = SimpleNamespace(
            version=SimpleNamespace(id="ver_existing"),
            assistant_turn=SimpleNamespace(
                choice_options=[
                    {
                        "comparisonProjection": {
                            "proposalId": "proposal_new",
                            "rootPortfolioId": "portfolio_root",
                            "planningSelectionRootTurnId": "turn_root",
                            "isPartial": False,
                        }
                    }
                ]
            ),
        )

        outcome = service._partial_plan_expansion_outcome(
            session_id=session.session_id,
            request_context=request_context,
            response=response,
        )
        mismatched_version_outcome = service._partial_plan_expansion_outcome(
            session_id=session.session_id,
            request_context=request_context,
            response=SimpleNamespace(
                version=SimpleNamespace(id="ver_other"),
                assistant_turn=response.assistant_turn,
            ),
        )
        completion_context = {
            **request_context,
            "selectedAgentChoice": {
                "action": "retry_model_planning",
                "sourceAssistantTurnId": "turn_source_expansion",
                "choiceId": "choice_positive_expansion",
            },
            "fallbackChoiceExecutionClaim": {"id": "choice_exec_positive_expansion"},
        }
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_response_json, created_at, updated_at) "
            "VALUES (?, ?, 'assistant', '可继续生成其他方案', 1, 'active', ?, ?, ?)",
            (
                "turn_source_expansion",
                session.session_id,
                json.dumps(
                    {
                        "choiceOptions": [
                            {
                                "id": "choice_positive_expansion",
                                "action": "retry_model_planning",
                            }
                        ]
                    }
                ),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_request_json, created_at, updated_at) "
            "VALUES (?, ?, 'user', '继续生成其他方案', 2, 'active', ?, ?, ?)",
            (
                "turn_positive_expansion",
                session.session_id,
                json.dumps(completion_context),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO agent_choice_executions "
            "(id, session_id, source_turn_id, source_user_turn_id, choice_id, action, status, "
            "created_at, updated_at) VALUES (?, ?, ?, ?, ?, 'retry_model_planning', 'executing', ?, ?)",
            (
                "choice_exec_positive_expansion",
                session.session_id,
                "turn_source_expansion",
                "turn_root",
                "choice_positive_expansion",
                now,
                now,
            ),
        )
        connection.commit()
        completion_response = SimpleNamespace(
            version=SimpleNamespace(id="ver_existing"),
            assistant_turn=SimpleNamespace(
                id="turn_positive_expansion_result",
                status="active",
                failure_reason=None,
                choice_options=response.assistant_turn.choice_options,
            ),
        )
        service._complete_controller_choice_execution(
            session.session_id,
            "turn_positive_expansion",
            completion_response,
        )
        completed_execution = connection.execute(
            "SELECT status, outcome_json FROM agent_choice_executions WHERE id = ?",
            ("choice_exec_positive_expansion",),
        ).fetchone()
        source_choice_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                ("turn_source_expansion",),
            ).fetchone()[0]
        )
        connection.execute(
            "UPDATE agent_plan_proposals SET verifier_json = ? WHERE id = ?",
            (json.dumps({"passed": False}), "proposal_new"),
        )
        connection.commit()
        unverified = service._partial_plan_expansion_outcome(
            session_id=session.session_id,
            request_context=request_context,
            response=response,
        )

    assert outcome["succeeded"] is True
    assert outcome["newProposalIds"] == ["proposal_new"]
    assert outcome["qualifiedProposalIds"] == ["proposal_new"]
    assert outcome["proposalDelta"] == 1
    assert outcome["versionDelta"] == 0
    assert outcome["patchDelta"] == 0
    assert outcome["routeWriteDelta"] == 0
    assert outcome["zeroWrite"] is True
    assert outcome["responseVersionId"] == "ver_existing"
    assert outcome["responseVersionUnchanged"] is True
    assert mismatched_version_outcome["succeeded"] is False
    assert mismatched_version_outcome["responseVersionId"] == "ver_other"
    assert mismatched_version_outcome["responseVersionUnchanged"] is False
    assert completed_execution["status"] == "succeeded"
    assert source_choice_payload["consumedChoiceIds"] == ["choice_positive_expansion"]
    assert json.loads(completed_execution["outcome_json"])["reason"] == "new_verified_proposal"
    assert json.loads(completed_execution["outcome_json"])["proposalDelta"] == 1
    assert unverified["succeeded"] is False
    assert unverified["qualifiedProposalIds"] == []


def test_two_complete_proposals_are_appended_one_at_a_time_without_formal_writes():
    """Each opaque expansion adds its own verified proposal and preserves prior rows."""

    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "append-only fixture")
        service = AgentService(connection, provider=SimpleNamespace())
        now = datetime.now(timezone.utc).isoformat()
        connection.execute(
            """INSERT INTO agent_plan_portfolios (
                id, session_id, source_user_turn_id, source_assistant_turn_id,
                expected_base_version_id, source_observation_fingerprint,
                request_contract_fingerprint, status, selected_proposal_id,
                dominant_proposal_id, summary_json, failure_reason, expires_at,
                created_at, updated_at
            ) VALUES (?, ?, ?, NULL, NULL, ?, ?, 'awaiting_selection', NULL, NULL, ?, NULL, NULL, ?, ?)""",
            (
                "portfolio_append",
                session.session_id,
                "turn_root",
                "obs_fp",
                "request_fp",
                json.dumps({"proposalIds": [], "visibleProposalIds": []}),
                now,
                now,
            ),
        )
        connection.execute(
            """INSERT INTO itinerary_versions
            (id, session_id, plan_id, version_number, source_type, source_turn_id,
             source_patch_id, snapshot_json, created_at)
            VALUES (?, ?, ?, 1, 'agent', 'turn_root', NULL, '{}', ?)""",
            ("ver_existing", session.session_id, session.active_plan_id, now),
        )
        connection.execute(
            "UPDATE conversation_sessions SET active_version_id = ? WHERE id = ?",
            ("ver_existing", session.session_id),
        )

        def insert_proposal(proposal_id: str, brief_id: str, title: str, amap_id: str, rank: int) -> None:
            snapshot = {
                "city": "北京",
                "title": title,
                "days": [
                    {
                        "dayNumber": 1,
                        "segments": [
                            {
                                "id": f"seg_{proposal_id}",
                                "poi": {
                                    "amapId": amap_id,
                                    "name": title.split("｜", 1)[-1],
                                    "source": "amap-place-search",
                                    "latitude": 39.9 + rank / 100,
                                    "longitude": 116.4 + rank / 100,
                                },
                            }
                        ],
                    }
                ],
                "portfolioPendingSlots": [],
            }
            connection.execute(
                """INSERT INTO agent_plan_proposals (
                    id, portfolio_id, choice_id, rank_index, status, brief_json,
                    snapshot_json, score_json, verifier_json, evidence_json,
                    canonical_signature, generation_lineage_json, created_at, updated_at
                ) VALUES (?, 'portfolio_append', ?, ?, 'offered', ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    proposal_id,
                    f"portfolio_choice_{proposal_id}",
                    rank,
                    json.dumps({"briefId": brief_id, "title": title}),
                    json.dumps(snapshot),
                    json.dumps({"hardConstraintPassed": True}),
                    json.dumps({"passed": True}),
                    json.dumps({"groundedAmapIds": [amap_id]}),
                    f"signature_{proposal_id}",
                    json.dumps({"planningSelectionRootTurnId": "turn_root"}),
                    now,
                    now,
                ),
            )

        def expansion_outcome(proposal_id: str, brief_id: str, before: list[str]) -> dict:
            summary = {
                "proposalIds": [*before, proposal_id],
                "visibleProposalIds": [*before, proposal_id],
                "briefGenerationState": [{"briefId": brief_id, "status": "completed"}],
            }
            connection.execute(
                "UPDATE agent_plan_portfolios SET summary_json = ? WHERE id = 'portfolio_append'",
                (json.dumps(summary),),
            )
            connection.commit()
            claim = service._partial_plan_expansion_claim_state(
                session_id=session.session_id,
                plan_id=session.active_plan_id,
                root_portfolio_id="portfolio_append",
                planning_root_id="turn_root",
                request_fingerprint="request_fp",
                active_version_id="ver_existing",
            )
            claim.update(
                {
                    "proposalIdsBefore": before,
                    "visibleProposalIdsBefore": before,
                    "focusBriefId": brief_id,
                    "resolvedFocusBriefId": brief_id,
                    "expansionFocusMode": "exact",
                }
            )
            response = SimpleNamespace(
                version=SimpleNamespace(id="ver_existing"),
                assistant_turn=SimpleNamespace(
                    id=f"turn_{proposal_id}",
                    choice_options=[
                        {
                            "comparisonProjection": {
                                "proposalId": proposal_id,
                                "rootPortfolioId": "portfolio_append",
                                "planningSelectionRootTurnId": "turn_root",
                                "isPartial": False,
                            }
                        }
                    ],
                ),
            )
            return service._partial_plan_expansion_outcome(
                session_id=session.session_id,
                request_context={"partialPlanExpansionClaim": claim},
                response=response,
            )

        insert_proposal("proposal_one", "brief_one", "北京｜清华大学、奥林匹克塔", "B00000011", 0)
        first = expansion_outcome("proposal_one", "brief_one", [])
        insert_proposal("proposal_two", "brief_two", "北京｜国家博物馆、亮马河", "B00000012", 1)
        second = expansion_outcome("proposal_two", "brief_two", ["proposal_one"])
        rows = connection.execute(
            "SELECT id, brief_json, snapshot_json FROM agent_plan_proposals WHERE portfolio_id = 'portfolio_append' ORDER BY rank_index"
        ).fetchall()

    assert first["succeeded"] is True
    assert first["newProposalIds"] == ["proposal_one"]
    assert second["succeeded"] is True
    assert second["newProposalIds"] == ["proposal_two"]
    assert second["versionDelta"] == second["patchDelta"] == second["routeWriteDelta"] == 0
    assert [row["id"] for row in rows] == ["proposal_one", "proposal_two"]
    assert {json.loads(row["brief_json"])["briefId"] for row in rows} == {"brief_one", "brief_two"}
    assert len({json.loads(row["snapshot_json"])["title"] for row in rows}) == 2


