def _partial_projection_with_physical_ids(proposal_id: str, poi_ids: list[str]) -> dict:
    projection = _grounded_read_only_partial_projection(proposalId=proposal_id)
    projection["days"] = [
        {
            "dayNumber": 1,
            "segments": [
                {
                    "id": f"{proposal_id}_{index}",
                    "poi": {
                        "amapId": amap_id,
                        "name": f"地点 {index}",
                        "source": "amap-place-search",
                        "latitude": 39.9 + index / 100,
                        "longitude": 116.3 + index / 100,
                    },
                }
                for index, amap_id in enumerate(poi_ids, start=1)
            ],
        }
    ]
    return projection


