def test_grounded_read_only_partial_projection_validation_fails_closed(mutation, expected):
    projection = _grounded_read_only_partial_projection(**mutation)

    assert (
        AgentService._qualified_partial_comparison_projection(
            projection,
            root_portfolio_id="portfolio_root",
            planning_root_id="turn_root",
            request_fingerprint="request_fp",
            focus_brief_id="brief_alt",
            expected_base_version_id="ver_existing",
            source_assistant_turn_id="turn_partial_preview_result",
        )
        == expected
    )


def test_partial_preview_novelty_audit_reads_only_active_same_root_history():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "partial novelty")
        service = AgentService(connection, provider=SimpleNamespace())
        now = datetime.now(timezone.utc).isoformat()
        prior = _grounded_read_only_partial_projection(
            proposalId="partial:portfolio_root",
            sourceAssistantTurnId="turn_prior",
            choiceId="adopt_prior",
            focusBriefId="brief_base",
        )
        candidate = _grounded_read_only_partial_projection()
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_response_json, created_at, updated_at) "
            "VALUES (?, ?, 'assistant', 'prior', 1, 'active', ?, ?, ?)",
            (
                "turn_prior",
                session.session_id,
                json.dumps({"comparisonProjections": [prior]}),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_response_json, created_at, updated_at) "
            "VALUES (?, ?, 'assistant', 'foreign', 2, 'active', ?, ?, ?)",
            (
                "turn_foreign",
                session.session_id,
                json.dumps(
                    {
                        "comparisonProjections": [
                            {**prior, "proposalId": "partial:foreign", "rootPortfolioId": "foreign"}
                        ]
                    }
                ),
                now,
                now,
            ),
        )
        connection.commit()

        audit = service._partial_preview_novelty_audit(
            session_id=session.session_id,
            planning_root_id="turn_root",
            root_portfolio_id="portfolio_root",
            candidate_projection=candidate,
            current_assistant_turn_id="turn_partial_preview_result",
        )

    assert audit["passed"] is False
    assert audit["noveltyMode"] == "physical"
    assert audit["minimumNewPoiCount"] == 0
    assert audit["priorProjectionCount"] == 1


def test_partial_preview_novelty_uses_packed_baseline_and_accepts_two_physical_replacements():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "legacy novelty")
        service = AgentService(connection, provider=SimpleNamespace())
        now = datetime.now(timezone.utc).isoformat()
        classic = _partial_projection_with_physical_ids(
            "partial:portfolio_root",
            ["B000A7BD6C", "B000A81FMM", "B000A80HO9", "B0MGGZ3HPM", "B000A81CB2"],
        )
        legacy_local = _partial_projection_with_physical_ids(
            "partial-preview:portfolio_root:local",
            ["B000A7BD6C", "B000A7JEXW", "B000A80HO9", "B0MGGZ3HPM", "B000A81CB2"],
        )
        legacy_food = _partial_projection_with_physical_ids(
            "partial-preview:portfolio_root:food",
            ["B000A7BD6C", "B000A7JEXW", "B000A80HO9", "B0MGGZ3HPM", "B000A81CB2"],
        )
        for turn_index, (turn_id, projection) in enumerate(
            [
                ("turn_classic", classic),
                ("turn_legacy_local", legacy_local),
                ("turn_legacy_food", legacy_food),
            ],
            start=1,
        ):
            connection.execute(
                "INSERT INTO conversation_turns "
                "(id, session_id, role, content, turn_index, status, agent_response_json, created_at, updated_at) "
                "VALUES (?, ?, 'assistant', 'prior', ?, 'active', ?, ?, ?)",
                (
                    turn_id,
                    session.session_id,
                    turn_index,
                    json.dumps({"comparisonProjections": [projection]}),
                    now,
                    now,
                ),
            )
        connection.commit()
        nature = _partial_projection_with_physical_ids(
            "partial-preview:portfolio_root:nature",
            ["B000A7BD6C", "B000A7JEXW", "B000A80HO9", "B0H2N1J6LL", "B000A81CB2"],
        )

        audit = service._partial_preview_novelty_audit(
            session_id=session.session_id,
            planning_root_id="turn_root",
            root_portfolio_id="portfolio_root",
            candidate_projection=nature,
            current_assistant_turn_id="turn_nature",
        )

    assert audit["passed"] is True
    assert audit["noveltyMode"] == "physical"
    assert audit["minimumNewPoiCount"] == 2
    assert audit["reasonCode"] == "materially_distinct_physical_projection"
    assert audit["comparisonBaselineProposalIds"] == ["partial:portfolio_root"]
    assert audit["suppressedLegacyProjectionIds"] == [
        "partial-preview:portfolio_root:local",
        "partial-preview:portfolio_root:food",
    ]


def test_bounded_partial_expansion_failure_advances_cursor_without_failed_assistant_turn(monkeypatch):
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "bounded expansion failure")
        service = AgentService(connection, provider=SimpleNamespace())
        now = datetime.now(timezone.utc).isoformat()
        selected_choice = {
            "action": "retry_model_planning",
            "sourceAssistantTurnId": "turn_bounded_source",
            "choiceId": "choice_bounded_expansion",
        }
        request_context = {
            "selectedAgentChoice": selected_choice,
            "fallbackChoiceExecutionClaim": {"id": "choice_exec_bounded_expansion"},
            "_partialPlanExpansionAuthorized": True,
            "structuredPlanningChoiceResume": True,
        }
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_response_json, created_at, updated_at) "
            "VALUES (?, ?, 'assistant', '继续生成其他方案', 1, 'active', ?, ?, ?)",
            (
                "turn_bounded_source",
                session.session_id,
                json.dumps(
                    {
                        "choiceOptions": [
                            {
                                "id": "choice_bounded_expansion",
                                "action": "retry_model_planning",
                            }
                        ]
                    }
                ),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, agent_request_json, created_at, updated_at) "
            "VALUES (?, ?, 'user', '继续生成其他方案', 2, 'active', ?, ?, ?)",
            ("turn_bounded_request", session.session_id, json.dumps(request_context), now, now),
        )
        next_choice = {
            "id": "choice_next_expansion",
            "action": "retry_model_planning",
            "focusBriefId": "brief_next",
            "expansionFocusMode": "exact",
        }
        connection.execute(
            "INSERT INTO conversation_turns "
            "(id, session_id, role, content, turn_index, status, itinerary_version_id, error_json, "
            "agent_response_json, created_at, updated_at) "
            "VALUES (?, ?, 'assistant', '规划失败', 3, 'failed', ?, ?, ?, ?, ?)",
            (
                "turn_bounded_result",
                session.session_id,
                "ver_bounded_existing",
                json.dumps({"message": "portfolio_route_quality_unresolved:meal_detour_high"}),
                json.dumps({"terminalStatus": "failed", "choiceOptions": [next_choice]}),
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO agent_choice_executions "
            "(id, session_id, source_turn_id, source_user_turn_id, choice_id, action, status, "
            "created_at, updated_at) VALUES (?, ?, ?, ?, ?, 'retry_model_planning', 'executing', ?, ?)",
            (
                "choice_exec_bounded_expansion",
                session.session_id,
                "turn_bounded_source",
                "turn_bounded_root",
                "choice_bounded_expansion",
                now,
                now,
            ),
        )
        connection.commit()
        monkeypatch.setattr(
            service,
            "_partial_plan_expansion_outcome",
            lambda **_kwargs: {
                "succeeded": False,
                "identityMatches": True,
                "zeroWrite": True,
                "boundedAttemptConsumed": True,
                "cursorAdvanced": True,
                "cursorExhausted": False,
                "nextBriefId": "brief_next",
                "versionDelta": 0,
                "patchDelta": 0,
                "routeWriteDelta": 0,
            },
        )
        response = SimpleNamespace(
            version=SimpleNamespace(id="ver_bounded_existing"),
            terminal_status="failed",
            assistant_turn=SimpleNamespace(
                id="turn_bounded_result",
                status="failed",
                failure_reason="portfolio_route_quality_unresolved:meal_detour_high",
                content="规划失败",
                choice_options=[next_choice],
            ),
        )

        service._complete_controller_choice_execution(session.session_id, "turn_bounded_request", response)

        execution = connection.execute(
            "SELECT status, outcome_json FROM agent_choice_executions WHERE id = ?",
            ("choice_exec_bounded_expansion",),
        ).fetchone()
        result_turn = connection.execute(
            "SELECT status, error_json, itinerary_version_id, agent_response_json FROM conversation_turns WHERE id = ?",
            ("turn_bounded_result",),
        ).fetchone()
        source_payload = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                ("turn_bounded_source",),
            ).fetchone()[0]
        )

    outcome = json.loads(execution["outcome_json"])
    result_payload = json.loads(result_turn["agent_response_json"])
    assert execution["status"] == "failed_terminal"
    assert outcome["cursorAdvanced"] is True
    assert result_turn["status"] == "active"
    assert result_turn["error_json"] is None
    assert result_turn["itinerary_version_id"] == "ver_bounded_existing"
    assert result_payload["terminalStatus"] == "needs_confirmation"
    assert response.assistant_turn.status == "active"
    assert response.assistant_turn.failure_reason is None
    assert response.terminal_status == "needs_confirmation"
    assert source_payload["consumedChoiceIds"] == ["choice_bounded_expansion"]
    assert "已推进到下一个旅行方向" in response.assistant_turn.content


