def test_partial_plan_expansion_accepts_route_only_partial_without_pending_slots(monkeypatch):
    service = AgentService(sqlite3.connect(":memory:"), provider=SimpleNamespace())
    monkeypatch.setattr(service, "_creative_portfolio_enabled", lambda _context: True)
    selection_context = {
        "planningSelectionRootTurnId": "turn_root",
        "rootPortfolioId": "portfolio_root",
        "focusBriefId": "brief_focus",
        "requestContractFingerprint": "request_fp",
    }
    monkeypatch.setattr(
        service,
        "_active_partial_snapshot",
        lambda _session_id: {
            "portfolioPartialTimeline": {"status": "partial"},
            "portfolioPendingSlots": [],
            "portfolioSelectionContext": selection_context,
        },
    )
    monkeypatch.setattr(service, "_session", lambda _session_id: {"active_version_id": "version_partial"})
    root_summary = {
        "nextBriefId": "brief_next",
        "creativeExplorationFrontier": {
            "frontierState": "has_more",
            "remainingBudget": 8,
        },
    }
    monkeypatch.setattr(
        service,
        "_portfolio_continuation_root_exists",
        lambda _root_portfolio_id: True,
    )

    def fake_persisted_continuation(**kwargs):
        frontier = root_summary["creativeExplorationFrontier"]
        if (
            kwargs["active_version_id"] != "version_partial"
            or frontier.get("frontierState") not in {"ready", "has_more"}
            or int(frontier.get("remainingBudget") or 0) <= 0
        ):
            return False
        candidate = kwargs["option"]
        next_brief_id = str(root_summary.get("nextBriefId") or "")
        if next_brief_id:
            return bool(
                candidate.get("expansionFocusMode") == "exact" and candidate.get("focusBriefId") == next_brief_id
            )
        discover_next_authorized = bool(
            root_summary.get("failureReason") == "partial_expansion_root_initialized"
            or any(
                item.get("briefId") == "brief_focus" and item.get("status") in {"completed", "failed"}
                for item in root_summary.get("briefGenerationState") or []
            )
        )
        return bool(
            discover_next_authorized
            and candidate.get("expansionFocusMode") == "discover_next"
            and candidate.get("focusBriefId") == "brief_focus"
        )

    monkeypatch.setattr(
        service,
        "_persisted_portfolio_continuation_is_eligible",
        fake_persisted_continuation,
    )
    option = {
        **selection_context,
        "kind": "portfolio_partial_more_plans",
        "expectedBaseVersionId": "version_partial",
        "focusBriefId": "brief_next",
        "expansionFocusMode": "exact",
    }
    assert (
        service._is_current_partial_plan_expansion_option(
            session_id="session_root",
            option=option,
        )
        is True
    )
    root_summary.update(
        {
            "nextBriefId": "",
            "failureReason": "partial_expansion_root_initialized",
            "briefGenerationState": [
                {"briefId": "brief_last_fixed_direction", "status": "completed"},
            ],
        }
    )
    discover_next_option = {
        **option,
        "focusBriefId": "brief_focus",
        "expansionFocusMode": "discover_next",
    }
    assert (
        service._is_current_partial_plan_expansion_option(
            session_id="session_root",
            option=discover_next_option,
        )
        is True
    )
    root_summary.pop("failureReason")
    assert (
        service._is_current_partial_plan_expansion_option(
            session_id="session_root",
            option=discover_next_option,
        )
        is False
    )
    root_summary["failureReason"] = "partial_expansion_root_initialized"
    assert (
        service._is_current_partial_plan_expansion_option(
            session_id="session_root",
            option={
                **discover_next_option,
                "focusBriefId": "brief_last_fixed_direction",
            },
        )
        is False
    )
    root_summary["creativeExplorationFrontier"] = {
        "frontierState": "budget_exhausted",
        "remainingBudget": 0,
        "exhaustionReason": "max_generated_proposals_per_root",
    }
    assert (
        service._is_current_partial_plan_expansion_option(
            session_id="session_root",
            option=discover_next_option,
        )
        is False
    )


def test_controller_retry_choice_calls_model_controller_exactly_once_and_never_confirms_rule_draft(monkeypatch):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = _install_intent_contract(DeepSeekAgentProvider(api_key="", model="deepseek-test", timeout_seconds=7))
