    assert len(controller_contexts) == 1
    assert original in request_payload["effectiveUserMessage"]
    assert manual_value in request_payload["effectiveUserMessage"]
    assert request_payload["selectedAgentChoice"]["action"] == "manual_continuation"
    assert "explicitRuleSafeDraft" not in request_payload
    assert second.version is None
    assert execution["status"] == "succeeded"
    assert execution["action"] == "manual_continuation"


