def _persist_rule_safe_choice_fixture(connection, service, session_id):
    """Persist one server-owned rule-safe capability with complete route policy."""

    source_request = route_ready_request("北京2日游，晚上看城市夜景")
    source_user_turn_id = service._insert_turn(session_id, "user", source_request, "active")
    # The recorded helper intentionally owns turn index 1.  Keep the source
    # request before it so opaque-choice resolution can recover the exact text.
    connection.execute(
        "UPDATE conversation_turns SET turn_index = 0 WHERE id = ? AND session_id = ?",
        (source_user_turn_id, session_id),
    )
    request_envelope = record_completed_night_experience_context(
        connection,
        session_id,
        allowed_day_numbers=[1, 2],
        frequency="every_available_evening",
    )
    route_contract = canonical_server_route_decision_contract()
    request_envelope["requestIntentContract"]["routeDecisionContract"] = route_contract
    request_envelope["currentUserTurnId"] = source_user_turn_id
    source_assistant_turn_id = f"turn_recorded_experience_{session_id}"
    option = {
        "id": f"rule-safe:{source_assistant_turn_id}",
        "index": 1,
        "label": "确认生成规则安全草案",
        "kind": "safe_fallback_action",
        "action": "confirm_rule_safe_draft",
        "sourceUserTurnId": source_user_turn_id,
        "sourceDecisionId": f"decision:{source_assistant_turn_id}",
        "expectedBaseVersionId": None,
        "allowsManualInput": False,
    }
    source_payload = json.loads(
        connection.execute(
            "SELECT agent_response_json FROM conversation_turns WHERE id = ? AND session_id = ?",
            (source_assistant_turn_id, session_id),
        ).fetchone()[0]
    )
    source_payload["choiceOptions"] = [option]
    connection.execute(
        """UPDATE conversation_turns
        SET agent_request_json = ?, agent_response_json = ?
        WHERE id = ? AND session_id = ?""",
        (
            json.dumps(request_envelope, ensure_ascii=False),
            json.dumps(source_payload, ensure_ascii=False),
            source_assistant_turn_id,
            session_id,
        ),
    )
    connection.commit()
    normalized_route_contract = RouteInsertionScorer.normalized_route_decision_contract(route_contract)
    assert (
        RouteInsertionScorer.normalized_route_decision_contract(normalized_route_contract) == normalized_route_contract
    )
    assert route_contract["status"] == "ready"
    assert route_contract["missingFields"] == []
    assert route_contract["source"] == "request_intent_contract"
    return service._turn_response(source_assistant_turn_id), option


def _rule_safe_itinerary_write_state(connection, session_id, plan_id):
    """Capture exact rows so equal counts cannot hide delete-and-reinsert writes."""

    return {
        "versions": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM itinerary_versions WHERE session_id = ? ORDER BY id",
                (session_id,),
            ).fetchall()
        ],
        "patches": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM itinerary_patches WHERE session_id = ? ORDER BY id",
                (session_id,),
            ).fetchall()
        ],
        "routes": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM route_options WHERE plan_id = ? ORDER BY id",
                (plan_id,),
            ).fetchall()
        ],
        "days": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM itinerary_days WHERE plan_id = ? ORDER BY id",
                (plan_id,),
            ).fetchall()
        ],
        "segments": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM itinerary_segments WHERE plan_id = ? ORDER BY id",
                (plan_id,),
            ).fetchall()
        ],
        "pois": [
            tuple(row)
            for row in connection.execute(
                "SELECT * FROM pois WHERE plan_id = ? ORDER BY id",
                (plan_id,),
            ).fetchall()
        ],
    }


def test_safe_fallback_duplicate_claim_is_atomic_and_creates_one_execution(monkeypatch):
    clear_database()
    provider = _install_intent_contract(DeepSeekAgentProvider(api_key="", model="deepseek-test", timeout_seconds=7))
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "duplicate choice")
        service = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({}))
        source_assistant_turn, option = _persist_rule_safe_choice_fixture(
            connection,
            service,
            session.session_id,
        )
        write_state_before = _rule_safe_itinerary_write_state(
            connection,
            session.session_id,
            session.active_plan_id,
        )
        selected = {
            "sourceAssistantTurnId": source_assistant_turn.id,
            "choiceId": option["id"],
            "action": option["action"],
            "option": option,
        }
        claimed = service._claim_fallback_choice_execution(session.session_id, "turn_request_one", selected)

        with pytest.raises(HTTPException) as duplicate:
            service._claim_fallback_choice_execution(session.session_id, "turn_request_two", selected)

        execution_count = connection.execute(
            "SELECT COUNT(*) FROM agent_choice_executions WHERE session_id = ? AND source_turn_id = ? AND choice_id = ?",
            (session.session_id, source_assistant_turn.id, option["id"]),
        ).fetchone()[0]
        write_state_after = _rule_safe_itinerary_write_state(
            connection,
            session.session_id,
            session.active_plan_id,
        )

    assert claimed["status"] == "executing"
    assert duplicate.value.status_code == 409
    assert duplicate.value.detail["code"] == "agent_choice_execution_in_progress"
    assert execution_count == 1
    assert write_state_after == write_state_before


def test_cancel_before_choice_execution_claim_is_zero_execution():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "cancel before choice claim")
        service = AgentService(
            connection,
            provider=DeepSeekAgentProvider(api_key="", model="deepseek-test", timeout_seconds=7),
            poi_resolution_service=FakePoiResolver({}),
        )
        source_user_turn_id = service._insert_turn(session.session_id, "user", "原始请求", "active")
        source_assistant_turn_id = service._insert_turn(session.session_id, "assistant", "请选择", "active")
        execution_turn_id = service._insert_turn(session.session_id, "user", "执行选择", "active")
        option = {
            "id": "choice_cancel_before_claim",
            "action": "retry_model_planning",
            "sourceUserTurnId": source_user_turn_id,
        }
        selected = {
            "sourceAssistantTurnId": source_assistant_turn_id,
            "choiceId": option["id"],
            "action": option["action"],
            "option": option,
        }
        assert acquire_session_run(session.session_id) is True
        try:
            assert request_session_run_cancel(session.session_id) is True
            with pytest.raises(HTTPException) as error:
                service._claim_fallback_choice_execution(session.session_id, execution_turn_id, selected)
        finally:
            release_session_run(session.session_id)
        execution_count = connection.execute(
            "SELECT COUNT(*) FROM agent_choice_executions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()[0]

    assert error.value.status_code == 499
    assert error.value.detail == "agent_run_cancelled"
    assert execution_count == 0


