def test_candidate_hint_timeout_uses_cached_hints_without_retrying_provider(monkeypatch):
    clear_database()
    _CANDIDATE_HINT_CACHE.clear()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    hint_payload = {
        "hints": [
            {
                "poolId": "campus_visit_pool",
                "candidateHints": ["清华大学", "北京大学", "中国人民大学", "北京航空航天大学"],
                "hintPolicy": "llm_common_knowledge_hint",
            },
            {
                "poolId": "night_view_pool",
                "candidateHints": ["奥林匹克塔", "中信大厦", "景山公园", "什刹海"],
                "hintPolicy": "llm_common_knowledge_hint",
            },
        ],
        "warnings": [],
    }
    message = route_ready_request(
        "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
    )
    first_provider = HintRetryInitialProvider(hint_payload)
    second_provider = HintRetryInitialProvider({"hints": []}, fail_hints=True)

    with open_db() as connection:
        first_session = ConversationService(connection).create_session("北京", "北京会话")
        first = AgentService(
            connection, provider=first_provider, poi_resolution_service=FakePoiResolver({})
        ).send_message(
            first_session.session_id,
            AgentMessageRequest(content=message),
        )
        second_session = ConversationService(connection).create_session("北京", "北京会话 2")
        second = AgentService(
            connection, provider=second_provider, poi_resolution_service=FakePoiResolver({})
        ).send_message(
            second_session.session_id,
            AgentMessageRequest(content=message),
        )

    assert first.version is not None
    assert first_provider.hint_calls == 1
    assert second.version is not None
    assert second_provider.hint_calls == 0
    hint_event = next(event for event in second.planning_steps if event.type == "candidate_hints_provider")
    preview = hint_event.metadata["resultPreview"]
    assert preview["reason"] == "candidate_hint_cache_hit"
    assert preview["candidateHintCacheHit"] is True


