def test_manual_candidate_hints_resume_waiting_plan_uses_map_search_seeds(monkeypatch):
    clear_database()
    search_calls: list[str] = []
    hint_names = {"清华大学", "北京大学", "奥林匹克塔", "中信大厦"}
    provider_available = {"value": False}

    def search_verified_hint(self, city, keyword, category="all", limit=10):
        if not provider_available["value"]:
            raise HTTPException(status_code=429, detail="高德 POI 查询频率超限，请稍后重试")
        search_calls.append(str(keyword))
        if str(keyword) in hint_names:
            is_campus = str(keyword) in {"清华大学", "北京大学"}
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[
                    MapPoiResponse(
                        id=f"manual_amap_{abs(hash(str(keyword)))}",
                        name=f"{keyword}(高德验证)",
                        type="科教文化服务;学校;高等院校" if is_campus else "风景名胜;观景点",
                        city=city,
                        district="测试区",
                        address=f"{keyword} 地址",
                        longitude=116.35 + len(search_calls) * 0.001,
                        latitude=39.91 + len(search_calls) * 0.001,
                        category=category,
                        source=AMAP_PLACE_SOURCE,
                        sourceNote="高德 WebService POI 搜索",
                        confidence=0.95,
                        photos=[],
                    )
                ],
            )
        return fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)

    monkeypatch.setattr(MapPoiService, "search", search_verified_hint)
    provider = HintRetryInitialProvider({"hints": []}, fail_hints=True)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        first = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_plan_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        draft_pois = connection.execute(
            "SELECT source, amap_id, confidence FROM pois WHERE plan_id = ?",
            (active["active_plan_id"],),
        ).fetchall()

    assert provider.calls == 1
    assert provider.hint_calls == 1
    assert first.version is not None
    assert search_calls == []
    assert draft_pois
    assert all(row["source"] == "agent-text-timeline" for row in draft_pois)
    assert all(row["amap_id"] is None for row in draft_pois)
    assert all(float(row["confidence"] or 0) <= 0.45 for row in draft_pois)
    skeleton_event = next(event for event in first.planning_steps if event.type == "build_skeleton_draft_segments")
    assert skeleton_event.metadata["resultPreview"]["finalization"]["draftPersistenceOverride"] is True


