def test_agent_profile_uses_single_server_experience_family_and_rejects_ambiguous_family() -> None:
    service = AgentService(sqlite3.connect(":memory:"))
    itinerary_service = ItineraryService(sqlite3.connect(":memory:"))
    slot = DaySlot(
        "night_slot",
        1,
        "2026-10-01",
        "18:30-22:00",
        "18:30",
        90,
        "visit",
        "公共城市夜景",
        True,
        requirement_level="required",
        experience_goal="公共城市夜景",
    )
    pool = IntentPool(
        pool_id="night_pool",
        raw_need="公共城市夜景",
        city="北京",
        intent_type="night_view",
        target_count=1,
        goal_id="goal_night",
        requirement_level="required",
        assign_to_slots=[slot.slot_id],
    )

    def intent_for(
        families: list[Any],
        *,
        grounded_families: Optional[list[Any]] = None,
        include_grounding_fingerprint: bool = True,
    ):
        request_contract = {
            "requiredIntents": [
                {
                    "goalId": "goal_night",
                    "intentType": "night_view",
                    "experienceFamilies": families,
                }
            ],
            "experienceSpecs": [
                {
                    "intentType": "night_view",
                    "experienceFamilies": families,
                }
            ],
        }
        policy = service._experience_spec_policy_for_intent(
            request_contract,
            "night_view",
            request_contract["requiredIntents"][0],
        )
        slot.grounding_policy = {
            "experienceFamilies": list(
                grounded_families if grounded_families is not None else policy.get("experienceFamilies") or []
            ),
            "experienceSpecFingerprint": (
                str(policy.get("specFingerprint") or "") if include_grounding_fingerprint else ""
            ),
        }
        return service._poi_intent_from_pool_slot(
            pool,
            slot,
            itinerary_service,
            {
                "creativePortfolioMode": True,
                "requestIntentContract": request_contract,
            },
        )

    resolved_profile = intent_for(["public_city_view"]).search_profile
    assert resolved_profile is not None
    assert resolved_profile.experienceFamily == "public_city_view"
    assert resolved_profile.sourceEvidence.familySource == "experience_spec_family"
    assert resolved_profile.originalExperienceFamily is None
    assert "web_seed_then_amap" in {plan.mode for plan in resolved_profile.queryPlans}

    ambiguous_profile = intent_for(["public_city_view", "waterfront_evening"]).search_profile
    assert ambiguous_profile is not None
    assert ambiguous_profile.experienceFamily == "unknown"
    assert ambiguous_profile.sourceEvidence.familySource == "experience_spec_family_ambiguous"
    assert search_profile_provider_rejection_reason(ambiguous_profile) == ("experience_spec_family_ambiguous")

    split_brain_profile = intent_for(
        ["public_city_view"],
        grounded_families=["waterfront_evening"],
    ).search_profile
    assert split_brain_profile is not None
    assert split_brain_profile.experienceFamily == "unknown"
    assert split_brain_profile.sourceEvidence.familySource == "experience_spec_family_invalid"

    missing_fingerprint_profile = intent_for(
        ["public_city_view"],
        include_grounding_fingerprint=False,
    ).search_profile
    assert missing_fingerprint_profile is not None
    assert missing_fingerprint_profile.experienceFamily == "unknown"
    assert missing_fingerprint_profile.sourceEvidence.familySource == "experience_spec_family_invalid"

    invalid_profile = intent_for([None]).search_profile
    assert invalid_profile is not None
    assert invalid_profile.experienceFamily == "unknown"
    assert invalid_profile.sourceEvidence.familySource == "experience_spec_family_invalid"


