    scoped = AgentService._experience_spec_policy_for_intent(
        {
            "experienceSpecs": [
                {
                    "intentType": "night_view",
                    "allowedDayNumbers": [1, 2],
                    "experienceFamilies": ["public_city_view"],
                    "unresolvedDimensions": [],
                }
            ]
        },
        "night_view",
        {"allowedDayNumbers": [], "experienceFamilies": []},
    )
    assert scoped["allowedDayNumbers"] == [1, 2]
    assert scoped["experienceFamilies"] == ["public_city_view"]
    assert len(scoped["specFingerprint"]) == 64
