def test_fixed_public_city_request_projects_only_route_detour_clarification() -> None:
    service = AgentService(sqlite3.connect(":memory:"))

    contract = service._request_intent_contract(
        "2026年10月1日至10月2日，北京高校主题两日游，1人，公共交通，每日午餐体验当地特色美食，仅安排一晚公共城市夜景。",
        {"dates": ["2026-10-01", "2026-10-02"]},
        SimpleNamespace(meal_slots=[]),
    )

    assert contract["clarificationRequired"] is True, "route-decision-detour-dimension-missing"
    assert contract["clarificationReason"] == "route_decision.detour_tolerance"
    assert len(contract["clarificationDimensions"]) == 1
    dimension = contract["clarificationDimensions"][0]
    assert dimension["dimensionId"] == "route_decision.detour_tolerance"
    assert dimension["intentType"] == "route_decision"
    assert dimension["status"] == "unresolved"
    assert dimension["allowedSemanticFields"] == [
        "detourTolerance",
        "adjacentLegConstraint",
    ]
    assert dimension["candidateScope"]["missingFields"] == ["detourTolerance"]
    assert dimension["candidateScope"]["transportMode"] == "transit"
    assert contract["routeDecisionContract"]["status"] == "awaiting_clarification"
    assert contract["routeDecisionContract"]["missingFields"] == ["detourTolerance"]
    assert contract["experienceSpecs"][0]["experienceFamilies"] == ["public_city_view"]
    assert contract["experienceSpecs"][0]["frequency"] == "one"
    assert "detourTolerance" not in contract["experienceSpecs"][0]


def test_route_detour_opaque_choice_preserves_typed_value_and_is_zero_write(
    monkeypatch,
) -> None:
    clear_database()
    external_calls: list[str] = []

    def reject_external_call(*_args, **_kwargs):
        external_calls.append("unexpected")
        raise AssertionError("route clarification must stop before external providers")

    monkeypatch.setattr(MapPoiService, "search", reject_external_call)
    monkeypatch.setattr(MapPoiService, "search_nearby", reject_external_call)
    monkeypatch.setattr(RouteService, "build_routes", reject_external_call)
    request = (
        "2026年10月1日至10月2日，北京高校主题两日游，1人，公共交通，每日午餐体验当地特色美食，仅安排一晚公共城市夜景。"
    )
    expected_tolerance = {
        "maxGeneralizedCostDelta": 27.5,
        "maxDetourRatio": 0.23,
    }

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "route decision clarification")
        provider = RouteDecisionDetourClarificationProvider()
        service = AgentService(connection, provider=provider)
        before = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        first_checkpoint = service._turn_response(first.assistant_turn.id).clarification_checkpoint
        first_option = first.assistant_turn.choice_options[0]
        second = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content="使用已选择的路线容忍度",
                context={
                    "selectedAgentChoice": {
                        "sourceAssistantTurnId": first.assistant_turn.id,
                        "choiceId": first_option["id"],
                    }
                },
            ),
        )
        second_request = json.loads(
            connection.execute(
                "SELECT agent_request_json FROM conversation_turns WHERE id = ?",
                (second.assistant_turn.id,),
            ).fetchone()["agent_request_json"]
        )
        after = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()[0]
        with pytest.raises(HTTPException) as duplicate_error:
            service.send_message(
                session.session_id,
                AgentMessageRequest(
                    content="重复选择",
                    context={
                        "selectedAgentChoice": {
                            "sourceAssistantTurnId": first.assistant_turn.id,
                            "choiceId": first_option["id"],
                        }
                    },
                ),
            )

    final_contract = second_request["requestIntentContract"]
    route_contract = final_contract["routeDecisionContract"]
    answer = final_contract["clarificationAnswers"][-1]
    assert first_option["kind"] == "clarification_checkpoint"
    assert first_option["dimensionId"] == "route_decision.detour_tolerance"
    assert first_option["allowsManualInput"] is False
    assert first_checkpoint["question"]["allowFreeText"] is False
    assert first_option["semanticValue"] == {"detourTolerance": expected_tolerance}
    assert first_checkpoint["sourceAssistantTurnId"] == first.assistant_turn.id
    assert final_contract["clarificationDecisionSource"] == "controller_semantic_choice"
    assert final_contract["clarificationCheckpointId"] == first_checkpoint["checkpointId"]
    assert answer["dimensionId"] == "route_decision.detour_tolerance"
    assert answer["semanticValue"] == {"detourTolerance": expected_tolerance}
    assert answer["source"] == "structured_option"
    assert route_contract["status"] == "ready"
    assert route_contract["missingFields"] == []
    assert route_contract["detourTolerance"] == expected_tolerance
    assert route_contract["detourToleranceSource"] == "controller_semantic_choice"
    assert route_contract["provenance"]["detourToleranceIntentTypes"] == ["controller_semantic_choice"]
    assert RouteInsertionScorer.normalized_route_decision_contract(route_contract) is not None
    assert all(spec.get("intentType") != "route_decision" for spec in final_contract["experienceSpecs"])
    assert before == after == (0, 0, 0)
    assert active_version_id is None
    assert external_calls == []
    assert duplicate_error.value.status_code == 409
    assert duplicate_error.value.detail["code"] == "agent_choice_consumed"


def test_out_of_range_route_detour_choice_fails_closed_with_zero_writes() -> None:
    clear_database()
    request = (
        "2026年10月1日至10月2日，北京高校主题两日游，1人，公共交通，每日午餐体验当地特色美食，仅安排一晚公共城市夜景。"
    )

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "invalid route decision clarification")
        provider = RouteDecisionDetourClarificationProvider(max_detour_ratio=1.01)
        service = AgentService(connection, provider=provider)
        first = service.send_message(session.session_id, AgentMessageRequest(content=request))
        first_option = first.assistant_turn.choice_options[0]
        with pytest.raises(HTTPException) as error:
            service.send_message(
                session.session_id,
                AgentMessageRequest(
                    content="使用越界路线容忍度",
                    context={
                        "selectedAgentChoice": {
                            "sourceAssistantTurnId": first.assistant_turn.id,
                            "choiceId": first_option["id"],
                        }
                    },
                ),
            )
        counts = (
            connection.execute("SELECT COUNT(*) FROM itinerary_versions").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert error.value.status_code == 409
    assert error.value.detail["code"] == "route_decision_clarification_invalid"
    assert counts == (0, 0, 0)


