def test_editable_draft_commit_only_waives_soft_route_anchor_shortfall():
    readiness = {
        "adoptionReady": True,
        "draftAdoptionReady": True,
        "adoptionMode": "editable_draft",
        "hardPendingSlotCount": 0,
        "softPendingSlotCount": 2,
    }

    assert (
        AgentService._editable_draft_commit_allowed(
            readiness,
            {"draftPassed": True, "passed": False},
        )
        is True
    )
    assert (
        AgentService._editable_draft_commit_allowed(
            {**readiness, "hardPendingSlotCount": 1},
            {"draftPassed": True, "passed": False},
        )
        is False
    )
    assert (
        AgentService._editable_draft_commit_allowed(
            {**readiness, "adoptionMode": "complete"},
            {"draftPassed": False, "passed": True},
        )
        is False
    )
    assert (
        AgentService._repaired_proposal_offer_allowed(
            readiness,
            {"draftPassed": True, "passed": False},
        )
        is True
    )
    assert (
        AgentService._repaired_proposal_offer_allowed(
            {**readiness, "hardPendingSlotCount": 1},
            {"draftPassed": True, "passed": False},
        )
        is False
    )
    assert (
        AgentService._repaired_proposal_offer_allowed(
            {**readiness, "adoptionReady": False},
            {"draftPassed": False, "passed": True},
        )
        is True
    )


