def test_http_429_amap_error_is_classified_as_rate_limited(monkeypatch):
    clear_database()

    def rate_limited_search(*_args, **_kwargs):
        raise HTTPException(
            status_code=502,
            detail={
                "code": "provider_rate_limited",
                "message": "高德 POI 查询暂时受限，请稍后重试。",
                "providerName": "amap",
                "retryAfterSeconds": 90,
                "debug": {
                    "endpoint": "place/text",
                    "source": "place/text",
                    "httpStatusCode": 429,
                    "rawInfo": "HTTP 429",
                    "classifiedReason": "http_429",
                    "retryAfterSeconds": 90,
                    "requestParams": {"keywords": "清华大学", "city": "110000", "types": "141200"},
                    "processId": 12345,
                    "cacheHit": False,
                    "localCooldown": False,
                },
            },
        )

    monkeypatch.setattr(MapPoiService, "search", rate_limited_search)
    provider = StagedInitialProvider(two_day_initial_day_slot_output())
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )

    assert response.version is not None
    collect_event = next(event for event in response.planning_steps if event.type == "collect_candidates")
    collect_preview = collect_event.metadata["resultPreview"]
    assert collect_preview["rateLimited"] is True
    assert collect_preview["poolReports"][0]["providerState"] == "rate_limited"
    assert collect_preview["providerDebug"][0]["classifiedReason"] == "http_429"
    assert collect_preview["providerDebug"][0]["source"] == "place/text"
    assert collect_preview["poolReports"][0]["providerDebug"][0]["httpStatusCode"] == 429
    assert collect_preview["poolReports"][0]["providerDebug"][0]["source"] == "place/text"
    assert "key" not in collect_preview["providerDebug"][0]["requestParams"]
    create_event = next(event for event in response.planning_steps if event.type == "create_itinerary_version")
    assert create_event.metadata["resultPreview"]["activeVersionId"]
    skeleton_preview = next(
        event.metadata["resultPreview"]
        for event in response.planning_steps
        if event.type == "build_skeleton_draft_segments"
    )
    assert skeleton_preview["finalization"]["draftPersistenceOverride"] is True


