def test_empty_candidate_first_stays_retryable_without_skeleton_write(monkeypatch):
    clear_database()
    provider = StagedInitialProvider(two_day_initial_day_slot_output())

    def fake_build(self, _session, _initial_plan, _pipeline_context, _tool_events, **_kwargs):
        return [], {
            "rateLimited": True,
            "rateLimitReason": "provider_rate_limited",
            "resultState": "provider_rate_limited",
            "warnings": ["地图候选服务暂时限流。"],
            "unresolvedSlots": [],
            "unresolvedDays": [1, 2],
            "persistableSegmentCount": 0,
            "requiredIntentCoverage": [],
            "poolReports": [],
            "qualityContract": {
                "canCreateActiveVersion": False,
                "qualityStatus": "draft_needs_completion",
                "hardFailures": ["no_minimum_viable_day"],
                "softWarnings": [],
            },
        }

    def fake_enrichment(self, session_before, initial_version_id, *_args, **_kwargs):
        version = self._version(initial_version_id, session_before["id"], session_before["active_plan_id"])
        return {
            "state": "draft_created_with_pending_grounding",
            "partialGrounding": True,
            "warnings": ["部分地点待地图候选补全。"],
        }, self._version_response(version)

    monkeypatch.setattr(AgentService, "_build_candidate_first_segment_plans", fake_build)
    monkeypatch.setattr(AgentService, "_run_staged_enrichment", fake_enrichment)

    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content="今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先。想要体验当地特色美食"
            ),
        )
        active = connection.execute(
            "SELECT active_plan_id, active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        draft_pois = connection.execute(
            """
            SELECT amap_id, source, confidence, source_note
            FROM pois
            WHERE plan_id = ? AND source = 'agent-text-timeline'
            """,
            (active["active_plan_id"],),
        ).fetchall()
        accepted_patch_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_patches WHERE validation_status = 'accepted'"
        ).fetchone()[0]

    assert response.version is None
    assert response.assistant_turn.status == "active"
    assert response.terminal_status == "needs_confirmation"
    assert active["active_version_id"] is None
    assert draft_pois == []
    assert accepted_patch_count == 0


