def test_explicit_poi_duration_is_persisted_as_user_lock_and_cascades_schedule():
    service = AgentService(sqlite3.connect(":memory:"))
    plans = [
        PersistableSegmentPlan(
            1,
            "09:00",
            135,
            "visit",
            True,
            POI("poi_pku", "北京大学", "北京", "campus", 39.99, 116.31, source=AMAP_PLACE_SOURCE, amap_id="amap_pku"),
            "北京大学",
            "campus_visit",
            "agent_selected_candidate",
            "not_checked",
        ),
        PersistableSegmentPlan(
            1,
            "09:30",
            90,
            "visit",
            True,
            POI("poi_next", "颐和园", "北京", "scenic", 39.99, 116.27, source=AMAP_PLACE_SOURCE, amap_id="amap_next"),
            "颐和园",
            "",
            "agent_selected_candidate",
            "not_checked",
        ),
    ]
    snapshot = service._snapshot_from_persistable_segment_plans(
        {"active_plan_id": "plan_test", "city": "北京"},
        AgentInitialPlanOutput(reply="", mode="plan", daySlots=[], intentPools=[]),
        plans,
        {"latestUserMessage": "北京大学只逛1小时，然后去颐和园"},
    )

    first, second = snapshot["days"][0]["segments"]
    duration = first["estimateMetadata"]["duration"]
    assert first["startTime"] == "09:00"
    assert first["endTime"] == "10:00"
    assert duration["preferredMinutes"] == 60
    assert duration["minMinutes"] == 60
    assert duration["maxMinutes"] == 60
    assert duration["source"] == "user_locked"
    assert duration["userLocked"] is True
    assert second["startTime"] == "10:00"


