def test_required_meal_rate_limit_preview_is_waiting_not_not_required(monkeypatch):
    clear_database()

    def meal_rate_limited(_self, city, keyword, category="all", limit=10):
        keyword_text = str(keyword)
        if category == "food" or any(token in keyword_text for token in ("午餐", "晚餐", "餐厅", "美食")):
            raise HTTPException(status_code=429, detail="高德 POI 查询频率超限，请稍后重试")
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword,
            category=category,
            providerName="fake-amap",
            queriedAt=datetime.now(timezone.utc),
            pois=[
                MapPoiResponse(
                    id=f"amap_{abs(hash(keyword_text))}",
                    name=keyword_text,
                    type="科教文化服务;学校;高等院校" if category == "campus" else "风景名胜;观景点",
                    city=city,
                    district="测试区",
                    address=f"{keyword_text} 地址",
                    longitude=116.30 + (abs(hash(keyword_text)) % 20) * 0.001,
                    latitude=39.90 + (abs(hash(keyword_text)) % 20) * 0.001,
                    category=category,
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.95,
                    photos=[],
                )
            ],
        )

    def meal_nearby_rate_limited(_self, city, longitude, latitude, keyword, category="all", radius=1500, limit=10):
        raise HTTPException(status_code=429, detail="高德 POI 查询频率超限，请稍后重试")

    monkeypatch.setattr(MapPoiService, "search", meal_rate_limited)
    monkeypatch.setattr(MapPoiService, "search_nearby", meal_nearby_rate_limited)
    provider = StagedInitialProvider(two_day_initial_day_slot_output())
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        record_completed_night_experience_context(
            connection,
            session.session_id,
            allowed_day_numbers=[1, 2],
            frequency="every_available_evening",
        )
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。"
                    "10月1日到2日，2天，中等预算，1人，公交地铁优先。午餐晚餐我想体验当地美食"
                )
            ),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()[0]
        accepted_patch_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_patches WHERE validation_status = 'accepted'"
        ).fetchone()[0]

    assert response.version is None
    assert response.assistant_turn.status == "active"
    assert response.terminal_status == "needs_confirmation"
    assert active_version_id is None
    assert accepted_patch_count == 0
    collect_preview = next(
        event.metadata["resultPreview"] for event in response.planning_steps if event.type == "collect_candidates"
    )
    meal_slots = [
        item
        for item in collect_preview["unresolvedSlots"]
        if item.get("kind") == "meal" and item.get("reason") == "provider_rate_limited"
    ]
    assert meal_slots
    assert all(slot["state"] == "provider_rate_limited" for slot in meal_slots)


