def test_generic_pool_without_hints_does_not_write_low_quality_defaults(monkeypatch):
    clear_database()
    payload = two_day_initial_day_slot_output()
    for pool in payload["intentPools"]:
        pool["candidateHints"] = []
        pool["hintPolicy"] = "no_hint"

    def low_quality_generic_search(_self, city, keyword, category="all", limit=10):
        if category == "campus":
            name = "中央广播电视大学"
            poi_type = "科教文化服务;学校;成人教育"
        else:
            name = "世纪水门"
            poi_type = "商务住宅;住宅区"
        return MapPoiSearchResponse(
            city=city,
            keyword=keyword,
            category=category,
            providerName="fake-amap",
            queriedAt=datetime.now(timezone.utc),
            pois=[
                MapPoiResponse(
                    id=f"amap_{abs(hash(name))}",
                    name=name,
                    type=poi_type,
                    city=city,
                    district="测试区",
                    address=f"{name} 地址",
                    longitude=116.40,
                    latitude=39.91,
                    category=category,
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.93,
                    photos=[],
                )
            ],
        )

    monkeypatch.setattr(MapPoiService, "search", low_quality_generic_search)
    provider = StagedInitialProvider(payload)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        poi_names = [row[0] for row in connection.execute("SELECT name FROM pois").fetchall()]
        assistant_json = json.loads(
            connection.execute(
                "SELECT agent_response_json FROM conversation_turns WHERE id = ?",
                (response.assistant_turn.id,),
            ).fetchone()[0]
        )

    assert response.assistant_turn.status == "active"
    assert response.version is not None
    assert any("暂未" in warning or "候选" in warning or "地点" in warning for warning in response.warnings)
    assert "中央广播电视大学" not in poi_names
    assert "世纪水门" not in poi_names
    hint_event = next(event for event in response.planning_steps if event.type == "candidate_hints_provider")
    assert hint_event.metadata["resultPreview"]["serverFallbackUsed"] is True
    assert hint_event.metadata["resultPreview"]["candidateHintsAdded"] > 0
    collect_event = next(event for event in response.planning_steps if event.type == "collect_candidates")
    build_event = next(event for event in response.planning_steps if event.type == "build_persistable_segment_plans")
    collect_preview = collect_event.metadata["resultPreview"]
    build_preview = build_event.metadata["resultPreview"]
    first_pool_report = collect_preview["poolReports"][0]
    unresolved_slot = collect_preview["unresolvedSlots"][0]
    assert first_pool_report["rawNeed"] == "高校参观"
    assert first_pool_report["candidateHintCount"] > 0
    assert first_pool_report["queryCount"] > 0
    assert first_pool_report["candidateCount"] >= 0
    assert first_pool_report["selectedCount"] == 0
    assert first_pool_report["coverageStatus"] == "missing"
    assert first_pool_report["providerState"] == "ok"
    assert isinstance(first_pool_report["topCandidates"], list)
    assert not any(item.get("decision") == "selected" for item in first_pool_report["topCandidates"])
    assert isinstance(first_pool_report["rejectedReasonCounts"], dict)
    assert unresolved_slot["slotId"]
    assert unresolved_slot["kind"] == "visit"
    assert unresolved_slot["poolId"] == "campus_visit_pool"
    assert unresolved_slot["candidateHintCount"] > 0
    assert unresolved_slot["reason"] in {
        "ok",
        "low_confidence_or_ambiguous_candidates",
        "low_quality_generic_candidates",
    }
    assert "topCandidatePreview" in unresolved_slot
    assert unresolved_slot["nextAction"] in {"retry_candidate_hints", "retry_unfinished_poi_grounding"}
    assert build_preview["routeAnchorRequiredCount"] == 6
    assert build_preview["routeAnchorSelectedCount"] == 0
    assert build_preview["minimumViableRule"] == "partial timelines require at least 1 verified real route anchor"
    assert build_preview["dayReadiness"]
    assert all(day["meetsMinimumViableDay"] is False for day in build_preview["dayReadiness"])
    skeleton_event = next(event for event in response.planning_steps if event.type == "build_skeleton_draft_segments")
    assert skeleton_event.metadata["resultPreview"]["finalization"]["draftPersistenceOverride"] is True
    assert assistant_json["resultState"] in {"partial_success", "draft_created_with_pending_grounding"}


