def test_initial_staged_pipeline_uses_generic_day_slots_after_provider_timeout(monkeypatch):
    clear_database()
    search_calls: list[tuple[str, str]] = []

    def record_amap_search(self, city, keyword, category="all", limit=10):
        search_calls.append((str(keyword), str(category)))
        return fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)

    monkeypatch.setattr(MapPoiService, "search", record_amap_search)
    provider = TimeoutInitialProvider()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()

    provider_events = [event for event in response.planning_steps if event.type == "initial_day_slot_provider"]
    decompose_events = [event for event in response.planning_steps if event.type == "decompose_intent_pools"]
    assert provider.calls == 1
    assert response.assistant_turn.status == "active"
    assert response.version is not None
    assert active["active_version_id"] == response.version.id
    assert search_calls
    assert provider_events
    assert provider_events[0].status == "fallback"
    provider_preview = provider_events[0].metadata["resultPreview"]
    assert provider_preview["fallbackUsed"] is True
    assert provider_preview["fallbackReason"] == "provider_call_error"
    assert provider_preview["fallbackType"] == "server_generic_day_slots"
    assert provider_preview["parseError"] == "initial DaySlot provider read timed out"
    timeout_debug = provider_preview["providerTimeoutDiagnostics"]
    assert timeout_debug["stage"] == "initial_day_slot_provider"
    assert timeout_debug["fallbackUsed"] is True
    assert timeout_debug["fallbackType"] == "server_generic_day_slots"
    assert timeout_debug["userVisibleImpact"] == "none"
    assert decompose_events
    decompose_preview = decompose_events[0].metadata["resultPreview"]
    assert decompose_preview["fallbackUsed"] is True
    assert decompose_preview["fallbackType"] == "server_generic_day_slots"
    assert decompose_preview["candidateHintsAvailable"] is False
    assert decompose_preview["semanticCandidateHintNeeded"] is True
    assert decompose_preview["implication"] == "generic pools use stricter threshold"
    assert not any("deterministic_fallback_full_itinerary" in warning for warning in response.warnings)


def test_v3_draft_timeout_publishes_truthful_partial_without_second_controller(monkeypatch):
    clear_database()

    def verified_campus_search(self, city, keyword, category="all", limit=10):
        response = fake_amap_search_with_keyword_candidate(self, city, keyword, category=category, limit=limit)
        if category == "campus" or any(marker in str(keyword) for marker in ("大学", "高校", "学院", "校区", "985")):
            response.pois = [
                MapPoiResponse(
                    id="amap_peking_university",
                    name="北京大学",
                    type="科教文化服务;学校;高等院校",
                    city=city,
                    district="海淀区",
                    address="颐和园路5号",
                    longitude=116.3109,
                    latitude=39.9928,
                    category="campus",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.95,
                    photos=[],
                ),
                MapPoiResponse(
                    id="amap_tsinghua_university",
                    name="清华大学",
                    type="科教文化服务;学校;高等院校",
                    city=city,
                    district="海淀区",
                    address="双清路30号",
                    longitude=116.3269,
                    latitude=40.0032,
                    category="campus",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.95,
                    photos=[],
                ),
            ]
        elif category == "museum" or "博物馆" in str(keyword) or "美术馆" in str(keyword):
            response.pois[0].id = "amap_national_art_museum"
            response.pois[0].name = "中国美术馆"
            response.pois[0].type = "科教文化服务;博物馆"
        return response

    monkeypatch.setattr(MapPoiService, "search", verified_campus_search)

    class V3TimeoutDraftProvider(IntentContractProviderMixin):
        model = "provider-shaped"

        def __init__(self) -> None:
            self.decision_calls = 0
            self.initial_calls = 0
            self.tool_loop_calls = 0

        def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
            self.decision_calls += 1
            observation = context.get("observation") if isinstance(context.get("observation"), dict) else {}
            lifecycle = str((observation.get("itinerary") or {}).get("lifecycleState") or "")
            if lifecycle not in {"", "empty_scaffold", "no_active_version"}:
                return {
                    "schemaVersion": "agent-decision-v3",
                    "primaryAction": "finish",
                    "actionDirective": {"type": "finish", "assistantReply": "草稿已保存。"},
                }
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "draft_itinerary",
                "actionDirective": {
                    "type": "draft_itinerary",
                    "goalPriority": ["goal_campus_visit", "goal_museum", "goal_meal"],
                    "dayStrategies": [
                        {
                            "dayNumber": 1,
                            "theme": "高校与可选美食",
                            "requiredGoalIds": ["goal_campus_visit"],
                            "requiredGoalCounts": {"goal_campus_visit": 1},
                            "optionalGoalIds": ["goal_meal"],
                        },
                        {
                            "dayNumber": 2,
                            "theme": "博物馆",
                            "requiredGoalIds": ["goal_museum"],
                            "requiredGoalCounts": {"goal_museum": 1},
                            "optionalGoalIds": [],
                        },
                    ],
                    "optionalExperienceBudget": 1,
                    "routePlanningPolicy": {
                        "objective": "least_generalized_cost",
                        "source": "controller_estimate",
                        "allowExperienceDetour": True,
                        "mobilityProfile": {
                            "transportMode": "transit",
                            "paceClass": "standard",
                        },
                        "detourEnvelope": {
                            "maxGeneralizedCostDelta": 15.0,
                            "maxDetourRatio": 0.15,
                        },
                    },
                    "occurrenceScheduleHints": [
                        {
                            "goalId": "goal_campus_visit",
                            "dayNumber": 1,
                            "dayPart": "morning",
                            "sequence": 1,
                            "preferredStartTime": "09:00",
                            "durationEstimate": {"min": 90, "preferred": 120, "max": 150},
                            "estimateSource": "controller_estimate",
                            "confidence": 0.95,
                        },
                        {
                            "goalId": "goal_meal",
                            "dayNumber": 1,
                            "dayPart": "noon",
                            "sequence": 2,
                            "preferredStartTime": "12:00",
                            "durationEstimate": {"min": 45, "preferred": 60, "max": 90},
                            "estimateSource": "controller_estimate",
                            "confidence": 0.9,
                        },
                        {
                            "goalId": "goal_museum",
                            "dayNumber": 2,
                            "dayPart": "morning",
                            "sequence": 1,
                            "preferredStartTime": "09:00",
                            "durationEstimate": {"min": 90, "preferred": 120, "max": 150},
                            "estimateSource": "controller_estimate",
                            "confidence": 0.95,
                        },
                    ],
                },
            }

        def generate_initial_plan(self, _context):
            self.initial_calls += 1
            raise TimeoutError("initial DaySlot provider read timed out")

        def run_tool_loop(self, _context, _tool_registry):
            self.tool_loop_calls += 1
            raise AssertionError("draft timeout fallback must not enter a nested tool/controller loop")

    provider = V3TimeoutDraftProvider()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "V3 timeout fallback")
        response = AgentService(
            connection,
            provider=provider,
            poi_resolution_service=FakePoiResolver({}),
        ).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观985大学两日游，然后体验北京当地博物馆。"
                    "10月1日到2日，2天，中等预算，1人，公交地铁优先，品尝北京当地特色美食"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        version_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
            (session.session_id,),
        ).fetchone()[0]
        segment_count = connection.execute(
            "SELECT COUNT(*) FROM itinerary_segments WHERE plan_id = ?",
            (session.active_plan_id,),
        ).fetchone()[0]

    fallback_event = next(item for item in response.planning_steps if item.type == "deterministic_slot_fallback")
    initial_event = next(item for item in response.planning_steps if item.type == "initial_day_slot_provider")
    stop_event = next(item for item in response.planning_steps if item.type == "agent_stop")
    assert provider.initial_calls == 1
    assert provider.tool_loop_calls == 0
    assert provider.decision_calls == 1
    assert response.version is not None, (
        response.assistant_turn.content,
        response.assistant_turn.failure_reason,
        response.warnings,
    )
    assert active["active_version_id"] == response.version.id
    assert response.terminal_status == "draft_pending_grounding"
    assert version_count == 1
    assert segment_count > 0
    assert initial_event.status == "fallback"
    assert initial_event.metadata["resultPreview"]["fallbackReason"] == "initial_day_slot_provider_timeout"
    assert initial_event.metadata["resultPreview"]["fallbackType"] == "deterministic_slot_fallback"
    assert fallback_event.metadata["resultPreview"]["finalPoiInvented"] is False
    assert fallback_event.metadata["resultPreview"]["activeVersionInvented"] is False
    assert fallback_event.metadata["resultPreview"]["verifierInvented"] is False
    assert stop_event.metadata["stopReason"] == "partial_timeline_needs_confirmation"
    assert stop_event.metadata["partialResultTerminal"] is True
    assert stop_event.metadata["partialResultVersionId"] == response.version.id
    assert stop_event.metadata["partialPendingSlotCount"] == 1
    assert stop_event.metadata["postObservationControllerCalled"] is False
    draft_outcome = next(
        item.metadata["resultPreview"]
        for item in response.planning_steps
        if item.type == "agent_action_outcome"
        and item.metadata.get("resultPreview", {}).get("action") == "draft_itinerary"
    )
    assert draft_outcome["status"] == "partial"
    assert draft_outcome["controlLoopDisposition"] == "terminal_needs_confirmation"
    assert not any(
        item.type == "agent_observation" and item.metadata.get("cycleIndex") == 1 for item in response.planning_steps
    )
    pending_slots = [slot for day in response.itinerary.days for slot in day.pending_slots]
    assert len(pending_slots) == 1
    assert pending_slots[0].kind == "meal"
    choice_actions = {str(option.get("action") or "") for option in response.assistant_turn.choice_options}
    assert choice_actions.isdisjoint({"select_plan_proposal", "confirm_rule_safe_draft", "adopt_active_partial"})


