@pytest.mark.parametrize(
    ("tampered_field", "tampered_value"),
    [
        ("briefId", "brief_other"),
        ("dayNumber", 2),
    ],
)
def test_density_candidate_choice_rejects_tampered_brief_or_day_scope(
    tampered_field: str,
    tampered_value: Any,
) -> None:
    clear_database()
    poi = MapPoiResponse(
        id="B000A7O5PK",
        name="什刹海",
        type="风景名胜;风景名胜相关;旅游景点",
        city="北京",
        district="西城区",
        address="什刹海街道",
        longitude=116.389,
        latitude=39.941,
        category="scenic",
        source=AMAP_PLACE_SOURCE,
        sourceNote="高德 WebService POI 搜索",
        confidence=0.94,
        photos=[],
    )
    candidate = {
        **poi.model_dump(by_alias=True),
        "briefId": "brief_day_1",
        "poolId": "pool_day_1_walk",
        "planningSlotId": "slot_day_1_walk",
        "dayNumber": 1,
        "intentType": "area_walk",
    }
    option = {
        "kind": "portfolio_density_candidate",
        "continuationType": "portfolio_density_completion",
        "candidateRecordId": "cand_day_1_walk",
        "amapId": poi.id,
        "sourceGoalId": "",
        "briefId": "brief_day_1",
        "poolId": "pool_day_1_walk",
        "planningSlotId": "slot_day_1_walk",
        "dayNumber": 1,
    }
    option[tampered_field] = tampered_value
    with open_db() as connection:
        service = AgentService(connection)
        session = ConversationService(connection).create_session(
            "北京",
            "density scope tamper",
        )
        turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "请选择街区漫步地点",
            "active",
        )
        connection.execute(
            """
            INSERT INTO amap_poi_candidates (
                id, session_id, turn_id, query, segment_id, city, category, status,
                candidates_json, selected_amap_id, created_at
            ) VALUES (?, ?, ?, ?, NULL, ?, ?, 'pending', ?, NULL, ?)
            """,
            (
                "cand_day_1_walk",
                session.session_id,
                turn_id,
                "Day 1 街区漫步",
                "北京",
                "area_walk",
                json.dumps([candidate], ensure_ascii=False),
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        connection.commit()

        with pytest.raises(HTTPException) as raised:
            service._select_planning_material_tradeoff_candidate(
                session.session_id,
                {"option": option},
            )
        selected_amap_id = connection.execute(
            "SELECT selected_amap_id FROM amap_poi_candidates WHERE id = ?",
            ("cand_day_1_walk",),
        ).fetchone()["selected_amap_id"]

    assert raised.value.status_code == 409
    assert raised.value.detail["code"] == "agent_choice_identity_mismatch"
    assert selected_amap_id is None


