def test_material_tradeoff_options_offer_one_group_and_inline_custom_input():
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        session = ConversationService(connection).create_session("北京", "grouped material choices")
        now = datetime.now(timezone.utc).isoformat()
        for group_id, goal_id, slot_id, prefix in (
            ("cand_group_campus", "goal_campus_visit", "day1_goal_campus_1", "campus"),
            ("cand_group_museum", "goal_museum", "day1_goal_museum_1", "museum"),
        ):
            candidates = [
                {
                    "id": f"{prefix}_{index}",
                    "name": f"{prefix} {index}",
                    "type": "科教文化服务",
                    "city": "北京",
                    "district": "海淀区",
                    "address": "测试地址",
                    "longitude": 116.3 + index / 100,
                    "latitude": 39.9 + index / 100,
                    "category": "museum" if prefix == "museum" else "university",
                    "source": AMAP_PLACE_SOURCE,
                    "sourceGoalId": goal_id,
                    "planningSlotId": slot_id,
                }
                for index in (1, 2)
            ]
            connection.execute(
                """
                INSERT INTO amap_poi_candidates (
                    id, session_id, turn_id, query, segment_id, city, category, status,
                    candidates_json, selected_amap_id, created_at
                ) VALUES (?, ?, ?, ?, NULL, ?, ?, 'pending', ?, NULL, ?)
                """,
                (
                    group_id,
                    session.session_id,
                    "turn_group_source",
                    prefix,
                    "北京",
                    prefix,
                    json.dumps(candidates),
                    now,
                ),
            )
        connection.commit()
        options = service._planning_material_tradeoff_choice_options(
            session.session_id,
            {},
            "turn_group_user",
        )

    assert [option["candidateRecordId"] for option in options[:-1]] == [
        "cand_group_campus",
        "cand_group_campus",
    ]
    assert options[-1]["kind"] == "custom_input"
    assert {option["selectionGroupId"] for option in options} == {"cand_group_campus"}


