def test_v3_draft_timeout_preserves_material_tradeoff_as_zero_write_refresh(monkeypatch):
    clear_database()

    def recorded_initial_candidates(self, city, keyword, category="all", limit=10):
        response = fake_amap_search_with_keyword_candidate(
            self,
            city,
            keyword,
            category=category,
            limit=limit,
        )
        if category == "campus" or any(marker in str(keyword) for marker in ("大学", "高校", "学院", "校区", "985")):
            response.pois[0].id = "amap_peking_university"
            response.pois[0].name = "北京大学"
            response.pois[0].type = "科教文化服务;学校;高等院校"
        return response

    monkeypatch.setattr(MapPoiService, "search", recorded_initial_candidates)

    class MaterialTradeoffResolver:
        def __init__(self, db):
            self.db = db
            self.calls = 0

        def resolve(self, payload, commit=True):
            self.calls += 1
            candidates = [
                MapPoiResponse(
                    id="amap_capital_museum",
                    name="首都博物馆",
                    type="科教文化服务;博物馆",
                    city="北京",
                    district="西城区",
                    address="复兴门外大街16号",
                    longitude=116.341,
                    latitude=39.907,
                    category="museum",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.93,
                    photos=[],
                ),
                MapPoiResponse(
                    id="amap_national_museum",
                    name="中国国家博物馆",
                    type="科教文化服务;博物馆",
                    city="北京",
                    district="东城区",
                    address="东长安街16号",
                    longitude=116.401,
                    latitude=39.905,
                    category="museum",
                    source=AMAP_PLACE_SOURCE,
                    sourceNote="高德 WebService POI 搜索",
                    confidence=0.93,
                    photos=[],
                ),
            ]
            self.db.execute(
                """
                INSERT INTO amap_poi_candidates (
                    id, session_id, turn_id, query, city, category, status,
                    candidates_json, selected_amap_id, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    "cand_museum_tradeoff",
                    payload.session_id,
                    payload.turn_id,
                    "博物馆",
                    payload.city,
                    payload.queries[0].category,
                    "pending",
                    json.dumps(
                        [
                            {
                                **item.model_dump(by_alias=True),
                                "sourceGoalId": "goal_museum",
                                "planningSlotId": "day2_goal_museum_1",
                            }
                            for item in candidates
                        ],
                        ensure_ascii=False,
                    ),
                    None,
                    datetime.now(timezone.utc).isoformat(),
                ),
            )
            if commit:
                self.db.commit()
            return MapPoiResolveResponse(
                resolved=[],
                pending=[
                    MapPoiPendingItemResponse(
                        candidateRecordId="cand_museum_tradeoff",
                        query=payload.queries[0].name,
                        reason="material_tradeoff",
                        candidates=candidates,
                    )
                ],
            )

    class V3TimeoutMaterialTradeoffProvider(IntentContractProviderMixin):
        model = "provider-shaped"

        def __init__(self):
            self.decision_calls = 0
            self.initial_calls = 0
            self.tool_loop_calls = 0
            self.observations = []

        def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
            self.decision_calls += 1
            observation = context.get("observation") if isinstance(context.get("observation"), dict) else {}
            self.observations.append(observation)
            cycle = int(observation.get("cycleIndex") or 0)
            if cycle == 0:
                return {
                    "schemaVersion": "agent-decision-v3",
                    "primaryAction": "draft_itinerary",
                    "actionDirective": {
                        "type": "draft_itinerary",
                        "goalPriority": ["goal_campus_visit", "goal_museum", "goal_meal"],
                        "dayStrategies": [
                            {
                                "dayNumber": 1,
                                "theme": "985高校",
                                "requiredGoalIds": ["goal_campus_visit"],
                                "requiredGoalCounts": {"goal_campus_visit": 1},
                                "optionalGoalIds": ["goal_meal"],
                            },
                            {
                                "dayNumber": 2,
                                "theme": "博物馆",
                                "requiredGoalIds": ["goal_museum"],
                                "requiredGoalCounts": {"goal_museum": 1},
                                "optionalGoalIds": [],
                            },
                        ],
                        "optionalExperienceBudget": 1,
                        "routePlanningPolicy": {
                            "objective": "least_generalized_cost",
                            "source": "controller_estimate",
                            "allowExperienceDetour": True,
                            "mobilityProfile": {
                                "transportMode": "transit",
                                "paceClass": "standard",
                            },
                            "detourEnvelope": {
                                "maxGeneralizedCostDelta": 15.0,
                                "maxDetourRatio": 0.15,
                            },
                        },
                        "occurrenceScheduleHints": [
                            {
                                "goalId": "goal_campus_visit",
                                "dayNumber": 1,
                                "dayPart": "morning",
                                "sequence": 1,
                                "preferredStartTime": "09:00",
                                "durationEstimate": {"min": 90, "preferred": 120, "max": 150},
                                "estimateSource": "controller_estimate",
                                "confidence": 0.95,
                            },
                            {
                                "goalId": "goal_meal",
                                "dayNumber": 1,
                                "dayPart": "noon",
                                "sequence": 2,
                                "preferredStartTime": "12:00",
                                "durationEstimate": {"min": 45, "preferred": 60, "max": 90},
                                "estimateSource": "controller_estimate",
                                "confidence": 0.9,
                            },
                            {
                                "goalId": "goal_museum",
                                "dayNumber": 2,
                                "dayPart": "morning",
                                "sequence": 1,
                                "preferredStartTime": "09:00",
                                "durationEstimate": {"min": 90, "preferred": 120, "max": 150},
                                "estimateSource": "controller_estimate",
                                "confidence": 0.95,
                            },
                        ],
                    },
                }
            if cycle == 1:
                museum_slot = next(
                    item
                    for item in observation.get("segmentRefs") or []
                    if item.get("goalId") == "goal_museum" or item.get("intentType") == "museum"
                )
                assert (observation.get("versionLineage") or {}).get("currentVersionId")
                assert museum_slot.get("segmentId")
                return {
                    "schemaVersion": "agent-decision-v3",
                    "primaryAction": "resolve_poi",
                    "actionDirective": {
                        "type": "resolve_poi",
                        "targetGoalId": "goal_museum",
                        "targetSegmentIds": [museum_slot["segmentId"]],
                        "searchIntent": "北京博物馆或美术馆",
                        "autoSelectPolicy": "dominant_safe_candidate_only",
                        "askUserPolicy": "material_tradeoff_only",
                    },
                }
            assert (observation.get("candidateState") or {}).get("pendingGroups")
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "ask_user",
                "actionDirective": {
                    "type": "ask_user",
                    "question": "更偏向西城的首都博物馆，还是东城的国家博物馆？",
                    "choiceIds": ["capital_museum", "national_museum", "manual"],
                },
            }

        def generate_initial_plan(self, _context):
            self.initial_calls += 1
            raise TimeoutError("initial DaySlot provider read timed out")

        def run_tool_loop(self, _context, _tool_registry):
            self.tool_loop_calls += 1
            raise AssertionError("must not enter nested controller/tool loop")

    provider = V3TimeoutMaterialTradeoffProvider()
    provider.generate_candidate_hints = lambda _context, pools: json.dumps(
        {
            "hints": [
                {
                    "poolId": pool["poolId"],
                    "candidateHints": (
                        ["清华大学"]
                        if pool.get("intentType") == "campus_visit"
                        else ["中国美术馆"]
                        if pool.get("intentType") == "museum"
                        else []
                    ),
                    "hintPolicy": "llm_common_knowledge_hint",
                }
                for pool in pools
            ]
        },
        ensure_ascii=False,
    )
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "V3 waiting attempt")
        resolver = MaterialTradeoffResolver(connection)
        response = AgentService(connection, provider=provider, poi_resolution_service=resolver).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观985大学两日游，然后体验北京当地博物馆。"
                    "10月1日到2日，2天，中等预算，1人，公交地铁优先，品尝北京当地特色美食"
                )
            ),
        )
        active_version_id = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
        ).fetchone()[0]
        patch_count = connection.execute("SELECT COUNT(*) FROM itinerary_patches").fetchone()[0]
        candidate = connection.execute(
            "SELECT id, status, segment_id FROM amap_poi_candidates WHERE id = 'cand_museum_tradeoff'"
        ).fetchone()
        attempt = PlanningAttemptResumeService(connection).latest_resumable_attempt(session.session_id)

    assert provider.initial_calls == 1
    assert provider.tool_loop_calls == 0
    assert provider.decision_calls == 1
    assert resolver.calls == 0
    assert response.version is None
    assert response.itinerary is None
    assert active_version_id is None
    assert patch_count == 0
    assert response.terminal_status == "candidate_refresh_required"
    assert attempt is None or attempt["resultState"] in {"waiting_for_required_intent", "candidate_refresh_required"}
    assert candidate is None


