def test_structured_density_resume_preserves_active_provider_failure_reason(monkeypatch):
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "provider failure")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "刷新候选",
            "active",
            agent_request_json={
                "selectedAgentChoice": {
                    "action": "refresh_density_candidates",
                    "normalizedAction": "refresh_density_candidates",
                },
                "fallbackChoiceExecutionClaim": {"id": "execution_provider_failure"},
                "structuredPlanningChoiceResume": True,
                "portfolioDensityContinuation": {
                    "checkpointFingerprint": "checkpoint",
                    "planningSelectionRootTurnId": "turn_root",
                    "rootPortfolioId": "portfolio_root",
                    "requestContractFingerprint": "f" * 64,
                    "expectedBaseVersionId": "version_partial",
                    "focusBriefId": "brief_target",
                    "briefId": "brief_target",
                    "poolId": "pool_target",
                    "planningSlotId": "slot_target",
                    "dayNumber": 2,
                },
            },
        )
        assistant_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "地图服务暂时不可用",
            "active",
        )
        captured = {}
        monkeypatch.setattr(
            service,
            "_finish_fallback_choice_execution",
            lambda execution_id, status, **kwargs: captured.update(
                {"executionId": execution_id, "status": status, **kwargs}
            ),
        )
        event = AgentPlanningEventResponse(
            type="ground_candidates",
            label="补充候选",
            status="failed",
            metadata={
                "grounding": {
                    "providerState": "provider_failure",
                    "failureReason": "AMap unavailable",
                }
            },
            timestamp=datetime.now(timezone.utc).isoformat(),
        )
        response = AgentMessageResponse(
            userTurn=service._turn_response(user_turn_id),
            assistantTurn=service._turn_response(assistant_turn_id),
            planningSteps=[event],
            toolEvents=[event],
            terminalStatus="needs_confirmation",
        )

        service._complete_controller_choice_execution(
            session.session_id,
            user_turn_id,
            response,
        )

    assert captured["executionId"] == "execution_provider_failure"
    assert captured["status"] == "failed_retryable"
    assert captured["outcome"]["reason"] == "provider_failure"
    assert captured["outcome"]["providerFailure"] == {
        "providerState": "provider_failure",
        "failureReason": "AMap unavailable",
    }


@pytest.mark.parametrize(
    ("proposal_delta", "reason_code"),
    [
        (1, None),
        (
            0,
            "simple_direction_campus_candidate_page_rejected_frontier_remaining",
        ),
    ],
)
def test_simple_direction_finalizer_rejects_unpersisted_authorization_fields(
    monkeypatch,
    proposal_delta,
    reason_code,
):
    """Client-shaped/internal booleans cannot replace the persisted evidence chain."""

    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "direction choice finalizer")
        service = AgentService(connection, provider=FakeProvider({}))
        selected_option = {
            "id": "choice_continue_old",
            "choiceId": "choice_continue_old",
            "action": "continue_plan_expansion",
            "kind": "simple_direction_more_plans",
            "scopeKind": "comparison",
            "sourceAssistantTurnId": "turn_source",
            "planningSelectionRootTurnId": "turn_root",
            "rootPortfolioId": "portfolio_root",
            "requestContractFingerprint": "f" * 64,
        }
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "继续探索其他方向",
            "active",
            agent_request_json={
                "selectedAgentChoice": {
                    "action": "continue_plan_expansion",
                    "choiceId": selected_option["id"],
                    "sourceAssistantTurnId": "turn_source",
                    "option": selected_option,
                },
                "fallbackChoiceExecutionClaim": {"id": "choice_exec_direction"},
                "_simpleDirectionGenerationAuthorized": True,
            },
        )
        assistant_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "已完成本批候选检查",
            "active",
            agent_response_json={
                "mode": "simple_open_direction_proposal",
                "workflowMode": "simple_direction_v1",
                "planningSelectionRootTurnId": "turn_root",
                "rootPortfolioId": "portfolio_root",
                "proposalDelta": proposal_delta,
                "frontierAttemptConsumed": True,
                "reasonCode": reason_code,
                "versionDelta": 0,
                "patchDelta": 0,
                "routeWriteDelta": 0,
                "choiceOptions": [
                    {
                        "id": "choice_continue_new",
                        "action": "continue_plan_expansion",
                        "kind": "simple_direction_more_plans",
                    }
                ],
            },
        )
        captured: dict = {}
        consumed: list[dict] = []
        monkeypatch.setattr(
            service,
            "_finish_fallback_choice_execution",
            lambda execution_id, status, **kwargs: captured.update(
                {"executionId": execution_id, "status": status, **kwargs}
            ),
        )
        monkeypatch.setattr(
            service,
            "_consume_selected_agent_choice",
            lambda _session_id, choice: consumed.append(copy.deepcopy(choice)),
        )
        monkeypatch.setattr(service, "_finalize_planning_material_choice", lambda *_args, **_kwargs: None)
        response = AgentMessageResponse(
            userTurn=service._turn_response(user_turn_id),
            assistantTurn=service._turn_response(assistant_turn_id),
            terminalStatus="needs_confirmation",
        )

        service._complete_controller_choice_execution(
            session.session_id,
            user_turn_id,
            response,
        )

    assert captured["executionId"] == "choice_exec_direction"
    assert captured["status"] == "failed_terminal"
    assert captured["outcome"]["reason"] == "simple_direction_execution_missing"
    assert captured["outcome"]["boundedAttemptConsumed"] is True
    assert consumed == [
        {
            "action": "continue_plan_expansion",
            "choiceId": "choice_continue_old",
            "sourceAssistantTurnId": "turn_source",
            "option": selected_option,
        }
    ]


def test_candidate_inventory_exhaustion_is_actionable_and_zero_write():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "candidate inventory exhausted")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "继续生成其他方案",
            "active",
        )
        assistant_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "处理中",
            "active",
        )
        session_before = service._session(session.session_id)
        before = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

        response = service._failed_staged_pipeline_response(
            session.session_id,
            user_turn_id,
            assistant_turn_id,
            "继续生成其他方案",
            {"portfolioDensityContinuation": {"visibleProposalIds": ["proposal_1", "proposal_2", "proposal_3"]}},
            session_before,
            [],
            "creative_frontier_semantic_exhausted:candidate_inventory_exhausted",
            AgentVerifierReport(passed=False),
        )
        after = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert response.terminal_status == "portfolio_exhausted"
    assert response.assistant_turn.status == "active"
    assert response.version is None
    assert response.itinerary is None
    assert response.assistant_turn.content == (
        "当前仅找到 3 个可验证方向；当前已生成全部可验证方向。你可以刷新候选、放宽偏好或指定新的旅行主题。"
    )
    assert [item["label"] for item in response.assistant_turn.choice_options] == [
        "刷新候选",
        "放宽偏好",
        "指定旅行主题",
    ]
    assert after == before == (0, 0, 0)


def test_simple_direction_qualification_exhaustion_is_actionable_and_zero_write():
    from src.services.simple_open_direction_service import SimpleOpenDirectionService

    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("示例城", "simple direction frontier exhausted")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(session.session_id, "user", "继续探索其他方向", "active")
        assistant_turn_id = service._insert_turn(session.session_id, "assistant", "处理中", "active")
        request_fingerprint = "b" * 64
        root = SimpleOpenDirectionService(connection).ensure_root(
            session_id=session.session_id,
            planning_root_id=user_turn_id,
            source_assistant_turn_id=assistant_turn_id,
            expected_base_version_id=None,
            source_observation_fingerprint="a" * 64,
            request_contract_fingerprint=request_fingerprint,
            request_contract={},
            locality="示例城",
            max_pages_per_query=3,
        )
        session_before = service._session(session.session_id)
        before = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

        response = service._failed_staged_pipeline_response(
            session.session_id,
            user_turn_id,
            assistant_turn_id,
            "继续探索其他方向",
            {},
            session_before,
            [],
            "simple_direction_qualification_frontier_exhausted",
            AgentVerifierReport(passed=False),
        )
        after = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert response.terminal_status == "simple_direction_frontier_exhausted"
    assert response.assistant_turn.status == "active"
    assert "高校候选已全部领取" in response.assistant_turn.content
    assert [item["label"] for item in response.assistant_turn.choice_options] == ["允许复用高校，只变化其他体验"]
    option = response.assistant_turn.choice_options[0]
    assert option["scopeKind"] == "comparison"
    assert option["sourceAssistantTurnId"] == assistant_turn_id
    assert option["planningSelectionRootTurnId"] == user_turn_id
    assert option["rootPortfolioId"] == root["id"]
    assert option["requestContractFingerprint"] == request_fingerprint
    assert after == before == (0, 0, 0)


def test_cardinality_failure_explains_direct_retry_and_stays_zero_write():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "cardinality retry guidance")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(
            session.session_id,
            "user",
            "只安排一晚夜游",
            "active",
        )
        assistant_turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "处理中",
            "active",
        )
        session_before = service._session(session.session_id)
        before = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

        response = service._failed_staged_pipeline_response(
            session.session_id,
            user_turn_id,
            assistant_turn_id,
            "只安排一晚夜游",
            {},
            session_before,
            [],
            "goal_occurrence_maximum_cardinality_exceeded:goal_night_view:2/1",
            AgentVerifierReport(passed=False),
        )
        after = (
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_versions WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute(
                "SELECT COUNT(*) FROM itinerary_patches WHERE session_id = ?",
                (session.session_id,),
            ).fetchone()[0],
            connection.execute("SELECT COUNT(*) FROM route_options").fetchone()[0],
        )

    assert response.terminal_status == "failed"
    assert response.assistant_turn.status == "failed"
    assert response.version is None
    assert response.itinerary is None
    assert response.assistant_turn.content == (
        "规划中的目标次数超过了你刚确认的上限，本轮已停止写入。"
        "请直接重试本轮，系统会按已确认次数重新生成；无需刷新地点候选。"
    )
    assert after == before == (0, 0, 0)


def test_scoped_density_manual_input_becomes_exact_amap_search_without_controller() -> None:
    clear_database()
    with open_db() as connection:
        session_model = ConversationService(connection).create_session("北京", "manual density")
        service = AgentService(connection, provider=FakeProvider({}))
        user_turn_id = service._insert_turn(
            session_model.session_id,
            "user",
            "北京动物园",
            "active",
        )
        user_turn = service._turn_response(user_turn_id)
        session = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?",
            (session_model.session_id,),
        ).fetchone()
        request_context = {
            "skipPostObservationController": True,
            "structuredPlanningChoiceResume": True,
            "portfolioDensityContinuation": {
                "briefId": "brief_target",
                "poolId": "pool_walk",
                "planningSlotId": "slot_day_2_walk",
                "dayNumber": 2,
                "intentType": "area_walk",
                "expectedBaseVersionId": "version_partial",
            },
        }
        selected_choice = {
            "action": "manual_continuation",
            "normalizedAction": "search_density_manual_candidates",
            "manualValue": "北京动物园",
            "option": {
                "id": "manual_slot_choice",
                "kind": "custom_input",
                "action": "manual_continuation",
                "briefId": "brief_target",
                "poolId": "pool_walk",
                "planningSlotId": "slot_day_2_walk",
                "dayNumber": 2,
                "intentType": "area_walk",
            },
        }

        result = service._dispatch_selected_agent_choice(
            session_model.session_id,
            user_turn_id,
            "北京动物园",
            user_turn,
            session,
            request_context,
            selected_choice,
        )

    assert result is None
    assert request_context["skipPostObservationController"] is True
    assert request_context["forceCandidateRefresh"] is True
    assert request_context["structuredRetry"]["retryMode"] == "manual_exact_search"
    assert request_context["structuredRetry"]["planningSlotId"] == "slot_day_2_walk"
    assert request_context["manualCandidateHints"] == [
        {
            "briefId": "brief_target",
            "poolId": "pool_walk",
            "planningSlotId": "slot_day_2_walk",
            "dayNumber": 2,
            "intentType": "area_walk",
            "candidateHints": ["北京动物园"],
            "hintPolicy": "user_explicit_hint",
            "manualExactSlotSearch": True,
            "entityBindingMode": "exact_entity",
            "exactEntity": "北京动物园",
            "rawNeed": "北京动物园",
        }
    ]


