def test_density_manual_search_rebinds_only_exact_target_pool() -> None:
    initial_plan = AgentInitialPlanOutput.model_validate(
        {
            "reply": "",
            "mode": "day_slots",
            "daySlots": [
                {
                    "slotId": "slot_day_2_walk",
                    "dayNumber": 2,
                    "timeWindow": "14:00-16:00",
                    "startTime": "14:00",
                    "durationMinutes": 120,
                    "kind": "activity",
                    "rawNeed": "街区漫步",
                    "routeAnchor": True,
                },
                {
                    "slotId": "slot_day_1_walk",
                    "dayNumber": 1,
                    "timeWindow": "14:00-18:00",
                    "startTime": "14:00",
                    "durationMinutes": 120,
                    "kind": "activity",
                    "rawNeed": "艺术街区",
                    "routeAnchor": True,
                },
            ],
            "intentPools": [
                {
                    "poolId": "pool_walk",
                    "briefId": "brief_target",
                    "rawNeed": "街区漫步",
                    "city": "北京",
                    "intentType": "area_walk",
                    "targetCount": 1,
                    "assignToSlots": ["slot_day_2_walk"],
                    "candidateHints": ["天坛公园"],
                    "hintPolicy": "llm_common_knowledge_hint",
                },
                {
                    "poolId": "pool_art",
                    "briefId": "brief_target",
                    "rawNeed": "艺术街区",
                    "city": "北京",
                    "intentType": "area_walk",
                    "targetCount": 1,
                    "assignToSlots": ["slot_day_1_walk"],
                    "candidateHints": ["798艺术区"],
                    "hintPolicy": "llm_common_knowledge_hint",
                },
            ],
        }
    )
    with open_db() as connection:
        service = AgentService(connection)
        manual_hints = service._manual_candidate_hints_from_context(
            {
                "manualCandidateHints": [
                    {
                        "briefId": "brief_target",
                        "poolId": "pool_walk",
                        "planningSlotId": "slot_day_2_walk",
                        "dayNumber": 2,
                        "intentType": "area_walk",
                        "candidateHints": ["北京动物园"],
                        "manualExactSlotSearch": True,
                        "entityBindingMode": "exact_entity",
                        "exactEntity": "北京动物园",
                        "rawNeed": "北京动物园",
                    }
                ]
            }
        )
        hints_by_pool = service._manual_candidate_hints_by_pool(initial_plan, manual_hints)
        rebound, _, _ = service._apply_candidate_hints_to_initial_plan(
            initial_plan,
            hints_by_pool,
            prefer_new=True,
        )

    target, untouched = rebound.intent_pools
    assert target.candidate_hints == ["北京动物园"]
    assert target.raw_need == "北京动物园"
    assert target.entity_binding_mode == "exact_entity"
    assert target.exact_entity == "北京动物园"
    assert target.assign_to_slots == ["slot_day_2_walk"]
    assert untouched.candidate_hints == ["798艺术区"]
    assert untouched.raw_need == "艺术街区"
    assert untouched.entity_binding_mode == "category"


