def test_initial_staged_pipeline_missing_intent_pools_without_hints_fails_closed(monkeypatch):
    clear_database()

    def unexpected_map_search(*_args, **_kwargs):
        raise AssertionError("missing semantic candidate hints must fail closed before AMap search")

    monkeypatch.setattr(MapPoiService, "search", unexpected_map_search)
    payload = two_day_initial_day_slot_output()
    payload.pop("intentPools")
    provider = StagedInitialProvider(payload)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        active = connection.execute(
            "SELECT active_version_id FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        patch_rows = connection.execute(
            "SELECT validation_status FROM itinerary_patches ORDER BY created_at"
        ).fetchall()

    provider_events = [event for event in response.planning_steps if event.type == "initial_day_slot_provider"]
    decompose_event = next(event for event in response.planning_steps if event.type == "decompose_intent_pools")
    collect_event = next(event for event in response.planning_steps if event.type == "collect_candidates")
    action_outcome = next(event for event in response.planning_steps if event.type == "agent_action_outcome")

    assert response.assistant_turn.status == "active", collect_event.metadata.get("resultPreview")
    assert response.terminal_status == "needs_confirmation"
    assert response.version is None
    assert response.itinerary is None
    assert active["active_version_id"] is None
    assert patch_rows == []
    assert not any(event.type == "candidate_hints_provider" for event in response.planning_steps)
    assert provider_events
    assert provider_events[0].status == "completed"
    assert provider_events[0].metadata["resultPreview"]["fallbackUsed"] is False
    assert provider_events[0].metadata["resultPreview"]["fallbackReason"] == "intent_pools_missing_server_will_complete"
    assert decompose_event.metadata["resultPreview"]["intentPoolCount"] == 2
    assert decompose_event.metadata["resultPreview"]["candidateHintsAvailable"] is False
    assert decompose_event.metadata["resultPreview"]["semanticCandidateHintNeeded"] is True
    assert collect_event.status == "fallback"
    assert collect_event.metadata["resultPreview"]["resultState"] == "semantic_candidate_hint_missing"
    assert action_outcome.status == "partial", [
        {
            "status": event.status,
            "cycleIndex": event.metadata.get("cycleIndex"),
            "preview": event.metadata.get("resultPreview"),
        }
        for event in response.planning_steps
        if event.type == "agent_action_outcome"
    ]
    assert action_outcome.metadata["resultPreview"]["status"] == "partial"
    assert action_outcome.metadata["resultPreview"]["resultVersionId"] is None
    assert action_outcome.metadata["resultPreview"]["patchIds"] == []


def test_staged_pipeline_user_copy_translates_internal_warning_and_omits_version_debug_id():
    with open_db() as connection:
        service = AgentService(connection, provider=FakeProvider("{}"))
        warnings = service._pipeline_warnings(
            {},
            AgentVerifierReport(passed=True),
            [
                "CANDIDATE_HINT_RETRY_USED",
                "RUNTIME_EVAL_MOCK_INITIAL_PLAN",
                "MEAL_GROUNDING_POLICY_APPLIED",
                "result_state: partial_success",
                "AMap area POI resolve failed: {'code': 'amap_budget_exceeded', 'debug': {'processId': 123}}",
                "required meal grounding incomplete in partial editable draft: 1 meal segment(s)",
                "initial_day_slot_plan_error: The read operation timed out",
                "路线工具失败，已保留行程草案：token=secret-value",
                "Authorization: Bearer bearer-secret",
                "secret: colon-secret",
                "day day_330d582ba769 has only 1 visit segment; itinerary may be too thin",
                "transport preference mismatch for segments: seg_5788b6f0c0ac, seg_e7683c221f2d",
                "Rejected Example: type blacklist",
            ],
        )
        reply = service._staged_pipeline_reply(
            "已生成。",
            "ver_internal_123",
            warnings,
            {"state": "partial_success"},
        )

    assert warnings == [
        "部分地点使用了备用搜索词补充候选，结果仍按真实地图匹配与路线约束筛选。",
        "本轮高德 POI 调用预算已用尽，未完成的地点已保留为待补全。",
        "仍有餐饮地点需要选择具体地图 POI，当前草稿可继续编辑。",
        "初始规划 provider 确认超时，已使用确定性安全执行器生成可编辑时间轴。",
        "路线工具失败，已保留行程草案：token=***",
        "Authorization: Bearer ***",
        "secret: ***",
        "部分日期仅有 1 个游览安排，行程较松，可继续补充或调整。",
        "部分行程段的交通方式与公交地铁优先偏好不完全一致，建议继续调整。",
    ]
    assert "CANDIDATE_HINT_RETRY_USED" not in reply
    assert "result_state" not in reply
    assert "ver_internal_123" not in reply
    assert "调试ID" not in reply
    assert "备用搜索词" in reply
    assert "The read operation timed out" not in reply
    assert "secret-value" not in reply
    assert "bearer-secret" not in reply
    assert "colon-secret" not in reply
    assert "day_330d582ba769" not in reply
    assert "seg_5788b6f0c0ac" not in reply
    assert all(warning in reply for warning in warnings)


