def test_external_fact_decision_uses_read_only_executor_and_never_enters_tool_loop(monkeypatch):
    clear_database()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    executed_tools: list[str] = []

    def fake_execute(registry, tool_call_id, tool_name, arguments):
        executed_tools.append(tool_name)
        now = datetime.now(timezone.utc).isoformat()
        registry.events.append(
            {
                "id": tool_call_id,
                "toolName": tool_name,
                "type": "tool",
                "label": tool_name,
                "status": "succeeded",
                "providerName": "test-read-only-provider",
                "fallbackUsed": False,
                "failureReason": None,
                "detail": "test external fact result",
                "outputSummary": "test external fact result",
                "timestamp": now,
                "startedAt": now,
                "finishedAt": now,
                "metadata": {"resultPreview": {"arguments": arguments}},
            }
        )
        return {"ok": True, "toolName": tool_name, "providerName": "test-read-only-provider"}

    class FailIfToolLoopProvider(IntentContractProviderMixin):
        def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
            observation = context.get("observation") or {}
            if int(observation.get("cycleIndex") or 0) > 0:
                return {
                    "schemaVersion": "agent-decision-v3",
                    "primaryAction": "finish",
                    "actionDirective": {"type": "finish", "assistantReply": "外部事实已核验。"},
                }
            segment_ids = [
                str(item.get("segmentId"))
                for item in observation.get("segmentRefs") or []
                if isinstance(item, dict) and item.get("segmentId")
            ]
            return {
                "schemaVersion": "agent-decision-v3",
                "primaryAction": "verify_external_facts",
                "actionDirective": {
                    "type": "verify_external_facts",
                    "factTypes": ["reservation", "risk"],
                    "segmentIds": segment_ids,
                },
            }

        def run_tool_loop(self, _context, _registry):
            raise AssertionError("verify_external_facts must not enter the general tool loop")

    monkeypatch.setattr(TravelToolRegistry, "execute", fake_execute)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        created = AgentService(
            connection,
            provider=StagedInitialProvider(two_day_initial_day_slot_output()),
            poi_resolution_service=FakePoiResolver({}),
        ).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        verifier_service = AgentService(connection, provider=FailIfToolLoopProvider())
        fact_context = verifier_service._build_request_context(
            verifier_service._session(session.session_id),
            "查一下这几个学校国庆期间的预约和风险",
            AgentMessageRequest(content="查一下这几个学校国庆期间的预约和风险"),
        )
        assert fact_context["agentObservation"]["invariantErrors"] == []
        verified = verifier_service.send_message(
            session.session_id,
            AgentMessageRequest(content="查一下这几个学校国庆期间的预约和风险"),
        )

    assert created.version is not None
    assert verified.assistant_turn.status == "active"
    assert verified.version is not None
    assert verified.version.id == created.version.id
    assert executed_tools == ["ticket_lookup"]
    assert "patch_itinerary" not in executed_tools
    assert any(event.type == "agent_action_outcome" for event in verified.planning_steps)
    assert any(event.type == "agent_stop" for event in verified.planning_steps)


def test_initial_staged_pipeline_persists_skeleton_draft_for_unknown_city_without_fake_amap():
    clear_database()

    def fail_amap_search(*_args, **_kwargs):
        raise RuntimeError("AMap unavailable")

    intent_only = {
        "reply": "已解析用户需求。",
        "tripIntent": {"city": "测试城", "budget": "中等", "partySize": 1, "transportPreference": "公交地铁"},
        "resolvedTripDates": {
            "startDate": "2026-10-01",
            "endDate": "2026-10-02",
            "dates": ["2026-10-01", "2026-10-02"],
        },
    }
    provider = StagedInitialSequenceProvider([intent_only])
    with open_db() as connection:
        original_search = MapPoiService.search
        MapPoiService.search = fail_amap_search
        session = ConversationService(connection).create_session("测试城", "测试城会话")
        try:
            response = AgentService(
                connection, provider=provider, poi_resolution_service=FakePoiResolver({})
            ).send_message(
                session.session_id,
                AgentMessageRequest(content="10月1日到2日，2天，中等预算，1人，公交地铁"),
            )
            active = connection.execute(
                "SELECT active_version_id FROM conversation_sessions WHERE id = ?", (session.session_id,)
            ).fetchone()
            poi_rows = connection.execute("SELECT name, source, amap_id FROM pois").fetchall()
        finally:
            MapPoiService.search = original_search

    assert response.assistant_turn.status == "active"
    assert response.version is not None
    assert active["active_version_id"] == response.version.id
    assert poi_rows
    assert all(row["source"] == "agent-text-timeline" for row in poi_rows)
    assert all(row["amap_id"] is None for row in poi_rows)
    assert any(
        "暂未" in warning or "候选" in warning or "地点" in warning or "限流" in warning
        for warning in response.warnings
    )
    assert not any("deterministic_fallback_full_itinerary" in warning for warning in response.warnings)
    assert not any("核心景点" in row["name"] or "夜景地标" in row["name"] for row in poi_rows)


