def test_initial_staged_pipeline_basic_verifier_reads_version_snapshot(monkeypatch):
    clear_database()
    monkeypatch.setattr(MapPoiService, "search", fake_amap_search_with_keyword_candidate)
    provider = StagedInitialProvider(two_day_initial_day_slot_output())
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        response = AgentService(connection, provider=provider, poi_resolution_service=FakePoiResolver({})).send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观北京高校两日游。10月1日到2日，2天，中等预算，1人，公交地铁优先"
                )
            ),
        )
        patch_row = connection.execute(
            "SELECT id, result_version_id FROM itinerary_patches WHERE source_turn_id = ? AND validation_status = 'accepted'",
            (response.assistant_turn.id,),
        ).fetchone()
        version_row = connection.execute(
            "SELECT snapshot_json FROM itinerary_versions WHERE id = ?",
            (patch_row["result_version_id"],),
        ).fetchone()
        snapshot = json.loads(version_row["snapshot_json"])
        snapshot["days"] = []
        connection.execute(
            "UPDATE itinerary_versions SET snapshot_json = ? WHERE id = ?",
            (json.dumps(snapshot, ensure_ascii=False), patch_row["result_version_id"]),
        )
        verifier_report = AgentVerifierService(connection).verify_agent_write(
            session.session_id,
            session.active_plan_id,
            patch_row["result_version_id"],
            patch_row["id"],
            planning_context=provider.contexts[0],
        )

    basic_check = next(check for check in verifier_report.checks if check["name"] == "basic_itinerary_verifier")
    assert verifier_report.passed is False
    assert basic_check["source"] == "version_snapshot"
    assert "itinerary snapshot must contain at least one day" in verifier_report.hard_failures
    assert "itinerary snapshot must contain at least one segment" in verifier_report.hard_failures


