    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "北京会话")
        connection.execute(
            """
            INSERT INTO amap_poi_candidates (
                id, session_id, turn_id, query, city, category, status,
                candidates_json, selected_amap_id, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "cand_pending",
                session.session_id,
                "turn_previous",
                "旧候选",
                "北京",
                "scenic",
                "pending",
                "[]",
                None,
                "2026-06-10T00:00:00Z",
            ),
        )
        connection.commit()
        first_pending = connection.execute("SELECT id, status FROM amap_poi_candidates").fetchone()

        response = AgentService(
            connection,
            provider=FakeProvider(single_poi_with_extra_resolution_requests_output()),
            poi_resolution_service=FakePoiResolver({"故宫博物院": poi_fixture("B000PALACE", "故宫博物院")}),
        ).send_message(session.session_id, AgentMessageRequest(content="只安排故宫博物院"))
        pending_rows = connection.execute("SELECT id, status FROM amap_poi_candidates ORDER BY created_at").fetchall()

    assert first_pending["status"] == "pending"
    assert response.pending_poi_candidates == []
    assert [(row["id"], row["status"]) for row in pending_rows] == [("cand_pending", "expired")]


