def fake_amap_search_with_keyword_candidate(
    _self,
    city,
    keyword,
    category="all",
    limit=10,
    provider_types=None,
    **_kwargs,
):
    del limit, _kwargs
    keyword_text = str(keyword)
    cleaned = re.sub(r"^(北京|北京市)\s+", "", keyword_text)
    cleaned = re.sub(r"\s+(地标|景点|大学|高等院校|校区)$", "", cleaned).strip() or keyword_text
    generic_campus_keywords = {"大学", "学院", "高等院校"}
    if category == "campus" or any(marker in keyword_text for marker in ("大学", "学院", "高等院校", "校区", "高校")):
        if cleaned in generic_campus_keywords or "高校" in keyword_text:
            cleaned = "北京测试大学" if "高等院校" not in keyword_text else "北京样例学院"
        poi_type = "科教文化服务;学校;高等院校"
    elif category == "food":
        poi_type = f"餐饮服务;中餐厅;{provider_types}" if provider_types else "餐饮服务;中餐厅"
    elif cleaned in {"奥林匹克塔", "中信大厦"}:
        poi_type = "风景名胜;观景点"
    elif any(marker in keyword_text for marker in ("夜景", "观景", "夜游", "灯光")):
        cleaned = "北京测试观景台"
        poi_type = "风景名胜;观景点"
    else:
        poi_type = (
            "科教文化服务;学校;高等院校"
            if any(marker in cleaned for marker in ("大学", "学院", "校区"))
            else "风景名胜"
        )
    return MapPoiSearchResponse(
        city=city,
        keyword=keyword,
        category=category,
        providerName="fake-amap",
        queriedAt=datetime.now(timezone.utc),
        pois=[
            MapPoiResponse(
                id=f"amap_{abs(hash(cleaned))}",
                name=cleaned,
                type=poi_type,
                city=city,
                district="测试区",
                address=f"{cleaned} 地址",
                longitude=116.397026 + (0.01 if "样例" in cleaned else 0),
                latitude=39.918058,
                category=category,
                source=AMAP_PLACE_SOURCE,
                sourceNote="高德 WebService POI 搜索",
                confidence=0.93,
                providerTypeCode="050111" if provider_types else None,
                photos=[],
            )
        ],
    )


def fake_amap_search_nearby_route_compatible(
    _self,
    city,
    longitude,
    latitude,
    keyword,
    category="all",
    radius=1500,
    limit=12,
    bypass_cache=False,
    query_scope_fingerprint=None,
    provider_types=None,
    **_kwargs,
):
    del radius, limit, bypass_cache, query_scope_fingerprint, provider_types, _kwargs
    normalized_need = re.sub(r"^(北京|北京市)\s*", "", str(keyword)).strip()
    is_food = category == "food" or bool(re.search(r"(餐|美食|午饭|午餐|小吃)", str(keyword)))
    is_scenic = category == "scenic" or bool(re.search(r"(公园|夜景|观景|夜游|灯光)", str(keyword)))
    if is_food:
        poi_id_prefix = "amap_nearby_meal"
        poi_name = f"北京本地菜餐厅·{normalized_need or '北京菜'}(路线附近店)"
        poi_type = "餐饮服务;中餐厅;北京菜"
        poi_category = "food"
    elif is_scenic:
        poi_id_prefix = "amap_nearby_scenic"
        poi_name = f"校园附近公园·{normalized_need or '公共公园'}"
        poi_type = "风景名胜;公园广场;公园"
        poi_category = "scenic"
    else:
        poi_name = f"路线附近地点·{normalized_need or '候选地点'}"
        poi_type = "风景名胜;其它"
        poi_category = category
    identity_material = json.dumps(
        [str(keyword), poi_name, round(float(longitude), 6), round(float(latitude), 6)],
        ensure_ascii=False,
        separators=(",", ":"),
    )
    amap_id = f"B{hashlib.sha256(identity_material.encode('utf-8')).hexdigest().upper()[:12]}"
    return MapPoiSearchResponse(
        city=city,
        keyword=keyword,
        category=category,
        providerName="fake-amap",
        queriedAt=datetime.now(timezone.utc),
        pois=[
            MapPoiResponse(
                id=amap_id,
                name=poi_name,
                type=poi_type,
                city=city,
                district="测试区",
                address="相邻路线锚点附近",
                longitude=float(longitude) + 0.0002,
                latitude=float(latitude) + 0.0002,
                category=poi_category,
                source=AMAP_PLACE_SOURCE,
                sourceNote="高德 WebService POI 周边搜索",
                confidence=0.95,
                photos=[],
            )
        ],
    )


class ScriptedDeepSeekProvider(IntentContractProviderMixin, DeepSeekAgentProvider):
    def __init__(self, responses):
        super().__init__(api_key="test-key", model="deepseek-test", timeout_seconds=7)
        self.responses = list(responses)
        self.calls = 0
        self.payloads: list[dict] = []

    def _post_json(self, payload: dict) -> dict:
        self.calls += 1
        self.payloads.append(payload)
