class PatchThenRejectedPatchProvider(ControllerComplexToolLoopProvider):
    def run_tool_loop(self, _context: dict, tool_registry) -> AgentToolLoopResult:
        tool_registry.execute(
            "call_patch_success",
            "patch_itinerary",
            {"operations": [replace_itinerary_operation()]},
        )
        tool_registry.execute(
            "call_patch_stale",
            "patch_itinerary",
            {"operations": [{"op": "remove_segment", "segmentId": "missing_segment"}]},
        )
        return AgentToolLoopResult(reply="已写入北京 1 日行程。", tool_events=tool_registry.events)


