class ConcurrentOtherTurnPatchProvider(ControllerComplexToolLoopProvider):
    def __init__(self):
        self.calls = 0

    def run_tool_loop(self, _context: dict, tool_registry) -> AgentToolLoopResult:
        self.calls += 1
        if self.calls == 1:
            result = tool_registry.execute(
                "call_patch_other",
                "patch_itinerary",
                {"operations": [replace_itinerary_operation()]},
            )
            version_id = result["activeVersionId"]
            tool_registry.db.execute(
                "UPDATE itinerary_patches SET source_turn_id = 'other_turn' WHERE result_version_id = ?",
                (version_id,),
            )
            tool_registry.db.execute(
                "UPDATE itinerary_versions SET source_turn_id = 'other_turn' WHERE id = ?",
                (version_id,),
            )
            return AgentToolLoopResult(reply="其他请求写入了时间轴，但本轮没有写。", tool_events=tool_registry.events)
        return AgentToolLoopResult(reply="重试后仍未写入本轮 patch。", tool_events=tool_registry.events)


