class FakeToolPoiResolutionService:
    def __init__(self, db: sqlite3.Connection, amap_id: str = "B000FOOD", name: str = "老胡同餐厅"):
        self.db = db
        self.amap_id = amap_id
        self.name = name

    def resolve(self, payload, commit: bool = True) -> MapPoiResolveResponse:
        poi = poi_fixture(self.amap_id, self.name)
        self.db.execute(
            """
            INSERT INTO amap_poi_candidates (
                id, session_id, turn_id, query, city, category, status,
                candidates_json, selected_amap_id, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "cand_tool_pending",
                payload.session_id,
                payload.turn_id,
                payload.queries[0].name,
                payload.city,
                payload.queries[0].category,
                "pending",
                json.dumps([poi.model_dump(by_alias=True)], ensure_ascii=False),
                None,
                "2026-06-17T00:00:00Z",
            ),
        )
        if commit:
            self.db.commit()
        return MapPoiResolveResponse(
            resolved=[],
            pending=[
                MapPoiPendingItemResponse(
                    candidateRecordId="cand_tool_pending",
                    query=payload.queries[0].name,
                    reason="multiple_candidates",
                    candidates=[poi],
                )
            ],
        )


class FakePoiResolver:
    def __init__(self, pois_by_query: dict[str, MapPoiResponse]):
        self.pois_by_query = pois_by_query
        self.seen_queries: list[str] = []

    def resolve(self, payload) -> MapPoiResolveResponse:
        self.seen_queries = [query.name for query in payload.queries]
        return MapPoiResolveResponse(
            resolved=[
                MapPoiResolvedItemResponse(query=query.name, status="accepted", poi=self.pois_by_query[query.name])
                for query in payload.queries
                if query.name in self.pois_by_query
            ],
            pending=[],
        )


