def test_agent_request_model_is_applied_before_controller_decision():
    clear_database()

    class ModelCapturingProvider(ControllerAskUserProvider):
        def __init__(self):
            super().__init__()
            self.model = "deepseek-chat"
            self.seen_models: list[str] = []

        def decide_autonomy(self, context, *, timeout_seconds, repair_feedback=""):
            self.seen_models.append(self.model)
            return super().decide_autonomy(
                context,
                timeout_seconds=timeout_seconds,
                repair_feedback=repair_feedback,
            )

    provider = ModelCapturingProvider()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "legacy model alias")
        AgentService(connection, provider=provider).send_message(
            session.session_id,
            AgentMessageRequest(
                content=(
                    "今年国庆参观北京高校两日游，每晚都看北京夜景。"
                    "10月1日到2日，中等预算，1人，公交地铁优先。"
                    "每天午餐想体验当地特色美食。"
                ),
                agentModel="deepseek-chat",
            ),
        )

    assert provider.seen_models
    assert set(provider.seen_models) == {"deepseek-v4-flash"}


def test_deepseek_filters_tools_from_agent_plan_allowed_tools():
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    tools = [
        {"type": "function", "function": {"name": "read_itinerary"}},
        {"type": "function", "function": {"name": "generate_plan_comparison"}},
        {"type": "function", "function": {"name": "patch_itinerary"}},
        {"type": "function", "function": {"name": "web_search"}},
    ]

    filtered = provider._tools_for_agent_plan(
        tools,
        {"agentPlan": {"allowedTools": ["read_itinerary", "generate_plan_comparison"]}},
        [],
    )

    assert payload_tool_names({"tools": filtered}) == ["read_itinerary", "generate_plan_comparison"]


def test_deepseek_keeps_required_patch_tool_when_write_contract_requires_it():
    provider = DeepSeekAgentProvider(api_key="test-key", model="deepseek-test", timeout_seconds=7)
    tools = [
        {"type": "function", "function": {"name": "read_itinerary"}},
        {"type": "function", "function": {"name": "patch_itinerary"}},
        {"type": "function", "function": {"name": "web_search"}},
    ]

    filtered = provider._tools_for_agent_plan(
        tools,
        {
            "agentPlan": {"allowedTools": ["read_itinerary"]},
            "timelineWriteContract": {"required": True},
        },
        [],
    )

    assert payload_tool_names({"tools": filtered}) == ["read_itinerary", "patch_itinerary"]


