def _install_strict_v3_controller_fixture_adapter(*provider_classes: type) -> None:
    """Keep legacy data fixtures behind the current three-field Controller contract.

    The payload-generating methods on these test doubles still exercise their
    existing executor fixtures.  Only the model-facing decision envelope is
    projected here; server-owned policy/tool/risk metadata must not be emitted
    by a recorded Controller.
    """

    for provider_class in provider_classes:
        original = provider_class.__dict__.get("decide_autonomy")
        if original is None:
            continue

        def strict_decide(self, *args, __original=original, **kwargs):
            payload = __original(self, *args, **kwargs)
            if not isinstance(payload, dict) or payload.get("schemaVersion") != "agent-decision-v3":
                return payload
            return {
                "schemaVersion": payload["schemaVersion"],
                "primaryAction": payload["primaryAction"],
                "actionDirective": payload["actionDirective"],
            }

        provider_class.decide_autonomy = strict_decide


_install_strict_v3_controller_fixture_adapter(
    ControllerTimelineCommandProvider,
    ControllerAskUserProvider,
    ControllerReadProvider,
    ControllerFinishProvider,
    ControllerUncertaintyProvider,
    ControllerSingleSegmentTimeProvider,
    ControllerCandidateSelectionProvider,
    ControllerSingleDayRouteProvider,
    ControllerComplexPatchProvider,
    ModelOwnedMultiCycleInitialProvider,
    ModelOwnedDraftResolvePatchProvider,
    ControllerMemoryProvider,
    FakeProvider,
    StagedInitialProvider,
    ControllerStagedInitialProvider,
    ScriptedDeepSeekProvider,
    ControllerComplexToolLoopProvider,
)


def test_creative_portfolio_timeout_fallback_keeps_explicit_soft_shortfall_pending(monkeypatch):
    clear_database()
    monkeypatch.setenv("AGENT_EXPERIENCE_GROUNDING_V2_MODE", "off")
    monkeypatch.setattr(AgentService, "_creative_portfolio_enabled", lambda _self, _context: True)
    original_pop_candidate = AgentService._pop_next_pool_candidate_score

    def keep_soft_meal_in_shared_universe(self, available_scores, itinerary_service, intent, *args, **kwargs):
        if intent.intent_type == "meal":
            return None
        return original_pop_candidate(
            self,
            available_scores,
            itinerary_service,
            intent,
            *args,
            **kwargs,
        )

    monkeypatch.setattr(
        AgentService,
        "_pop_next_pool_candidate_score",
        keep_soft_meal_in_shared_universe,
    )
    text_search_keywords: list[str] = []
    acquired_text_search_keywords: list[str] = []
    denied_text_search_keywords: list[str] = []
    nearby_search_keywords: list[str] = []

    def portfolio_search(_self, city, keyword, category="all", limit=10):
        text_search_keywords.append(str(keyword))
        budget = current_amap_call_budget()
        if budget is not None and not budget.try_acquire(
            endpoint="place/text",
            keyword=str(keyword),
            category=str(category),
            source="test_creative_portfolio_text_search",
        ):
            denied_text_search_keywords.append(str(keyword))
            return MapPoiSearchResponse(
                city=city,
                keyword=keyword,
                category=category,
                providerName="fake-amap",
                queriedAt=datetime.now(timezone.utc),
                pois=[],
            )
        acquired_text_search_keywords.append(str(keyword))
        response = fake_amap_search_with_keyword_candidate(_self, city, keyword, category, limit)
        keyword_text = str(keyword)
        for poi in response.pois:
            if any(marker in keyword_text for marker in ("博物馆", "美术馆")):
                poi.id = "B0MUSEUM01"
                poi.name = "北京测试博物馆"
                poi.type = "科教文化服务;博物馆"
                poi.provider_type_code = "140100"
            elif any(marker in keyword_text for marker in ("大学", "学院", "高等院校", "校区", "高校")):
                campus_identity = next(
                    (
                        identity
                        for marker, identity in (
                            ("清华", ("B0CAMPUS01", 116.3260, 40.0030)),
                            ("北京大学", ("B0CAMPUS02", 116.3050, 39.9920)),
                            ("人民大学", ("B0CAMPUS03", 116.3170, 39.9700)),
                            ("航空航天", ("B0CAMPUS04", 116.3480, 39.9820)),
                        )
                        if marker in keyword_text
                    ),
                    ("B0CAMPUS05", 116.3380, 39.9870),
                )
                poi.id, poi.longitude, poi.latitude = campus_identity
                poi.provider_type_code = "141201"
                poi.type = "科教文化服务;学校;高等院校"
            elif any(marker in keyword_text for marker in ("奥林匹克塔", "中信大厦", "夜景", "观景", "夜游", "灯光")):
                if "中信大厦" in keyword_text:
                    poi.id = "B0NIGHT002"
                    poi.longitude = 116.4590
                    poi.latitude = 39.9130
                else:
                    poi.id = "B0NIGHT001"
                    poi.longitude = 116.3940
                    poi.latitude = 40.0030
                poi.type = "风景名胜;观景点"
                poi.provider_type_code = "110000"
            elif any(marker in keyword_text for marker in ("艺术", "创意", "画廊", "设计")):
                poi.id = "B0ARTPARK01"
                poi.name = "北京测试艺术园区"
                poi.type = "风景名胜;风景名胜相关;旅游景点"
                poi.tags = ["艺术园区", "展览"]
                poi.source_claims = [
                    {
                        "claimKey": "art_context",
                        "stance": "support",
                        "sourceName": "测试文旅详情",
                    }
                ]
            elif any(marker in keyword_text for marker in ("历史", "古迹", "老街", "文化街区", "传统建筑")):
                poi.id = "B0HERITAGE01"
                poi.name = "北京测试历史街区"
