    class TimeoutCreativePortfolioProvider(ControllerStagedInitialProvider):
        def generate_initial_portfolio(self, _context, *, repair_feedback=""):
            raise TimeoutError("creative portfolio timed out")

    timeout_payload = two_day_initial_day_slot_output()
    timeout_payload["daySlots"].append(
        {
            "slotId": "day1_local_museum",
            "dayNumber": 1,
            "date": "2026-10-01",
            "timeWindow": "16:15-18:00",
            "startTime": "16:15",
            "durationMinutes": 105,
            "kind": "museum",
            "rawNeed": "北京本地博物馆",
            "routeAnchor": True,
            "priority": 80,
            "notes": "显式必选博物馆 occurrence。",
        }
    )
    timeout_payload["intentPools"].append(
        {
            "poolId": "local_museum_pool",
            "rawNeed": "北京本地博物馆",
            "city": "北京",
            "intentType": "museum",
            "targetCount": 1,
            "preferredTypes": ["博物馆", "美术馆"],
            "rejectedTypes": ["酒店", "公司", "住宅"],
            "routePreference": {"sameDayUnique": True},
            "assignToSlots": ["day1_local_museum"],
            "candidateHints": ["北京本地博物馆"],
            "hintPolicy": "user_explicit_hint",
        }
    )
    provider = TimeoutCreativePortfolioProvider(timeout_payload)
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "portfolio timeout fallback")
        service = AgentService(
            connection,
            provider=provider,
            poi_resolution_service=FakePoiResolver({}),
        )
        service.experience_grounding_v2_mode = "off"
        response = service.send_message(
            session.session_id,
            AgentMessageRequest(
                content=route_ready_request(
                    "今年国庆参观985大学两日游，然后去体验北京当地博物馆。"
                    "10月1日到2日，中等预算，1人，路途中品尝北京当地特色美食"
                )
            ),
        )

        latest_run = connection.execute(
            "SELECT tool_calls_json FROM planning_runs ORDER BY created_at DESC LIMIT 1"
        ).fetchone()
        persisted_tool_calls = json.loads(latest_run[0]) if latest_run else []
        planning_tool_call_summary = [
            {
                "id": item.get("id"),
                "status": item.get("status"),
                "failureReason": item.get("failureReason"),
                "detail": item.get("detail"),
                "traceSummary": item.get("traceSummary"),
            }
            for item in persisted_tool_calls
        ]
        controller_failure_summary = [
            {
                "controllerError": item.metadata.get("controllerError"),
                "failureClass": item.metadata.get("controllerFailureClass"),
            }
            for item in response.planning_steps
            if item.type == "agent_decision" and item.metadata.get("controllerError")
        ]
        assert response.terminal_status == "needs_confirmation", {
            "warnings": response.warnings,
            "planningToolCalls": planning_tool_call_summary,
            "controllerFailures": controller_failure_summary,
            "portfolioSteps": [
                {
                    "type": item.type,
                    "status": item.status,
                    "detail": item.detail,
                    "failureReason": item.failure_reason,
                    "metadata": item.metadata,
                }
                for item in response.planning_steps
                if "portfolio" in item.type or item.status == "failed"
            ],
        }
        assert response.version is None
        assert response.itinerary is None
        proposal_options = [
            item for item in response.assistant_turn.choice_options if item["action"] == "select_plan_proposal"
        ]
        assert len(proposal_options) == 1, {
            "warnings": response.warnings,
            "content": response.assistant_turn.content,
            "choices": response.assistant_turn.choice_options,
            "planningToolCalls": planning_tool_call_summary,
            "controllerFailures": controller_failure_summary,
            "portfolioSteps": [
                {
                    "type": item.type,
                    "status": item.status,
                    "detail": item.detail,
                    "failureReason": item.failure_reason,
                    "metadata": item.metadata,
                }
                for item in response.planning_steps
                if "portfolio" in item.type or item.status == "failed"
            ],
        }
        comparison_projection = proposal_options[0]["comparisonProjection"]
        assert comparison_projection["adoptionReady"] is True
        assert comparison_projection["adoptionMode"] == "editable_draft"
        assert comparison_projection["pendingHardSlotCount"] == 0
        assert comparison_projection["pendingSoftSlotCount"] == 2
        assert comparison_projection["nextAction"] == "adopt_proposal"
        assert any(item["action"] == "retry_model_planning" for item in response.assistant_turn.choice_options)
        proposal_row = connection.execute("SELECT status, verifier_json FROM agent_plan_proposals").fetchone()
        assert proposal_row is not None
        assert proposal_row["status"] == "adoption_ready"
        stored_verifier = json.loads(proposal_row["verifier_json"])
        assert stored_verifier["draftPassed"] is True
        assert stored_verifier["pendingHardSlotCount"] == 0
        assert stored_verifier["pendingSoftSlotCount"] == 2
        collect_step = next(item for item in response.planning_steps if item.type == "collect_candidates")
        meal_reports = [
            report
            for report in collect_step.metadata["resultPreview"]["poolReports"]
            if report.get("intentType") == "meal"
        ]
        assert meal_reports
        assert meal_reports[0]["selectedCount"] == 0
        assert len(meal_reports[0]["safeCandidates"]) >= 2
        assert connection.execute("SELECT count(*) FROM itinerary_versions").fetchone()[0] == 0
        assert connection.execute("SELECT count(*) FROM itinerary_patches").fetchone()[0] == 0
        assert connection.execute("SELECT count(*) FROM route_options").fetchone()[0] == 0
        fallback_events = [
            item for item in json.loads(latest_run[0]) if item.get("id") == "creative_portfolio_provider"
        ]
        assert fallback_events[-1]["status"] == "fallback"
        provider_trace = next(
            item["traceSummary"] for item in persisted_tool_calls if item.get("id") == "creative_portfolio_provider"
        )
        staging_trace = next(
            item["traceSummary"] for item in persisted_tool_calls if item.get("id") == "portfolio_staging_performance"
        )
        assert provider_trace["providerCallCount"] >= 1
        assert provider_trace["sequence"] >= 1
        assert staging_trace["briefMetrics"]
        assert all(item.get("briefId") for item in staging_trace["briefMetrics"])
        assert all("traceSummary" not in item for item in response.planning_run.model_dump(by_alias=True)["toolCalls"])
        session_row = connection.execute(
            "SELECT * FROM conversation_sessions WHERE id = ?",
            (session.session_id,),
        ).fetchone()
        reloaded_run = ConversationService(connection)._latest_planning_run(session_row)
        # A proposal-only turn has no active plan/version, so session-level
        # planning-run hydration intentionally remains empty before selection.
        assert reloaded_run is None
        # A food-led variant whose optional slot cannot fit its compiled hard
        # window is intentionally absent. Family-specific experience searches
        # must stay within the same bounded AMap budget.
        family_query_markers = (
            "历史街区",
            "社区生活",
            "市场",
            "艺术街区",
            "创意园区",
            "公园休憩",
        )
        assert not any(
            any(marker in keyword for marker in ("美食", "餐饮", "小吃", *family_query_markers))
            for keyword in denied_text_search_keywords
        )
        assert len(acquired_text_search_keywords) <= 8
        assert len(acquired_text_search_keywords) + len(nearby_search_keywords) <= 16
        build_step = next(item for item in response.planning_steps if item.type == "build_persistable_segment_plans")
        build_preview = build_step.metadata["resultPreview"]
        assert build_preview["routeAnchorRequiredCount"] == 5
        assert [
            (item["dayNumber"], item["requiredRouteAnchors"], item["selectedRouteAnchors"])
            for item in build_preview["dayReadiness"]
        ] == [(1, 3, 2), (2, 2, 2)]
        assert build_preview["qualityContract"]["qualityStatus"] == "portfolio_staging_read_only"
        optional_reports = [
            report
            for report in collect_step.metadata["resultPreview"]["poolReports"]
            if report.get("priorityClass") == "optional_creative"
        ]
        assert optional_reports
        assert any(
            int(report.get("usedPlaceTextCalls") or 0) > 0 or report.get("reusedNetworkEvidence") is True
            for report in optional_reports
        )


