def test_reused_required_primary_evidence_is_rechecked_per_exact_entity():
    candidates = [
        POI(
            id="pku",
            amap_id="pku",
            name="北京大学",
            type="科教文化服务;学校;高等院校",
            city="北京",
            district="海淀区",
            address="颐和园路5号",
            category="campus",
            latitude=39.9929,
            longitude=116.3109,
            source=AMAP_PLACE_SOURCE,
            confidence=0.9,
        ),
        POI(
            id="thu",
            amap_id="thu",
            name="清华大学",
            type="科教文化服务;学校;高等院校",
            city="北京",
            district="海淀区",
            address="双清路30号",
            category="campus",
            latitude=40.0032,
            longitude=116.3269,
            source=AMAP_PLACE_SOURCE,
            confidence=0.9,
        ),
    ]
    with open_db() as connection:
        service = AgentService(connection)
        pku = service._required_primary_result_for_intent(
            PoiIntent(
                raw_need="北京大学",
                city="北京",
                day_number=1,
                time_window="morning",
                intent_type="campus_visit",
                specificity="exact_entity",
                entity_binding_mode="exact_entity",
                exact_entity="北京大学",
            ),
            candidates,
            provider_state="ok",
            collection_stats=[],
            primary_queries=["北京 大学"],
            reused_network_evidence=False,
        )
        thu = service._required_primary_result_for_intent(
            PoiIntent(
                raw_need="清华大学",
                city="北京",
                day_number=1,
                time_window="morning",
                intent_type="campus_visit",
                specificity="exact_entity",
                entity_binding_mode="exact_entity",
                exact_entity="清华大学",
            ),
            candidates,
            provider_state="ok",
            collection_stats=[],
            primary_queries=["北京 大学"],
            reused_network_evidence=True,
        )

    assert [item.amap_id for item in pku["candidates"]] == ["pku"]
    assert [item.amap_id for item in thu["candidates"]] == ["thu"]
    assert thu["reusedNetworkEvidence"] is True


