def test_portfolio_candidate_claim_requires_full_brief_pool_and_slot_lineage():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "portfolio lineage claim")
        payloads = {
            "cand_wrong_lineage": {
                "id": "poi_shared",
                "amapId": "poi_shared",
                "briefId": "brief_other",
                "poolId": "pool_other",
                "sourceGoalId": "goal_museum",
                "planningSlotId": "slot_museum",
            },
            "cand_correct_lineage": {
                "id": "poi_shared",
                "amapId": "poi_shared",
                "briefId": "brief_selected",
                "poolId": "pool_selected",
                "sourceGoalId": "goal_museum",
                "planningSlotId": "slot_museum",
            },
        }
        for candidate_id, candidate in payloads.items():
            connection.execute(
                """
                INSERT INTO amap_poi_candidates (
                    id, session_id, turn_id, query, segment_id, city, category, status,
                    candidates_json, selected_amap_id, created_at
                ) VALUES (?, ?, ?, ?, NULL, ?, ?, 'pending', ?, NULL, ?)
                """,
                (
                    candidate_id,
                    session.session_id,
                    "turn_portfolio_lineage",
                    "museum",
                    "北京",
                    "museum",
                    json.dumps([candidate]),
                    "2026-07-19T00:00:00+00:00",
                ),
            )
        connection.commit()

        claims = AgentService(connection)._claim_portfolio_snapshot_candidate_records(
            session_id=session.session_id,
            snapshot={
                "portfolioRequiredCandidateBindings": [
                    {
                        "amapId": "poi_shared",
                        "briefId": "brief_selected",
                        "poolId": "pool_selected",
                        "sourceGoalId": "goal_museum",
                        "planningSlotId": "slot_museum",
                    }
                ],
                "days": [{"segments": [{"poi": {"amapId": "poi_shared"}}]}],
            },
        )
        rows = connection.execute("SELECT id, status, selected_amap_id FROM amap_poi_candidates ORDER BY id").fetchall()

    assert claims == [("cand_correct_lineage", "pending", None)]
    assert [(row["id"], row["status"], row["selected_amap_id"]) for row in rows] == [
        ("cand_correct_lineage", "selected", "poi_shared"),
        ("cand_wrong_lineage", "pending", None),
    ]


