def test_density_refresh_and_expand_have_distinct_scoped_query_fingerprints() -> None:
    pool = IntentPool(
        pool_id="pool_meal",
        raw_need="沿途餐饮",
        city="北京",
        intent_type="meal",
        target_count=1,
        assign_to_slots=["slot_meal"],
    )
    slots = [
        DaySlot(
            slot_id="slot_meal",
            day_number=1,
            date="2026-10-01",
            time_window="12:00-13:15",
            start_time="12:00",
            duration_minutes=75,
            kind="meal",
            raw_need="沿途餐饮",
            route_anchor=True,
        )
    ]
    scope = {
        "briefId": "brief_food",
        "poolId": "pool_meal",
        "planningSlotId": "slot_meal",
        "dayNumber": 1,
    }
    base = {
        "portfolioDensityContinuation": {"briefId": "brief_food"},
        "candidateRefreshScopes": [scope],
    }
    refresh = {
        **base,
        "structuredRetry": {"retryMode": "refresh_candidates"},
        "forceCandidateRefresh": True,
    }
    expand = {
        **base,
        "structuredRetry": {"retryMode": "expand_nearby"},
        "expandDensityNearby": True,
    }

    refresh_fingerprint = AgentService._density_retry_query_fingerprint(refresh, pool, slots)
    expand_fingerprint = AgentService._density_retry_query_fingerprint(expand, pool, slots)

    assert refresh_fingerprint
    assert expand_fingerprint
    assert refresh_fingerprint != expand_fingerprint


