def test_material_candidate_evidence_preserves_hint_through_map_schema_rehydration() -> None:
    candidate = MapPoiResponse(
        id="B0LIANGMA",
        name="亮马河国际风情水岸",
        type="风景名胜;水域景观",
        city="北京",
        district="朝阳区",
        address="亮马河沿岸",
        longitude=116.471,
        latitude=39.952,
        category="scenic",
        source=AMAP_PLACE_SOURCE,
        sourceNote="来源：高德地图",
        confidence=0.94,
        photos=[],
    )
    object.__setattr__(candidate, "_trip_matched_hint", "亮马河夜游步道")
    object.__setattr__(candidate, "_trip_matched_hint_binding", "search_query")
    object.__setattr__(candidate, "_trip_semantic_passed", True)
    object.__setattr__(
        candidate,
        "_trip_exclusion_fingerprint",
        "f" * 64,
    )

    payload = AgentService._material_candidate_evidence_payload(
        candidate,
        source_goal_id="night",
        planning_slot_id="slot_night",
        pool_id="pool_night",
        brief_id="brief_focus",
        day_number=1,
        score=0.9,
    )
    assert payload is not None
    rehydrated = MapPoiResponse.model_validate(payload)
    assert payload["matchedCandidateHint"] == "亮马河夜游步道"
    assert payload["matchedCandidateHintBinding"] == "search_query"
    assert payload["semanticPassed"] is True
    assert payload["exclusionFingerprint"] == "f" * 64
    assert "matchedCandidateHint：亮马河夜游步道" in rehydrated.source_note
    assert "matchedCandidateHintBinding：search_query" in rehydrated.source_note
    assert AgentService._candidate_matched_hint(rehydrated) == "亮马河夜游步道"


