def test_optional_pool_lineage_does_not_promote_anchor_to_required_goal() -> None:
    connection = sqlite3.connect(":memory:")
    service = AgentService(connection)
    slot = DaySlot(
        slot_id="day2_optional_walk",
        day_number=2,
        date="2026-10-02",
        time_window="14:00-16:00",
        start_time="14:00",
        duration_minutes=120,
        kind="visit",
        raw_need="城市公园漫步",
        route_anchor=True,
    )
    poi = POI(
        id="poi_optional",
        amap_id="B0OPTIONAL",
        name="北京城市公园",
        city="北京",
        category="scenic",
        latitude=39.91,
        longitude=116.39,
        source=AMAP_PLACE_SOURCE,
        confidence=0.95,
        type="风景名胜;公园广场",
        source_note="来源：高德地图",
    )

    pipeline_context = {
        "requestIntentContract": {
            "requiredIntents": [
                {
                    "goalId": "goal_required_park",
                    "intentType": "park",
                    "requirementLevel": "required",
                }
            ]
        }
    }
    pool = IntentPool(
        pool_id="optional_walk_pool",
        brief_id="brief_optional",
        raw_need="城市公园漫步",
        city="北京",
        intent_type="park",
        target_count=1,
        requirement_level="optional",
        optional_experience_family="culture",
        assign_to_slots=[slot.slot_id],
    )
    source_goal_id = service._source_goal_id_for_pool(pool, pipeline_context)

    plan = service._route_anchor_segment_plan(
        slot,
        poi,
        ItineraryService(connection),
        pipeline_context,
        creative_brief_id=pool.brief_id,
        pool_id=pool.pool_id,
        source_goal_id=source_goal_id,
        source_requirement_level=pool.requirement_level,
    )

    assert source_goal_id == "pool_goal:optional_walk_pool"
    assert plan.source_goal_id == "pool_goal:optional_walk_pool"
    assert plan.goal_id is None
    assert plan.required is False
    assert plan.requirement_level == "optional"


