def test_materialize_portfolio_soft_segments_keeps_explicit_repeat_of_hard_goal():
    service = AgentService.__new__(AgentService)
    required_segment = {
        "id": "seg_required_campus_day_1",
        "startTime": "09:00",
        "endTime": "11:00",
        "poi": {"amapId": "B000CAMPUS1", "name": "清华大学"},
        "semanticMetadata": {
            "goalId": "goal_campus_visit",
            "sourceGoalId": "goal_campus_visit",
            "occurrenceId": "occ:goal_campus_visit:day:1:0",
            "requirementLevel": "required",
            "required": True,
        },
    }
    stale_soft_segment = {
        "id": "seg_stale_soft_campus_day_2",
        "startTime": "09:00",
        "endTime": "11:00",
        "poi": {"amapId": "B000STALE", "name": "旧候选"},
        "semanticMetadata": {
            "goalId": "goal_campus_visit",
            "sourceGoalId": "goal_campus_visit",
            "softGoalId": "goal_campus_visit",
            "occurrenceId": "occ:goal_campus_visit:day:2",
            "requirementLevel": "soft_experience",
            "required": False,
        },
    }
    snapshot = {
        "days": [
            {"dayNumber": 1, "segments": [required_segment]},
            {"dayNumber": 2, "segments": [stale_soft_segment]},
        ]
    }
    slot = SimpleNamespace(
        soft_goal_id="goal_campus_visit",
        day_number=2,
        time_window="09:00-11:00",
        start_time="09:00",
        duration_minutes=120,
        kind="visit",
        raw_need="北京高校参观",
        slot_id="campus_day_2_soft_slot",
    )
    skeleton = SimpleNamespace(
        brief=SimpleNamespace(brief_id="brief_a"),
        day_slots=[slot],
    )
    ledger = SimpleNamespace(
        hard_goals=[SimpleNamespace(goal_id="goal_campus_visit", intent_type="campus_visit")],
        soft_goals=[],
    )
    candidate = {
        "amapId": "B000CAMPUS2",
        "name": "北京大学",
        "city": "北京",
        "category": "campus",
        "providerType": "科教文化服务;学校;高等院校",
        "longitude": 116.31,
        "latitude": 39.99,
        "source": "amap-place-search",
        "confidence": 0.95,
        "sourceGoalId": "goal_campus_visit",
        "softGoalId": "goal_campus_visit",
        "briefId": "brief_a",
        "poolId": "campus_day_2_soft_pool",
        "planningSlotId": "campus_day_2_soft_slot",
        "dayNumber": 2,
        "occurrenceId": "occ:goal_campus_visit:day:2",
        "consumerAdmissionReport": {"schemaVersion": "consumer-candidate-admission-v2"},
    }

    service._materialize_portfolio_soft_segments(
        snapshot,
        skeleton=skeleton,
        ledger=ledger,
        soft={"occ:goal_campus_visit:day:2": candidate},
    )

    day_1_segments = snapshot["days"][0]["segments"]
    day_2_segments = snapshot["days"][1]["segments"]
    assert day_1_segments == [required_segment]
    assert len(day_2_segments) == 1
    assert day_2_segments[0]["poi"]["amapId"] == "B000CAMPUS2"
    assert day_2_segments[0]["semanticMetadata"]["sourceGoalId"] == "goal_campus_visit"
    assert day_2_segments[0]["semanticMetadata"]["occurrenceId"] == "occ:goal_campus_visit:day:2"
    assert day_2_segments[0]["semanticMetadata"]["requirementLevel"] == "soft_experience"
    assert day_2_segments[0]["semanticMetadata"]["consumerAdmissionReport"] == {
        "schemaVersion": "consumer-candidate-admission-v2"
    }


def test_deterministic_fallback_culture_optional_slots_all_materialize_with_hard_museum():
    ledger = ConstraintLedger.model_validate(
        {
            "schemaVersion": "constraint-ledger-v1",
            "city": "北京",
            "dayCount": 1,
            "hardGoals": [
                {"goalId": "museum", "intentType": "museum", "requiredMin": 1},
            ],
            "sourceFingerprint": "fallback-materialization-test-fingerprint",
        }
    )
    fallback = CreativePortfolioProviderService().deterministic_fallback(
        ledger=ledger,
        directive={
            "dayStrategies": [
                {
                    "dayNumber": 1,
                    "requiredGoalIds": ["museum"],
                    "requiredGoalCounts": {"museum": 1},
                    "optionalGoalIds": [],
                    "maxRouteAnchors": 3,
                }
            ]
        },
        schema_repair_attempts=0,
    )
    culture = next(proposal for proposal in fallback.proposals if proposal.brief.primary_axis == "culture_deep_dive")
    museum_segment = {
        "id": "seg_museum",
        "startTime": "09:00",
        "endTime": "11:00",
        "poi": amap_poi_snapshot(
            "poi_museum",
            "中国国家博物馆",
            "B000MUSEUM",
            116.397,
            39.903,
        ),
        "semanticMetadata": {
            "sourceGoalId": "museum",
            "requirementLevel": "required",
            "required": True,
            "routeAnchor": True,
        },
    }
    snapshot = {"days": [{"dayNumber": 1, "segments": [museum_segment]}]}
    optional_slots = sorted(
        (slot for slot in culture.day_slots if slot.optional_experience_family is not None),
        key=lambda slot: str(slot.optional_experience_family),
    )
    optional_candidates = [
        {
            "amapId": f"B000OPTIONAL{index}",
            "name": f"可选文化体验 {index}",
            "city": "北京",
            "category": "scenic",
            "providerType": "风景名胜;人文景观",
            "longitude": 116.40 + index / 100,
            "latitude": 39.90 + index / 100,
            "source": "amap-place-search",
            "confidence": 0.95,
            "optionalExperienceFamily": slot.optional_experience_family,
            "dayNumber": slot.day_number,
            "timeWindow": slot.time_window,
            "startTime": slot.start_time,
            "durationMinutes": slot.duration_minutes,
            "intentType": slot.kind,
            "planningSlotId": slot.slot_id,
            "slotId": slot.slot_id,
            "assignToSlots": [slot.slot_id],
        }
        for index, slot in enumerate(optional_slots, start=1)
    ]

    AgentService.__new__(AgentService)._append_portfolio_optional_segments(
        snapshot,
        optional_candidates,
        culture.brief,
    )

    route_anchor_segments = [
        segment
        for segment in snapshot["days"][0]["segments"]
        if segment.get("semanticMetadata", {}).get("routeAnchor") is True
    ]
    assert len(route_anchor_segments) == 1 + len(optional_slots)
    assert {
        segment.get("semanticMetadata", {}).get("optionalExperienceFamily")
        for segment in route_anchor_segments
        if segment.get("semanticMetadata", {}).get("portfolioOptional") is True
    } == {str(slot.optional_experience_family) for slot in optional_slots}


def test_trusted_portfolio_focus_prefers_checkpoint_and_rejects_unknown_values():
    selected = AgentService._trusted_portfolio_focus_brief_id(
        continuation=None,
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "brief_checkpoint"},
        request_context={"portfolioGroundingFocusBriefId": "brief_client"},
        generated_brief_ids=["brief_client", "brief_checkpoint"],
    )
    fallback = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_unknown"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "brief_also_unknown"},
        request_context={"portfolioGroundingFocusBriefId": "brief_client_unknown"},
        generated_brief_ids=["brief_first", "brief_second"],
    )
    authorized_expansion = AgentService._trusted_portfolio_focus_brief_id(
        continuation=None,
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "brief_checkpoint"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
            "partialPlanExpansionFocusMode": "exact",
            "portfolioGroundingFocusBriefId": "brief_client",
        },
        generated_brief_ids=["brief_checkpoint", "brief_next"],
        authorized_expansion_focus_brief_id="brief_next",
    )

    authorized_expansion_with_stale_continuation = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_checkpoint"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "brief_checkpoint"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
            "partialPlanExpansionFocusMode": "exact",
            "portfolioGroundingFocusBriefId": "brief_checkpoint",
        },
        generated_brief_ids=["brief_checkpoint", "brief_next"],
        authorized_expansion_focus_brief_id="brief_next",
    )
    authorized_expansion_with_provider_drift = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_checkpoint"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "provider_x"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
        },
        generated_brief_ids=["provider_x"],
        authorized_expansion_focus_brief_id="brief_next",
    )
    authorized_cursor_with_provider_drift = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_checkpoint"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "provider_x"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
        },
        generated_brief_ids=["provider_x"],
        authorized_expansion_focus_brief_id="brief_checkpoint",
    )
    authorized_discovery = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_checkpoint"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "provider_x"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
            "partialPlanExpansionFocusMode": "discover_next",
            "partialPlanExpansionClaim": {
                "focusBriefId": "brief_checkpoint",
                "requestedFocusBriefId": "brief_checkpoint",
                "resolvedFocusBriefId": "provider_x",
            },
        },
        generated_brief_ids=["provider_x"],
        authorized_expansion_focus_brief_id="provider_x",
    )
    authorized_discovery_from_moving_display_focus = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "last_visible_brief"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "provider_y"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "partial_timeline_brief",
            "partialPlanExpansionFocusMode": "discover_next",
            "partialPlanExpansionClaim": {
                "focusBriefId": "last_visible_brief",
                "requestedFocusBriefId": "last_visible_brief",
                "resolvedFocusBriefId": "provider_y",
            },
        },
        generated_brief_ids=["provider_y"],
        authorized_expansion_focus_brief_id="provider_y",
    )
    authorized_expansion_without_next = AgentService._trusted_portfolio_focus_brief_id(
        continuation={"briefId": "brief_checkpoint"},
        grounding_pipeline_context={"portfolioGroundingFocusBriefId": "brief_checkpoint"},
        request_context={
            "_partialPlanExpansionAuthorized": True,
            "activePartialFocusBriefId": "brief_checkpoint",
            "partialPlanExpansionFocusMode": "discover_next",
            "partialPlanExpansionClaim": {
                "focusBriefId": "brief_checkpoint",
                "requestedFocusBriefId": "brief_checkpoint",
                "resolvedFocusBriefId": "brief_checkpoint",
            },
        },
        generated_brief_ids=["brief_checkpoint"],
        authorized_expansion_focus_brief_id="brief_checkpoint",
    )
    assert selected == "brief_checkpoint"
    assert fallback == "brief_first"
    assert authorized_expansion == "brief_next"
    assert authorized_expansion_with_stale_continuation == "brief_next"
    assert authorized_expansion_with_provider_drift == ""
    assert authorized_cursor_with_provider_drift == ""
    assert authorized_discovery == "provider_x"
    assert authorized_discovery_from_moving_display_focus == "provider_y"
    assert authorized_expansion_without_next == ""


