def test_partial_expansion_cursor_uses_authoritative_frontier_not_empty_next_brief():
    continuing = AgentService._classify_partial_expansion_cursor(
        succeeded=False,
        resolved_focus_brief_id="fallback_4_local_immersion",
        resolved_brief_status="failed",
        next_brief_id="",
        frontier={
            "frontierState": "has_more",
            "remainingBudget": 10,
            "continuationRound": 2,
            "limits": {"maxContinuationRoundsPerRoot": 4},
        },
    )
    exhausted = AgentService._classify_partial_expansion_cursor(
        succeeded=False,
        resolved_focus_brief_id="fallback_4_local_immersion",
        resolved_brief_status="failed",
        next_brief_id="",
        frontier={
            "frontierState": "budget_exhausted",
            "remainingBudget": 0,
            "continuationRound": 4,
            "limits": {"maxContinuationRoundsPerRoot": 4},
        },
    )

    assert continuing == {
        "cursorAdvanced": True,
        "cursorExhausted": False,
        "boundedAttemptConsumed": True,
        "continuationFocusMode": "discover_next",
    }
    assert exhausted == {
        "cursorAdvanced": False,
        "cursorExhausted": True,
        "boundedAttemptConsumed": True,
        "continuationFocusMode": None,
    }

    transient = AgentService._classify_partial_expansion_cursor(
        succeeded=False,
        resolved_focus_brief_id="fallback_4_local_immersion",
        resolved_brief_status="failed",
        next_brief_id="",
        frontier={"frontierState": "has_more", "remainingBudget": 10},
        failure_reason_codes=["provider_timeout"],
    )
    assert transient == {
        "cursorAdvanced": False,
        "cursorExhausted": False,
        "boundedAttemptConsumed": False,
        "continuationFocusMode": None,
    }


