    missing_focus = AgentService._portfolio_grounding_proposals(
        proposals,
        focus_brief_id="",
        expansion_authorized=True,
    )

    assert [item.brief.brief_id for item in initial] == ["brief_next", "brief_later"]
    assert [item.brief.brief_id for item in expansion] == ["brief_next"]
    assert missing_target == []
    assert missing_focus == []


