def test_portfolio_initial_auto_advance_is_limited_to_route_or_schedule_failures():
    route_failed = SimpleNamespace(failure_reason="portfolio_route_quality_unresolved:brief_1:meal_detour_high")
    schedule_failed = SimpleNamespace(failure_reason="portfolio_verifier_hard_failure:schedule")
    hard_goal_failed = SimpleNamespace(failure_reason="portfolio_verifier_hard_failure:required_goal_missing")

    assert AgentService._portfolio_initial_auto_advance_allowed(route_failed, {}) is True
    assert (
        AgentService._portfolio_initial_auto_advance_allowed(
            schedule_failed,
            {"perBriefDiagnostics": [{"hardFailures": ["schedule_window_latest_start_exceeded:optional_1"]}]},
        )
        is True
    )
    assert (
        AgentService._portfolio_initial_auto_advance_allowed(
            hard_goal_failed,
            {"perBriefDiagnostics": [{"hardFailures": ["required_goal_missing"]}]},
        )
        is False
    )


