def test_turn_response_projects_persisted_comparison_projections():
    clear_database()
    with open_db() as connection:
        session = ConversationService(connection).create_session("北京", "comparison projection replay")
        service = AgentService(connection, provider=SimpleNamespace())
        projection = {
            "planningSelectionRootTurnId": "turn_root",
            "rootPortfolioId": "portfolio_root",
            "proposalId": "partial-preview:portfolio_root:fallback_2_local_immersion",
            "sourceAssistantTurnId": "turn_assistant",
            "choiceId": "preview_partial_portfolio_root_fallback_2_local_immersion",
            "status": "partial_preview",
            "isPartial": True,
            "adoptionReady": False,
            "title": "本地沉浸（只读部分方案）",
            "days": [],
            "pendingSlots": [],
        }
        comparison_summary = {
            "adoptionReadyCount": 0,
            "repairablePartialCount": 1,
            "remainingQualifiedEntityCount": 7,
            "remainingPoiPageCount": 2,
            "frontierStatus": "has_more",
            "exploredQualifiedEntityCount": 1,
            "attemptedPoiPageCount": 3,
            "lastOutcomeReason": None,
            "blockingLayer": None,
        }
        turn_id = service._insert_turn(
            session.session_id,
            "assistant",
            "已追加 1 个只读部分方案",
            "active",
            agent_response_json={
                "comparisonProjectionUpdateMode": "append",
                "comparisonProjections": [projection],
                "planningSelectionRootTurnId": "turn_root",
                "rootPortfolioId": "portfolio_root",
                "comparisonSummary": comparison_summary,
            },
        )

        turn = service._turn_response(turn_id)
        session_turn = ConversationService(connection)._turns(session.session_id)[0]

    assert turn.comparison_projections == [projection]
    assert turn.model_dump(by_alias=True)["comparisonProjections"] == [projection]
    assert turn.comparison_projection_update_mode == "replace"
    assert turn.model_dump(by_alias=True)["comparisonProjectionUpdateMode"] == "replace"
    assert turn.model_dump(by_alias=True)["planningSelectionRootTurnId"] == "turn_root"
    assert turn.model_dump(by_alias=True)["rootPortfolioId"] == "portfolio_root"
    assert turn.model_dump(by_alias=True)["comparisonSummary"] == comparison_summary
    assert session_turn.comparison_projections == [projection]
    assert session_turn.model_dump(by_alias=True)["comparisonProjections"] == [projection]
    assert session_turn.model_dump(by_alias=True)["comparisonProjectionUpdateMode"] == "replace"
    assert session_turn.model_dump(by_alias=True)["planningSelectionRootTurnId"] == "turn_root"
    assert session_turn.model_dump(by_alias=True)["rootPortfolioId"] == "portfolio_root"
    assert session_turn.model_dump(by_alias=True)["comparisonSummary"] == comparison_summary


