@pytest.mark.parametrize(
    ("action", "method_name"),
    [
        ("confirm_portfolio_theme_upgrade", "_execute_theme_completion_confirmation"),
        ("confirm_portfolio_theme_replacement", "_execute_theme_completion_confirmation"),
        ("reject_portfolio_theme_replacement", "_execute_theme_replacement_rejection"),
    ],
)
def test_theme_completion_confirmation_actions_dispatch_to_authoritative_handlers(
    monkeypatch,
    action,
    method_name,
):
    service = object.__new__(AgentService)
    expected = object()
    captured = {}

    def handler(_self, **kwargs):
        captured.update(kwargs)
        return expected

    monkeypatch.setattr(AgentService, method_name, handler, raising=False)
    result = service._dispatch_selected_agent_choice(
        "session_dispatch",
        "turn_user_dispatch",
        "",
        object(),
        {"active_version_id": None},
        {"requestMarker": "server"},
        {
            "action": action,
            "persistedChoiceId": f"choice_{action}",
            "option": {"action": action},
        },
    )

    assert result is expected
    assert captured["session_id"] == "session_dispatch"
    assert captured["user_turn_id"] == "turn_user_dispatch"
    assert captured["selected_choice"]["action"] == action


