def test_request_contract_keeps_vague_city_center_unresolved_and_generic_evidence_contracts():
    clear_database()
    with open_db() as connection:
        service = AgentService(connection)
        generic_contract = service._request_intent_contract(
            "北京高校两日游，每天一顿当地特色美食。",
            {"dates": ["2026-10-01", "2026-10-02"]},
            SimpleNamespace(meal_slots=[SimpleNamespace(route_anchor=True)]),
            simple_open_profile=True,
        )
        contract = service._request_intent_contract(
            "高校指的是985大学，每天一顿当地特色美食，行程安排最好在北京市中心附近。",
            {"dates": ["2026-10-01", "2026-10-02"]},
            SimpleNamespace(meal_slots=[SimpleNamespace(route_anchor=True)]),
            simple_open_profile=True,
        )

    assert generic_contract["hardConstraints"] == []
    assert generic_contract["entityQualificationConstraint"] is None
    spatial = contract["spatialPreference"]
    assert spatial["status"] == "unresolved"
    assert spatial["strength"] == "preferred"
